import { useEffect, useMemo, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { audio } from '@/engine/audioEngine';
import { useGame } from '@/engine/store';
import {
  type PhoneEvent,
  type PhoneReply,
  type PhoneLogEntry,
  resolveCallerLabel,
  getVisibleReplies,
} from '@/data/phoneEvents';
import { Phone, PhoneOff, PhoneCall, MessageSquare, X, Reply } from 'lucide-react';

// Phone Trigger — Steins;Gate-inspired phone-call / message device.
// On certain scenes the player's phone rings or receives a message. The
// player can answer (calls) or read (messages); missed calls are logged in
// the Codex's "Calls" tab for later review. Calls that carry grantsClue
// deliver that clue on answer, making the phone an alternate clue channel.
//
// Steins;Gate reply choices: events may carry `replies` — a small set of
// player responses that branch the conversation. After answering a call or
// opening a message that has replies, the device shows reply buttons. The
// player picks one; the caller responds, game-state actions apply (trust
// swings, sanity, flags), and any reply-level clue is delivered. The phone
// log records the chosen reply so the Codex shows the full conversation.
//
// The device renders as a small floating widget in the lower-right corner
// so it layers over normal dialogue without blocking the speaker. It
// intentionally does NOT pause the game — the phone is a punctuative
// device, not a modal. The player can ignore it and the call will be
// logged as missed when they leave the scene.
//
// Lifecycle:
//   ringing -> (answer | decline | auto-miss-on-scene-change)
//   answered -> [replies?] -> (pick reply) -> replied -> (dismiss)
//             -> [no replies] -> (dismiss)
//   message -> notify -> open -> [replies?] -> (pick reply) -> replied -> (dismiss)
//                                  -> [no replies] -> (dismiss)

type Phase = 'ringing' | 'answered' | 'replied' | 'done';

interface Props {
  event: PhoneEvent;
  onClose: () => void; // called when the device is dismissed / auto-missed
}

export default function PhoneDevice({ event, onClose }: Props) {
  const isCall = event.kind === 'call';
  const loopCount = useGame((s) => s.loopCount);
  const flags = useGame((s) => s.flags);
  const retainedClues = useGame((s) => s.retainedClues);
  const recordPhoneLog = useGame((s) => s.recordPhoneLog);
  const addClue = useGame((s) => s.addClue);
  const applyGameActions = useGame((s) => s.applyGameActions);

  const [phase, setPhase] = useState<Phase>('ringing');
  // For messages we auto-open the body after a short ring notification, so
  // the player sees a "new message" ping before the content slides in.
  const [messageOpen, setMessageOpen] = useState(false);
  // The reply the player picked, if any — surfaced in the replied phase and
  // recorded in the phone log on dismiss.
  const [chosenReply, setChosenReply] = useState<PhoneReply | null>(null);
  // Clues delivered during this phone event (event-level + reply-level) so
  // the UI can show a "clue delivered" indicator for each.
  const [deliveredClues, setDeliveredClues] = useState<string[]>([]);
  const resolvedRef = useRef(false);

  const callerLabel = resolveCallerLabel(event.from);

  // Visible replies for this event, gated by flags / retained clues / loop
  // count. Computed once per render so hidden replies (e.g. a second-loop
  // "I remember you" line) appear only when earned.
  const visibleReplies = useMemo(
    () => getVisibleReplies(event, { flags, retainedClues, loopCount }),
    [event, flags, retainedClues, loopCount],
  );
  const hasReplies = visibleReplies.length > 0;

  // Start the ringtone when the device mounts (calls only). Messages play
  // a single soft chime instead of a loop.
  useEffect(() => {
    if (isCall) {
      audio.playSFX('phone_ring');
    } else {
      audio.playSFX('chime');
      // Auto-open the message body after a brief notification beat.
      const t = window.setTimeout(() => setMessageOpen(true), 900);
      return () => window.clearTimeout(t);
    }
    // Stop ringtone on unmount (covers scene transitions while ringing).
    return () => {
      audio.stopPhoneRing();
    };
  }, [isCall]);

  // Deliver a clue (event-level or reply-level) exactly once. Idempotent —
  // addClue itself dedupes, but we also track locally so the UI indicator
  // does not flicker on re-render.
  const deliverClue = (clue?: string) => {
    if (!clue || deliveredClues.includes(clue)) return;
    addClue(clue);
    setDeliveredClues((prev) => [...prev, clue]);
    // Distinct chime so the clue delivery reads as a discovery, not a call.
    window.setTimeout(() => audio.playSFX('chime'), 250);
  };

  // Record the phone event in the log exactly once. Captures the chosen
  // reply (if any) so the Codex shows the full conversation. Guarded by
  // resolvedRef so a double-click can't create duplicate log entries.
  const resolve = (
    status: PhoneLogEntry['status'],
    reply: PhoneReply | null = chosenReply,
  ) => {
    if (resolvedRef.current) return;
    resolvedRef.current = true;

    const entry: PhoneLogEntry = {
      id: event.id,
      kind: event.kind,
      from: callerLabel,
      text: event.text,
      status,
      loopCount,
      ts: Date.now(),
      chosenReply: reply?.text,
      replyResponse: reply?.responseText,
    };
    recordPhoneLog(entry);
  };

  // --- Call handlers ------------------------------------------------------
  const handleAnswer = () => {
    if (phase !== 'ringing') return;
    audio.playSFX('phone_pickup');
    setPhase('answered');
    // For events WITHOUT replies, resolve immediately on answer — this
    // grants the event clue and records the log (the dismiss is just UI).
    // For events WITH replies, defer: the event clue is delivered now, but
    // the log is recorded on dismiss so it can capture the chosen reply.
    if (!hasReplies) {
      if (event.grantsClue) {
        deliverClue(event.grantsClue);
      }
      resolve('answered', null);
    } else {
      // Reply event: deliver the event clue on answer (the player has
      // connected and heard the line), defer log to dismiss.
      if (event.grantsClue) deliverClue(event.grantsClue);
    }
  };

  const handleDecline = () => {
    if (phase !== 'ringing') return;
    audio.playSFX('phone_busy');
    setPhase('done');
    resolve('declined', null);
    // Brief beat so the decline SFX lands before the widget closes.
    window.setTimeout(onClose, 400);
  };

  // --- Reply handler (shared by calls + messages) ------------------------
  const handlePickReply = (reply: PhoneReply) => {
    if (phase !== 'answered') return;
    // Apply the reply's game-state actions (trust/sanity/flags) via the
    // store's shared pipeline. A soft click sells the tap; the caller's
    // response then slides in.
    audio.playSFX('click');
    if (reply.actions && reply.actions.length > 0) {
      applyGameActions(reply.actions);
    }
    if (reply.grantsClue) deliverClue(reply.grantsClue);
    setChosenReply(reply);
    setPhase('replied');
  };

  // --- Dismiss handlers ---------------------------------------------------
  const handleDismissAnswered = () => {
    // Reply event: record the log now (deferred from answer) so it captures
    // the chosen reply. For non-reply events the log was already recorded
    // on answer, so resolve is a guarded no-op.
    if (hasReplies) {
      resolve('answered', chosenReply);
    }
    setPhase('done');
    onClose();
  };

  const handleDismissReplied = () => {
    if (hasReplies) {
      resolve('answered', chosenReply);
    }
    setPhase('done');
    onClose();
  };

  const handleDismissMessage = () => {
    // Reply event: defer log to capture chosen reply. Non-reply: resolve on
    // dismiss (the player has now "read" the message).
    resolve('read', chosenReply);
    setPhase('done');
    onClose();
  };

  const handleOpenMessage = () => {
    setMessageOpen(true);
    // Reply messages: deliver the event clue on open (player has read it),
    // defer log to dismiss so it captures the chosen reply. Non-reply
    // messages: clue + log are handled on dismiss.
    if (hasReplies && event.grantsClue) {
      deliverClue(event.grantsClue);
    }
  };

  // Auto-miss: if the player leaves the scene while still ringing (or has
  // answered but not dismissed), we record the appropriate outcome. Calls
  // still ringing are missed; answered/replied calls are logged as answered
  // (with any chosen reply); messages are read.
  useEffect(() => {
    return () => {
      if (!resolvedRef.current) {
        if (isCall) {
          if (phase === 'ringing') resolve('missed', null);
          else resolve('answered', chosenReply);
        } else {
          resolve('read', chosenReply);
        }
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, chosenReply]);

  return (
    <AnimatePresence>
      {phase !== 'done' && (
        <motion.div
          initial={{ opacity: 0, x: 40, y: 20 }}
          animate={{ opacity: 1, x: 0, y: 0 }}
          exit={{ opacity: 0, x: 40, y: 20 }}
          transition={{ type: 'spring', stiffness: 320, damping: 28 }}
          className="fixed bottom-4 right-4 z-40 w-[300px] max-w-[calc(100vw-2rem)] md:w-[340px]"
          onClick={(e) => e.stopPropagation()}
        >
          {/* The device shell — a small dark slab with a red status edge,
              like an old phone's call screen. */}
          <div className="vn-panel relative overflow-hidden px-4 py-3.5">
            {/* Sweeping red edge to signal an active call / incoming message. */}
            <div className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-blood-bright to-transparent animate-pulse-slow" />

            {/* Ringing state — call */}
            {isCall && phase === 'ringing' && (
              <RingingCall
                callerLabel={callerLabel}
                onAnswer={handleAnswer}
                onDecline={handleDecline}
              />
            )}

            {/* Answered state — call snippet (+ replies if any) */}
            {isCall && phase === 'answered' && (
              <AnsweredCall
                callerLabel={callerLabel}
                text={event.text}
                deliveredClues={deliveredClues}
                replies={hasReplies ? visibleReplies : []}
                onPickReply={handlePickReply}
                onDismiss={handleDismissAnswered}
              />
            )}

            {/* Replied state — caller's response to the player's reply */}
            {isCall && phase === 'replied' && chosenReply && (
              <RepliedView
                callerLabel={callerLabel}
                playerLine={chosenReply.text}
                responseText={chosenReply.responseText}
                deliveredClues={deliveredClues}
                onDismiss={handleDismissReplied}
              />
            )}

            {/* Message — notification then body (+ replies if any) */}
            {!isCall && (
              <MessageView
                callerLabel={callerLabel}
                text={event.text}
                open={messageOpen}
                deliveredClues={deliveredClues}
                replies={hasReplies && messageOpen ? visibleReplies : []}
                onOpen={handleOpenMessage}
                onPickReply={handlePickReply}
                onDismiss={handleDismissMessage}
              />
            )}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// --- Sub-views -------------------------------------------------------------

function RingingCall({
  callerLabel,
  onAnswer,
  onDecline,
}: {
  callerLabel: string;
  onAnswer: () => void;
  onDecline: () => void;
}) {
  return (
    <div>
      <div className="mb-2.5 flex items-center gap-2">
        <motion.span
          animate={{ scale: [1, 1.15, 1], opacity: [0.7, 1, 0.7] }}
          transition={{ duration: 1.2, repeat: Infinity, ease: 'easeInOut' }}
        >
          <PhoneCall size={14} className="text-blood-bright" />
        </motion.span>
        <span className="font-mono text-[9px] uppercase tracking-[0.35em] text-blood-bright animate-pulse">
          Incoming Call
        </span>
        <span className="ml-auto font-mono text-[8px] uppercase tracking-wider text-muted/60">
          ringing...
        </span>
      </div>
      <div className="mb-3 flex items-baseline gap-2">
        <span className="font-mono text-xs uppercase tracking-[0.2em] text-bone">
          {callerLabel}
        </span>
      </div>
      <div className="flex gap-2">
        <motion.button
          whileHover={{ scale: 1.03 }}
          whileTap={{ scale: 0.97 }}
          onClick={onAnswer}
          className="vn-choice flex flex-1 items-center justify-center gap-1.5 px-3 py-2 font-mono text-[10px] uppercase tracking-[0.25em] text-bone hover:text-white"
        >
          <Phone size={11} /> Answer
        </motion.button>
        <motion.button
          whileHover={{ scale: 1.03 }}
          whileTap={{ scale: 0.97 }}
          onClick={onDecline}
          className="flex items-center justify-center gap-1.5 border border-ash/60 px-3 py-2 font-mono text-[10px] uppercase tracking-[0.25em] text-muted transition-colors hover:border-blood hover:text-blood-bright"
        >
          <PhoneOff size={11} /> Decline
        </motion.button>
      </div>
    </div>
  );
}

function ClueDeliveredBadge({ clues }: { clues: string[] }) {
  if (clues.length === 0) return null;
  return (
    <motion.div
      initial={{ opacity: 0, y: 4 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.4 }}
      className="mb-2.5 border-l-2 border-blood-bright/70 bg-blood/5 px-2.5 py-1.5"
    >
      <span className="font-mono text-[8px] uppercase tracking-[0.3em] text-blood-bright">
        ◊ clue{clues.length > 1 ? 's' : ''} delivered
      </span>
    </motion.div>
  );
}

function AnsweredCall({
  callerLabel,
  text,
  deliveredClues,
  replies,
  onPickReply,
  onDismiss,
}: {
  callerLabel: string;
  text: string;
  deliveredClues: string[];
  replies: PhoneReply[];
  onPickReply: (reply: PhoneReply) => void;
  onDismiss: () => void;
}) {
  return (
    <div>
      <div className="mb-2 flex items-center gap-2">
        <Phone size={12} className="text-blood-bright" />
        <span className="font-mono text-[9px] uppercase tracking-[0.35em] text-blood-bright/80">
          Connected
        </span>
        <span className="ml-auto font-mono text-[10px] uppercase tracking-[0.2em] text-bone">
          {callerLabel}
        </span>
        {replies.length === 0 && (
          <button
            onClick={onDismiss}
            className="text-muted transition-colors hover:text-bone"
            aria-label="End call"
          >
            <X size={13} />
          </button>
        )}
      </div>
      <p className="mb-3 font-serif text-sm italic leading-relaxed text-bone/90 fx-whisper">
        {text}
      </p>
      <ClueDeliveredBadge clues={deliveredClues} />
      {replies.length > 0 ? (
        <ReplyList replies={replies} onPick={onPickReply} />
      ) : (
        <button
          onClick={onDismiss}
          className="vn-choice flex w-full items-center justify-center gap-1.5 px-3 py-1.5 font-mono text-[10px] uppercase tracking-[0.25em] text-muted hover:text-bone"
        >
          End Call
        </button>
      )}
    </div>
  );
}

function RepliedView({
  callerLabel,
  playerLine,
  responseText,
  deliveredClues,
  onDismiss,
}: {
  callerLabel: string;
  playerLine: string;
  responseText: string;
  deliveredClues: string[];
  onDismiss: () => void;
}) {
  return (
    <div>
      <div className="mb-2 flex items-center gap-2">
        <Phone size={12} className="text-blood-bright" />
        <span className="font-mono text-[9px] uppercase tracking-[0.35em] text-blood-bright/80">
          Connected
        </span>
        <span className="ml-auto font-mono text-[10px] uppercase tracking-[0.2em] text-bone">
          {callerLabel}
        </span>
        <button
          onClick={onDismiss}
          className="text-muted transition-colors hover:text-bone"
          aria-label="End call"
        >
          <X size={13} />
        </button>
      </div>
      {/* The player's chosen reply, echoed back as "you said:" */}
      <div className="mb-2 border-l-2 border-muted/40 pl-2.5">
        <span className="block font-mono text-[8px] uppercase tracking-[0.3em] text-muted/70">
          you said
        </span>
        <p className="font-serif text-xs italic leading-relaxed text-bone/70">
          {playerLine}
        </p>
      </div>
      {/* The caller's response */}
      <p className="mb-3 font-serif text-sm italic leading-relaxed text-bone/90 fx-whisper">
        {responseText}
      </p>
      <ClueDeliveredBadge clues={deliveredClues} />
      <button
        onClick={onDismiss}
        className="vn-choice flex w-full items-center justify-center gap-1.5 px-3 py-1.5 font-mono text-[10px] uppercase tracking-[0.25em] text-muted hover:text-bone"
      >
        End Call
      </button>
    </div>
  );
}

function ReplyList({
  replies,
  onPick,
}: {
  replies: PhoneReply[];
  onPick: (reply: PhoneReply) => void;
}) {
  return (
    <div className="space-y-1.5">
      <div className="mb-1 flex items-center gap-1.5">
        <Reply size={10} className="text-blood-bright/70" />
        <span className="font-mono text-[8px] uppercase tracking-[0.3em] text-blood-bright/70">
          reply
        </span>
      </div>
      {replies.map((reply, i) => (
        <motion.button
          key={i}
          whileHover={{ scale: 1.01 }}
          whileTap={{ scale: 0.99 }}
          onClick={() => onPick(reply)}
          className="vn-choice block w-full px-3 py-2 text-left font-serif text-xs italic leading-relaxed text-bone/85 hover:text-white"
        >
          {reply.text}
        </motion.button>
      ))}
    </div>
  );
}

function MessageView({
  callerLabel,
  text,
  open,
  deliveredClues,
  replies,
  onOpen,
  onPickReply,
  onDismiss,
}: {
  callerLabel: string;
  text: string;
  open: boolean;
  deliveredClues: string[];
  replies: PhoneReply[];
  onOpen: () => void;
  onPickReply: (reply: PhoneReply) => void;
  onDismiss: () => void;
}) {
  if (!open) {
    // Collapsed notification — a single line teasing the sender.
    return (
      <button
        onClick={onOpen}
        className="flex w-full items-center gap-2 text-left"
      >
        <motion.span
          animate={{ scale: [1, 1.2, 1] }}
          transition={{ duration: 1.4, repeat: Infinity, ease: 'easeInOut' }}
        >
          <MessageSquare size={13} className="text-blood-bright" />
        </motion.span>
        <div className="flex-1">
          <span className="block font-mono text-[9px] uppercase tracking-[0.3em] text-blood-bright">
            New Message
          </span>
          <span className="block font-mono text-[10px] uppercase tracking-[0.2em] text-bone">
            {callerLabel}
          </span>
        </div>
        <span className="font-mono text-[8px] uppercase tracking-wider text-muted/60 animate-pulse">
          tap
        </span>
      </button>
    );
  }
  // Open message with replies: show body + reply list. The dismiss button
  // is hidden while replies are pending — the player must pick a reply or
  // (if they want to ignore) they can close via the X. We surface the X so
  // the player is never trapped, but the reply list is the primary path.
  return (
    <div>
      <div className="mb-2 flex items-center gap-2">
        <MessageSquare size={12} className="text-blood-bright" />
        <span className="font-mono text-[9px] uppercase tracking-[0.3em] text-blood-bright/80">
          Message
        </span>
        <span className="ml-auto font-mono text-[10px] uppercase tracking-[0.2em] text-bone">
          {callerLabel}
        </span>
        <button
          onClick={onDismiss}
          className="text-muted transition-colors hover:text-bone"
          aria-label="Close message"
        >
          <X size={13} />
        </button>
      </div>
      <p className="mb-3 font-serif text-sm italic leading-relaxed text-bone/90 fx-whisper">
        {text}
      </p>
      <ClueDeliveredBadge clues={deliveredClues} />
      {replies.length > 0 ? (
        <ReplyList replies={replies} onPick={onPickReply} />
      ) : (
        <button
          onClick={onDismiss}
          className="vn-choice flex w-full items-center justify-center gap-1.5 px-3 py-1.5 font-mono text-[10px] uppercase tracking-[0.25em] text-muted hover:text-bone"
        >
          Dismiss
        </button>
      )}
    </div>
  );
}
