import { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { useGame } from '@/engine/store';
import { CHARACTERS } from '@/data/characters';
import { ScrollText, X } from 'lucide-react';

// Dialogue history panel — a scrollable log of every line the player has
// read this session. Inspired by Steins;Gate's system menu and the standard
// VN "log" feature: lets the player re-read a line they clicked past too
// fast, or recall who said what before a choice.
//
// The store already keeps a capped log[] (see advance() in store.ts); this
// panel just surfaces it. Opened via the in-game menu or the 'L' hotkey.

export default function HistoryPanel({ onClose }: { onClose: () => void }) {
  const log = useGame((s) => s.log);
  const scene = useGame((s) => s.scene);
  const lineIndex = useGame((s) => s.lineIndex);

  // The current line is highlighted so the player can see where they are
  // relative to the log. We approximate "current" by the last entry's ts.
  const currentLine = scene?.lines[lineIndex];
  const currentText = currentLine?.text ?? '';

  const scrollRef = useRef<HTMLDivElement>(null);
  // Jump to the bottom on open so the most recent line is visible — that's
  // what the player is most likely looking for.
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, []);

  // Esc closes — matches the rest of the overlay UX.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-50 flex items-center justify-center bg-void/92 backdrop-blur-md"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.96, y: 10 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.96, y: 10 }}
        onClick={(e) => e.stopPropagation()}
        className="vn-panel relative flex max-h-[80vh] w-full max-w-2xl flex-col px-6 py-6 md:px-8"
      >
        {/* Header */}
        <div className="mb-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ScrollText size={16} className="text-blood-bright" />
            <span className="font-mono text-xs uppercase tracking-[0.4em] text-blood-bright">
              History
            </span>
            <span className="font-mono text-[9px] uppercase tracking-wider text-muted/60">
              {log.length} lines
            </span>
          </div>
          <button
            onClick={onClose}
            className="text-muted transition-colors hover:text-bone"
            aria-label="Close"
          >
            <X size={18} />
          </button>
        </div>

        {/* Log scroll area */}
        <div
          ref={scrollRef}
          className="flex-1 overflow-y-auto pr-2"
          style={{ scrollbarGutter: 'stable' }}
        >
          {log.length === 0 ? (
            <p className="py-12 text-center font-serif text-sm italic text-muted/60">
              No lines spoken yet. The game has not begun to talk.
            </p>
          ) : (
            <ol className="flex flex-col gap-3">
              {log.map((entry, i) => {
                const speaker = entry.speaker ? CHARACTERS[entry.speaker] : null;
                const isSystem = entry.speaker === 'system';
                const isCurrent = entry.text === currentText && i === log.length - 1;
                return (
                  <li
                    key={i}
                    className={[
                      'border-l-2 pl-3 py-1.5 transition-colors',
                      isCurrent
                        ? 'border-blood-bright bg-blood/5'
                        : 'border-ash/60',
                    ].join(' ')}
                  >
                    {speaker && (
                      <div className="mb-0.5 flex items-baseline gap-2">
                        <span
                          className="font-mono text-[10px] uppercase tracking-[0.3em]"
                          style={{ color: speaker.color }}
                        >
                          {speaker.name}
                        </span>
                        {isCurrent && (
                          <span className="font-mono text-[8px] uppercase tracking-wider text-blood-bright animate-pulse-slow">
                            ◦ now
                          </span>
                        )}
                      </div>
                    )}
                    <p
                      className={[
                        'font-serif text-sm leading-relaxed',
                        speaker ? 'text-bone/85' : 'italic text-bone/65',
                        isSystem ? 'font-mono text-xs tracking-wide text-blood-bright/80' : '',
                      ].join(' ')}
                    >
                      {entry.text}
                    </p>
                  </li>
                );
              })}
            </ol>
          )}
        </div>

        {/* Footer hint */}
        <p className="mt-3 text-center font-mono text-[9px] uppercase tracking-[0.3em] text-muted/50">
          Esc to return ◊ The log records only this session
        </p>
      </motion.div>
    </motion.div>
  );
}
