// localStorage-backed save/load. 5 numbered slots + autosave.

export interface SavePayload {
  sceneId: string;
  flags: Record<string, number | string | boolean>;
  sanity: number;
  trust: Record<string, number>;
  inventory: string[];
  deductions: string[];
  ruleBreakCount: number;
  loopCount: number;
  retainedClues: string[];
  // Rules the player has verified (resolved) this loop. Persisted so the
  // active rule card stays accurate across save/load — a verified rule
  // stays hidden from the card but remains in the Codex. Not to be
  // confused with flippedRules, which is global (localStorage) state.
  verifiedRules: string[];
  // Game mode + Salvation Protocol tally / pool. Persisted so a save made
  // mid-Salvation loads back into the correct scene map with the correct
  // soul count. Optional — classic saves made before the mode existed
  // default to 'classic' with an empty tally on load.
  gameMode?: 'classic' | 'salvation';
  savedCount?: number;
  punishedCount?: number;
  savedPeople?: string[];
  punishedPeople?: string[];
  rescuePool?: string[];
}

export interface SaveSlotMeta {
  slot: number | 'autosave';
  timestamp: number;
  sceneId: string;
  chapter: number;
  sanity: number;
  loopCount: number;
  // Game mode + Salvation Protocol tally. Persisted so the save/load screen
  // can render mode-appropriate metadata (Round X / 3 + soul tally for
  // salvation, Day X / 7 + sanity for classic). Defaults to 'classic' for
  // saves made before the mode existed.
  gameMode?: 'classic' | 'salvation';
  savedCount?: number;
  punishedCount?: number;
}

const AUTOSAVE_KEY = 'btr_autosave';
const SLOT_PREFIX = 'btr_save_';

function slotKey(slot: number | 'autosave'): string {
  return slot === 'autosave' ? AUTOSAVE_KEY : `${SLOT_PREFIX}${slot}`;
}

export function writeSave(slot: number | 'autosave', payload: SavePayload): void {
  try {
    const data = {
      ...payload,
      timestamp: Date.now(),
    };
    localStorage.setItem(slotKey(slot), JSON.stringify(data));
  } catch (e) {
    console.error('Save failed', e);
  }
}

export function loadSave(slot: number | 'autosave'): (SavePayload & { timestamp: number }) | null {
  try {
    const raw = localStorage.getItem(slotKey(slot));
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export function listSaveSlots(): SaveSlotMeta[] {
  const slots: SaveSlotMeta[] = [];
  const auto = loadSave('autosave');
  if (auto) {
    slots.push({
      slot: 'autosave',
      timestamp: auto.timestamp,
      sceneId: auto.sceneId,
      chapter: chapterFromScene(auto.sceneId, auto.gameMode),
      sanity: auto.sanity,
      loopCount: auto.loopCount,
      gameMode: auto.gameMode ?? 'classic',
      savedCount: auto.savedCount,
      punishedCount: auto.punishedCount,
    });
  }
  for (let i = 1; i <= 5; i++) {
    const s = loadSave(i);
    if (s) {
      slots.push({
        slot: i,
        timestamp: s.timestamp,
        sceneId: s.sceneId,
        chapter: chapterFromScene(s.sceneId, s.gameMode),
        sanity: s.sanity,
        loopCount: s.loopCount,
        gameMode: s.gameMode ?? 'classic',
        savedCount: s.savedCount,
        punishedCount: s.punishedCount,
      });
    }
  }
  return slots;
}

export function deleteSave(slot: number | 'autosave'): void {
  localStorage.removeItem(slotKey(slot));
}

// Map a scene id to its chapter number. Classic mode scenes are prefixed
// "dN_" (e.g. "d3_intro" → 3). Salvation mode scenes are prefixed "salv_"
// and group by soul arc: intro + suwan arc = 1, chenmo arc = 2, linye arc +
// truth reveal + ending = 3. Returns 0 when the scene id is unrecognized
// (corrupt / foreign saves) so the UI falls back to a neutral label.
function chapterFromScene(sceneId: string, mode?: 'classic' | 'salvation'): number {
  const classicMatch = sceneId.match(/^d(\d+)/);
  if (classicMatch) return parseInt(classicMatch[1], 10);
  if (mode === 'salvation' || sceneId.startsWith('salv_')) {
    if (sceneId === 'salv_intro' || sceneId.includes('suwan')) return 1;
    if (sceneId.includes('chenmo')) return 2;
    // linye, truth_reveal, ending → 3
    return 3;
  }
  return 0;
}
