import type { CSSProperties } from 'react';

// ReactBits-inspired Shiny Text: 文字表面有线性高光从左到右周期性扫过，
// 像被光照射的金属或湿润的字面。
// 参考来源: https://reactbits.dev
//
// 适配本项目：默认高光为 bone-white，扫过时短暂提亮文字亮度，
// 用于 EndingScreen 的结局标题，让"结局"读起来像被铭刻而非打印。
// 用 background-clip: text + animation 实现，无 JS 动画循环。

interface Props {
  children: string;
  /** 高光颜色（默认 bone-white） */
  shimmerColor?: string;
  /** 基础文字颜色（默认继承） */
  baseColor?: string;
  /** 扫光周期（秒，默认 4s） */
  duration?: number;
  className?: string;
  style?: CSSProperties;
}

export default function ShinyText({
  children,
  shimmerColor = 'rgba(255, 245, 230, 0.95)',
  baseColor,
  duration = 4,
  className = '',
  style,
}: Props) {
  return (
    <span
      className={`inline-block shiny-text ${className}`}
      style={{
        // 关键：background-clip: text 让渐变只显示在文字字形内，
        // 配合 @keyframes shinySweep 移动 background-position 实现扫光。
        backgroundImage: `linear-gradient(110deg, transparent 30%, ${shimmerColor} 50%, transparent 70%)`,
        backgroundSize: '200% 100%',
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        // 基础颜色通过 color 提供，扫光通过 -webkit-text-fill-color 透出
        color: baseColor,
        WebkitTextFillColor: baseColor ?? 'currentColor',
        animation: `shinySweep ${duration}s ease-in-out infinite`,
        ...style,
      }}
    >
      {children}
    </span>
  );
}
