// A recorded phone event — persisted to localStorage so the Codex's "Calls"
// tab can review missed calls and answered messages across sessions. We
// store the resolved display name and a short status so the log reads as a
// phone's call history rather than raw event data.
export interface PhoneLogEntry {
  id: string;
  kind: PhoneKind;
  from: string; // resolved display label (e.g. "UNKNOWN NUMBER", "YOU (loop)")
  text: string;
  status: 'answered' | 'declined' | 'missed' | 'read';
  loopCount: number; // which loop this call arrived in
  ts: number; // Date.now() at the moment of resolution
  // Steins;Gate reply: if the player picked a reply option, we record the
  // reply text and the caller's response so the Codex's call history shows
  // the full conversation, not just the incoming line. Undefined when the
  // event had no replies or the player declined/hung up without replying.
  chosenReply?: string;
  replyResponse?: string;
}

// Look up the phone event (if any) that should fire on entering the given
// scene, taking the player's loop count into account.
export function getPhoneEventForScene(
  sceneId: string,
  loopCount: number,
): PhoneEvent | null {
  return (
    PHONE_EVENTS.find(
      (e) =>
        e.sceneId === sceneId &&
        (e.requiresLoopCount ? loopCount >= e.requiresLoopCount : true),
    ) ?? null
  );
}

// Resolve a phone event's "from" field to a display name. Character ids are
// looked up against the character table; everything else renders verbatim.
export function resolveCallerLabel(from: string): string {
  // 'UNKNOWN' is the canonical "withheld number" marker.
  if (from === 'UNKNOWN') return 'UNKNOWN NUMBER';
  return from;
}

// Filter a phone event's replies to those currently visible to the player.
// Replies with no `requires` are always visible; gated replies are checked
// against the player's flags, retained clues, and loop count. Used by
// PhoneDevice so hidden replies (e.g. a "I remember you" line that only
// surfaces on a second loop) appear only when earned. Mirrors the gating
// logic GameStage uses for scene choices, kept here so the phone layer
// stays self-contained.
export function getVisibleReplies(
  event: PhoneEvent,
  ctx: {
    flags: Record<string, number | string | boolean>;
    retainedClues: string[];
    loopCount: number;
  },
): PhoneReply[] {
  if (!event.replies || event.replies.length === 0) return [];
  return event.replies.filter((r) => {
    const req = r.requires;
    if (!req) return true;
    if (req.minLoopCount !== undefined && ctx.loopCount < req.minLoopCount) {
      return false;
    }
    if (req.hasRetainedClue && !ctx.retainedClues.includes(req.hasRetainedClue)) {
      return false;
    }
    if (req.flag) {
      const v = ctx.flags[req.flag];
      if (req.equals !== undefined && v !== req.equals) return false;
      if (req.gte !== undefined && (typeof v !== 'number' || v < req.gte)) return false;
      if (req.lte !== undefined && (typeof v !== 'number' || v > req.lte)) return false;
    }
    return true;
  });
}
