import { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useGame } from "@/engine/store";
import { CHARACTERS } from "@/data/characters";
import { getBackground } from "@/lib/assets";
import HUD from "./HUD";
import DialogueBox from './DialogueBox';
import ChoiceMenu from './ChoiceMenu';
import RuleCard from './RuleCard';
import DeductionBoard from './DeductionBoard';
import CharacterProfilePanel from './CharacterProfilePanel';
import CharacterFace from './CharacterFace';
import SceneFX from './effects/SceneFX';
import HistoryPanel from './HistoryPanel';
import CodexPanel from './CodexPanel';
import PhoneDevice from './PhoneDevice';
import FakeCrashOverlay from './FakeCrashOverlay';
import CrossExamMode from './CrossExamMode';
import VerifyBoard from './VerifyBoard';
import FileBrowser from './FileBrowser';
import { getPhoneEventForScene, type PhoneEvent } from '@/data/phoneEvents';
import { Menu, BookOpen, Users, Save, Home, X, ScrollText, BookMarked, HardDrive } from 'lucide-react';
import type { Emotion } from '@/engine/types';

// Lines whose text marks a "fourth-wall" beat — moments where the game
// quietly suggests a character is not entirely who they seem, or that the
// protagonist is not entirely under player control. We match by sceneId +
// lineIndex so the visual beat lands precisely on the scripted line. Each
// entry yields a brief visual cue: the speaker's face flushes with another
// character's tint (implying outside control or hidden allegiance), or the
// speaker's gaze drifts toward the camera (implying awareness of the viewer).
const FOURTH_WALL_BEATS: Record<string, { lineIndex: number; foreignTint?: string; lookingAtViewer?: boolean }[]> = {
  // Day 2 — Lin Ye's "the game rewards you" line. He should not know what
  // the game does yet. His face briefly takes the protagonist's grey tint,
  // as if he is also a player wearing a mask.
  d2_truth: [
    { lineIndex: 1, foreignTint: '#e8e8e8' },
  ],
  // Day 4 — Bai Jing's confession. "I report to the game." Her face briefly
  // flushes with the Game Master's blood-red, hinting at the chain of
  // command she serves.
  d4_accuse: [
    { lineIndex: 3, foreignTint: '#8b0000' },
  ],
  // Day 5 (let_run path) — Lin Ye's "remember the cost of obedience" line.
  // He speaks as though he has paid it before. His gaze drifts toward the
  // camera for a beat, as if aware someone is watching from outside the
  // loop.
  d5_let_run: [
    { lineIndex: 3, lookingAtViewer: true },
  ],
};

function getFourthWallBeat(sceneId: string | undefined, lineIndex: number) {
  if (!sceneId) return null;
  const beats = FOURTH_WALL_BEATS[sceneId];
  if (!beats) return null;
  return beats.find((b) => b.lineIndex === lineIndex) ?? null;
}

// Memory flashes — on a second playthrough (loopCount >= 1), the protagonist
// remembers fragments of the previous loop. These surface as a brief red
// whisper overlay at scripted (sceneId, lineIndex) points. They do not
// replace the normal line; they layer on top of it for ~2.5s, implying the
// protagonist's deja vu without forcing a branch.
const MEMORY_FLASHES: Record<string, { lineIndex: number; text: string }[]> = {
  // Day 1 — the lights steady before the screen speaks. The player already
  // knows rule 1, so the protagonist's body knows it too.
  d1_intro: [
    { lineIndex: 6, text: '...the lights steady before the screen speaks. You know this. You have steadied them before.' },
  ],
  // Day 2 — if the player walked the trap last loop, the corridor remembers.
  d2_choice: [
    { lineIndex: 0, text: '...do not take the left path. You took it. You remember how it ended.' },
  ],
  // Day 5 — Su-wan's death is a recurring one. The protagonist feels it coming.
  d5_choice: [
    { lineIndex: 0, text: '...she fades here. She always fades here. You have watched her go before.' },
  ],
  // Day 6 — Voss's sacrifice is the oldest pattern in the loop.
  d6_intro: [
    { lineIndex: 2, text: '...he says this every time. He always says this. He always stays.' },
  ],
};

function getMemoryFlash(sceneId: string | undefined, lineIndex: number, loopCount: number) {
  if (loopCount < 1) return null;
  if (!sceneId) return null;
  const flashes = MEMORY_FLASHES[sceneId];
  if (!flashes) return null;
  return flashes.find((f) => f.lineIndex === lineIndex) ?? null;
}

const EMOTION_GLOW: Record<Emotion, string> = {
  neutral: 'rgba(180,180,200,0.25)',
  happy: 'rgba(180,220,180,0.3)',
  sad: 'rgba(120,150,200,0.35)',
  angry: 'rgba(220,60,60,0.45)',
  fear: 'rgba(200,120,60,0.4)',
  thinking: 'rgba(120,160,220,0.3)',
  cold: 'rgba(150,210,230,0.3)',
  pained: 'rgba(200,80,80,0.4)',
};

export default function GameStage() {
  const scene = useGame((s) => s.scene);
  const lineIndex = useGame((s) => s.lineIndex);
  const showingChoices = useGame((s) => s.showingChoices);
  const showingRuleCard = useGame((s) => s.showingRuleCard);
  // Cross-exam (逆转裁判): when the scene has a crossExam config and the
  // intro lines are exhausted, the store flips crossExamActive and we
  // render CrossExamMode in place of the choice menu.
  const crossExamActive = useGame((s) => s.crossExamActive);
  // Salvation Mode verify board (救赎协议): same hand-off pattern as
  // cross-exam — when the scene has a verifyBoard config and the intro
  // lines are exhausted, the store flips verifyBoardActive and we render
  // VerifyBoard in place of the choice menu.
  const verifyBoardActive = useGame((s) => s.verifyBoardActive);
  const sanity = useGame((s) => s.sanity);
  const loopCount = useGame((s) => s.loopCount);
  const setScreen = useGame((s) => s.setScreen);
  const saveToSlot = useGame((s) => s.saveToSlot);
  const openSaveLoad = useGame((s) => s.openSaveLoad);
  const triggerPhoneEvent = useGame((s) => s.triggerPhoneEvent);

  // Phone Trigger: when the player enters a scene that has a phone event
  // (and it hasn't fired this loop), surface the PhoneDevice. We wait until
  // the rule card (if any) is dismissed so the phone doesn't ring over the
  // rules — the phone is a punctuation device, not a interruption of the
  // game's formal beats.
  const [activePhoneEvent, setActivePhoneEvent] = useState<PhoneEvent | null>(null);
  useEffect(() => {
    if (!scene || showingRuleCard) return;
    const evt = getPhoneEventForScene(scene.id, loopCount);
    if (!evt) return;
    const newlyTriggered = triggerPhoneEvent(evt.id);
    if (newlyTriggered) {
      // Small delay so the scene transition settles before the phone rings.
      const t = window.setTimeout(() => setActivePhoneEvent(evt), 600);
      return () => window.clearTimeout(t);
    }
  }, [scene?.id, showingRuleCard, loopCount, triggerPhoneEvent]);

  // Fake Crash: triggered when the player destroys a character's profile
  // from the Cast panel. The overlay takes over the screen, "crashes," then
  // recovers with the file restored. Purely cosmetic — no data is lost.
  const [crashProfileId, setCrashProfileId] = useState<string | null>(null);

  // Fourth-wall + memory-flash beats are derived from the current line.
  const beat = getFourthWallBeat(scene?.id, lineIndex);
  const memoryFlash = getMemoryFlash(scene?.id, lineIndex, loopCount);

  const [menuOpen, setMenuOpen] = useState(false);
  const [showDeduction, setShowDeduction] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showCodex, setShowCodex] = useState(false);
  // DDLC file system: a virtual file browser reachable from the in-game
  // menu. Lets the player read the game's back-end files and delete certain
  // ones to trigger hidden 剧情 (clues, flags, the FakeCrashOverlay for .chr
  // files). Shares the crashProfileId flow with the Cast panel.
  const [showFileSystem, setShowFileSystem] = useState(false);

  // First-time menu hint: a one-shot tooltip that points the player at the
  // menu button the first time they can review clues / codex / history. We
  // gate on a localStorage flag so it shows exactly once per browser, then
  // never again — it's a nudge, not a recurring coachmark. Dismissed as
  // soon as the player opens the menu (the act of viewing is the goal).
  const [menuHintSeen, setMenuHintSeen] = useState<boolean>(() => {
    try {
      return localStorage.getItem('btr_menu_hint_seen') === '1';
    } catch {
      return false;
    }
  });
  const showMenuHint =
    !menuHintSeen && !showingChoices && !showingRuleCard && !menuOpen;

  // Hotkeys: L opens dialogue history (Steins;Gate-style log), J opens the
  // Codex (rules + locations reference). Both close on Esc (handled inside
  // the panel). We deliberately avoid colliding with the dialogue's Space
  // / Enter advance, and with the choice menu's 1-9 number keys.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      // Ignore when an overlay that should monopolise input is open.
      if (showingChoices || showingRuleCard || menuOpen) return;
      if (e.key === 'l' || e.key === 'L') {
        e.preventDefault();
        setShowHistory(true);
      } else if (e.key === 'j' || e.key === 'J') {
        e.preventDefault();
        setShowCodex(true);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [showingChoices, showingRuleCard, menuOpen]);

  // Track scene id changes so we can play a one-shot cinematic wipe transition
  // whenever the player crosses into a new scene.
  const [wipeKey, setWipeKey] = useState(0);
  const prevSceneId = useRef<string | null>(null);
  useEffect(() => {
    if (scene && scene.id !== prevSceneId.current) {
      prevSceneId.current = scene.id;
      setWipeKey((k) => k + 1);
    }
  }, [scene?.id]);

  // Parallax: track the pointer offset from screen center and translate the
  // background + character layer by a few pixels. Adds depth without a rAF loop.
  const [parallax, setParallax] = useState({ x: 0, y: 0 });
  useEffect(() => {
    const onMove = (e: PointerEvent) => {
      const cx = window.innerWidth / 2;
      const cy = window.innerHeight / 2;
      // Subtle parallax — clamp to ±10px so it never feels jittery.
      setParallax({
        x: Math.max(-10, Math.min(10, (e.clientX - cx) / 80)),
        y: Math.max(-10, Math.min(10, (e.clientY - cy) / 80)),
      });
    };
    window.addEventListener('pointermove', onMove);
    return () => window.removeEventListener('pointermove', onMove);
  }, []);

  // Stage-level screen shake: when the current line carries effect: "shake",
  // briefly apply the scene-shake class to the whole stage.
  const currentLine = scene?.lines[lineIndex];
  const lineEffect = currentLine?.effect;
  const [shaking, setShaking] = useState(false);
  useEffect(() => {
    if (lineEffect !== 'shake') return;
    setShaking(true);
    const t = window.setTimeout(() => setShaking(false), 600);
    return () => window.clearTimeout(t);
  }, [lineIndex, lineEffect]);

  const backgroundKey = scene?.background;
  const { img, gradient } = getBackground(backgroundKey);

  const speakerId = currentLine?.speaker;
  const speaker = speakerId ? CHARACTERS[speakerId] : null;
  const emotion = currentLine?.emotion ?? 'neutral';

  // Low sanity warning: pulsing red vignette when the mind starts to crack.
  const dangerLevel = sanity <= 0 ? 0 : sanity < 25 ? 2 : sanity < 45 ? 1 : 0;

  return (
    <div
      className={[
        'relative h-full w-full overflow-hidden',
        shaking ? 'animate-scene-shake' : '',
      ].join(' ')}
      style={{ background: gradient }}
    >
      {/* Background image (generated) layered over gradient fallback, with parallax */}
      <AnimatePresence mode="wait">
        <motion.div
          key={backgroundKey ?? 'none'}
          initial={{ opacity: 0, scale: 1.04 }}
          animate={{
            opacity: img ? 0.55 : 0,
            scale: 1,
            x: parallax.x * -2,
            y: parallax.y * -1.5,
          }}
          exit={{ opacity: 0, scale: 1.02 }}
          transition={{ duration: 0.9, ease: 'easeOut' }}
          className="absolute inset-0"
        >
          {img && (
            <img
              src={img}
              alt=""
              className="bg-ken-burns h-full w-full object-cover"
              onError={(e) => {
                (e.currentTarget as HTMLImageElement).style.display = 'none';
              }}
            />
          )}
        </motion.div>
      </AnimatePresence>

      {/* Per-scene ambient particle / overlay effects */}
      <div
        className="absolute inset-0"
        style={{
          transform: `translate(${parallax.x}px, ${parallax.y}px)`,
        }}
      >
        <SceneFX backgroundKey={backgroundKey} />
      </div>

      {/* Atmospheric color wash per chapter */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            'linear-gradient(180deg, rgba(10,10,15,0.2) 0%, transparent 40%, rgba(10,10,15,0.4) 100%)',
        }}
      />

      {/* Cinematic wipe between scenes — a dark gradient sweeps across briefly */}
      {wipeKey > 0 && (
        <div
          key={`wipe-${wipeKey}`}
          className="scene-wipe"
          aria-hidden
        />
      )}

      {/* Low-sanity danger pulse: the screen bleeds red as the mind frays. */}
      {dangerLevel > 0 && (
        <motion.div
          key={`danger-${dangerLevel}`}
          className="pointer-events-none absolute inset-0 z-20"
          initial={{ opacity: 0 }}
          animate={{
            opacity: dangerLevel === 2 ? [0.35, 0.7, 0.35] : [0.12, 0.3, 0.12],
          }}
          transition={{
            duration: dangerLevel === 2 ? 1.4 : 2.4,
            repeat: Infinity,
            ease: 'easeInOut',
          }}
          style={{
            background:
              'radial-gradient(ellipse at 50% 50%, transparent 20%, rgba(139,0,0,0.55) 85%, rgba(80,0,0,0.85) 100%)',
            mixBlendMode: 'multiply',
          }}
        />
      )}

      {/* Character presence: a stylised glowing silhouette with a per-character
          face. The face is parametrised by character id and emotion so each
          cast member reads as a distinct person rather than a coloured circle.
          On scripted "fourth wall" beats, the speaker's face briefly takes on
          another character's tint or gazes at the viewer.
          Sizing/positioning: kept inside the upper ~60% of the viewport so the
          figure never collides with the dialogue panel (which owns the bottom
          ~32vh) or the top HUD row. The name tag sits inside the figure box
          (not below it) so it cannot be clipped by the panel. */}
      {speaker && speaker.id !== 'system' && speaker.id !== 'narrator' && (() => {
        const beat = getFourthWallBeat(scene?.id, lineIndex);
        const foreignTint = beat?.foreignTint;
        const lookingAtViewer = beat?.lookingAtViewer ?? false;
        return (
        <div className="pointer-events-none absolute right-2 top-[38%] z-10 hidden -translate-y-1/2 sm:block md:right-12">
          <AnimatePresence mode="wait">
            <motion.div
              key={speaker.id + emotion + (foreignTint ?? '')}
              initial={{ opacity: 0, x: 30 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              transition={{ duration: 0.4 }}
              className="relative flex h-[48vh] max-h-[460px] w-28 flex-col items-center justify-end md:w-40"
              style={{ color: speaker.color }}
            >
              {/* Glow aura — pulses gently with the character's breath */}
              <motion.div
                className="absolute bottom-0 h-3/4 w-full"
                animate={{ opacity: [0.6, 1, 0.6] }}
                transition={{ duration: 4.5, repeat: Infinity, ease: 'easeInOut' }}
                style={{
                  background: `radial-gradient(ellipse at 50% 80%, ${EMOTION_GLOW[emotion]} 0%, transparent 70%)`,
                  filter: 'blur(8px)',
                }}
              />
              {/* Character figure — gently breathes via the .animate-breath utility */}
              <svg
                viewBox="0 0 100 220"
                className="animate-breath relative h-full w-full"
                style={{ filter: `drop-shadow(0 0 12px ${speaker.color}40)` }}
              >
                {/* Full figure (head + body) — rendered per character, per
                    emotion. Each character has a distinct build, clothing and
                    signature gesture. The protagonist can wear a foreign tint
                    or look at the viewer on scripted beats to imply outside
                    control. */}
                <CharacterFace
                  id={speaker.id}
                  color={speaker.color}
                  emotion={emotion}
                  foreignTint={foreignTint}
                  lookingAtViewer={lookingAtViewer}
                />
              </svg>
              {/* Name tag — kept inside the figure box (bottom padding) so it
                  never gets clipped by the dialogue panel below. */}
              <div className="w-full pt-1.5 text-center">
                <span
                  className="font-mono text-[9px] uppercase tracking-[0.3em]"
                  style={{ color: speaker.color }}
                >
                  {speaker.name}
                </span>
              </div>
            </motion.div>
          </AnimatePresence>
        </div>
        );
      })()}

      {/* HUD */}
      <HUD />

      {/* In-game menu button + first-time hint. Anchored below the HUD row
          (top-20 / md:top-24) so it never overlaps the sanity/clue readouts
          above it, and on the right edge clear of the character figure. */}
      {!showingChoices && !showingRuleCard && (
        <div className="fixed right-3 top-20 z-30 flex items-center gap-2 md:top-24">
          <AnimatePresence>
            {showMenuHint && (
              <motion.button
                type="button"
                onClick={() => {
                  try {
                    localStorage.setItem('btr_menu_hint_seen', '1');
                  } catch {
                    /* ignore */
                  }
                  setMenuHintSeen(true);
                  setMenuOpen(true);
                }}
                initial={{ opacity: 0, x: 8 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 8 }}
                transition={{ duration: 0.3 }}
                className="group flex items-center gap-2 border border-blood/60 bg-void/80 px-2.5 py-1.5 text-right backdrop-blur-sm hover:border-blood-bright transition-colors"
              >
                <span className="font-mono text-[9px] uppercase tracking-[0.2em] text-blood-bright">
                  ◂
                </span>
                <span className="flex flex-col items-start leading-tight">
                  <span className="font-mono text-[9px] uppercase tracking-[0.25em] text-bone">
                    Review
                  </span>
                  <span className="font-serif text-[10px] italic text-muted group-hover:text-bone/80">
                    clues · codex · history
                  </span>
                </span>
              </motion.button>
            )}
          </AnimatePresence>
          <button
            onClick={() => {
              if (!menuHintSeen) {
                try {
                  localStorage.setItem('btr_menu_hint_seen', '1');
                } catch {
                  /* ignore */
                }
                setMenuHintSeen(true);
              }
              setMenuOpen(true);
            }}
            className={[
              'relative border bg-void/40 p-2 text-muted transition-colors',
              showMenuHint
                ? 'border-blood-bright text-bone animate-pulse-slow'
                : 'border-ash/60 hover:border-blood hover:text-bone',
            ].join(' ')}
            aria-label="Menu"
          >
            <Menu size={16} />
            {showMenuHint && (
              <span className="absolute -right-1 -top-1 flex h-2 w-2">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-blood-bright opacity-75" />
                <span className="relative inline-flex h-2 w-2 rounded-full bg-blood-bright" />
              </span>
            )}
          </button>
        </div>
      )}

      {/* Dialogue box */}
      <DialogueBox />

      {/* Overlays */}
      <AnimatePresence>
        {showingRuleCard && <RuleCard key="rulecard" />}
      </AnimatePresence>
      {showingChoices && <ChoiceMenu />}
      {/* Cross-examination mode — replaces the choice menu when a scene has
          a crossExam config. Mutually exclusive with showingChoices. */}
      <AnimatePresence>
        {crossExamActive && <CrossExamMode key="crossexam" />}
      </AnimatePresence>
      {/* Salvation Mode verify board — replaces the choice menu when a scene
          has a verifyBoard config. Mutually exclusive with showingChoices and
          crossExam. The player judges each rule as Real or Fake; the store
          weighs each verdict (fake→save, real→maybe save, wrong→punish). */}
      <AnimatePresence>
        {verifyBoardActive && <VerifyBoard key="verifyboard" />}
      </AnimatePresence>

      {/* Phone Trigger — incoming call / message device. Renders as a
          floating widget in the lower-right; layers over dialogue without
          pausing the game. Auto-dismisses on scene change (logged as
          missed if still ringing). */}
      <AnimatePresence>
        {activePhoneEvent && (
          <PhoneDevice
            key={`phone-${activePhoneEvent.id}`}
            event={activePhoneEvent}
            onClose={() => setActivePhoneEvent(null)}
          />
        )}
      </AnimatePresence>

      {/* Deduction board */}
      <AnimatePresence>
        {showDeduction && <DeductionBoard key="deduction" onClose={() => setShowDeduction(false)} />}
      </AnimatePresence>

      {/* Codex — rules witnessed + locations reference */}
      <AnimatePresence>
        {showCodex && <CodexPanel key="codex" onClose={() => setShowCodex(false)} />}
      </AnimatePresence>

      {/* Dialogue history — scrollable log of past lines */}
      <AnimatePresence>
        {showHistory && <HistoryPanel key="history" onClose={() => setShowHistory(false)} />}
      </AnimatePresence>

      {/* Character profile panel */}
      <AnimatePresence>
        {showProfile && (
          <CharacterProfilePanel
            key="profile"
            onClose={() => setShowProfile(false)}
            onDestroy={(profileId) => {
              setShowProfile(false);
              // Brief delay so the Cast panel closes before the crash overlay
              // takes over — the transition sells the "game just broke" beat.
              window.setTimeout(() => setCrashProfileId(profileId), 250);
            }}
          />
        )}
      </AnimatePresence>

      {/* DDLC file system browser — virtual file tree the player can read
          and delete from. Deleting a .chr file triggers the same crash flow
          as the Cast panel's destroy action (shared crashProfileId state). */}
      <AnimatePresence>
        {showFileSystem && (
          <FileBrowser
            key="filesystem"
            onClose={() => setShowFileSystem(false)}
            onCrashProfile={(profileId) => {
              setShowFileSystem(false);
              window.setTimeout(() => setCrashProfileId(profileId), 250);
            }}
          />
        )}
      </AnimatePresence>

      {/* In-game menu */}
      <AnimatePresence>
        {menuOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-50 flex items-center justify-center bg-void/90 backdrop-blur-md"
            onClick={() => setMenuOpen(false)}
          >
            <motion.div
              initial={{ scale: 0.9, y: 10 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 10 }}
              onClick={(e) => e.stopPropagation()}
              className="w-full max-w-xs px-6"
            >
              <div className="mb-6 flex items-center justify-between">
                <span className="font-mono text-xs uppercase tracking-[0.4em] text-blood-bright">
                  Paused
                </span>
                <button
                  onClick={() => setMenuOpen(false)}
                  className="text-muted hover:text-bone transition-colors"
                >
                  <X size={18} />
                </button>
              </div>
              <div className="flex flex-col gap-2.5">
                <MenuButton
                  icon={<BookOpen size={14} />}
                  label="Deduction Board"
                  onClick={() => {
                    setMenuOpen(false);
                    setShowDeduction(true);
                  }}
                />
                <MenuButton
                  icon={<BookMarked size={14} />}
                  label="Codex"
                  hint="J"
                  onClick={() => {
                    setMenuOpen(false);
                    setShowCodex(true);
                  }}
                />
                <MenuButton
                  icon={<ScrollText size={14} />}
                  label="History"
                  hint="L"
                  onClick={() => {
                    setMenuOpen(false);
                    setShowHistory(true);
                  }}
                />
                <MenuButton
                  icon={<Users size={14} />}
                  label="The Cast"
                  onClick={() => {
                    setMenuOpen(false);
                    setShowProfile(true);
                  }}
                />
                <MenuButton
                  icon={<HardDrive size={14} />}
                  label="File System"
                  onClick={() => {
                    setMenuOpen(false);
                    setShowFileSystem(true);
                  }}
                />
                <MenuButton
                  icon={<Save size={14} />}
                  label="Quick Save"
                  onClick={() => {
                    saveToSlot(1);
                    setMenuOpen(false);
                  }}
                />
                <MenuButton
                  icon={<Save size={14} />}
                  label="Save / Load"
                  onClick={() => {
                    setMenuOpen(false);
                    openSaveLoad('save');
                  }}
                />
                <MenuButton
                  icon={<Home size={14} />}
                  label="Main Menu"
                  onClick={() => {
                    setMenuOpen(false);
                    setScreen('title');
                  }}
                />
              </div>
              <p className="mt-6 text-center font-serif text-[11px] italic text-muted">
                The game does not pause. It waits.
              </p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Memory flash overlay — on a second playthrough, the protagonist
          remembers fragments of the previous loop. Renders as a brief red
          whisper layered over the normal dialogue. Anchored above the
          dialogue panel (not at the very top) so it never collides with
          the HUD row. Does not block input. */}
      <AnimatePresence>
        {memoryFlash && (
          <motion.div
            key={`mem-${scene?.id}-${lineIndex}`}
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            transition={{ duration: 0.6 }}
            className="pointer-events-none fixed left-1/2 top-[34vh] z-40 max-w-md -translate-x-1/2 px-6 text-center"
          >
            <p className="font-serif text-sm italic text-blood-bright/80 fx-whisper">
              {memoryFlash.text}
            </p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Screen leak overlay — on a fourth-wall beat, a fake system log
          line flickers at the screen edge for ~0.8s, implying someone (or
          something) is monitoring the player's input. Purely cosmetic. */}
      <AnimatePresence>
        {beat && (
          <motion.div
            key={`leak-${scene?.id}-${lineIndex}`}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: [0, 0.7, 0.7, 0], x: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.6, times: [0, 0.2, 0.7, 1] }}
            className="pointer-events-none fixed bottom-4 right-4 z-40 hidden font-mono text-[9px] uppercase tracking-wider text-blood-bright/60 md:block"
          >
            <span className="text-muted/40">player_input_detected:</span>{' '}
            processing...
          </motion.div>
        )}
      </AnimatePresence>

      {/* Fake Crash overlay — triggered when the player destroys a character
          profile. Takes over the screen with a simulated crash, then recovers.
          The Game Master acknowledges the deletion attempt before restoring
          the file. Purely cosmetic — no save data is actually lost. */}
      <AnimatePresence>
        {crashProfileId && (
          <FakeCrashOverlay
            key={`crash-${crashProfileId}`}
            profileId={crashProfileId}
            onClose={() => setCrashProfileId(null)}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

function MenuButton({
  icon,
  label,
  hint,
  onClick,
}: {
  icon: React.ReactNode;
  label: string;
  hint?: string;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="vn-choice flex items-center gap-3 px-5 py-3 font-mono text-xs uppercase tracking-widest text-bone hover:text-white"
    >
      <span className="text-blood-bright">{icon}</span>
      <span className="flex-1 text-left">{label}</span>
      {hint && (
        <span className="ml-auto border border-blood/40 px-1.5 py-0.5 text-[9px] tracking-widest text-muted">
          {hint}
        </span>
      )}
    </button>
  );
}
