// Evaluate whether a file's requirements are met given the player's state.
// Files with no requirements are always visible. Used by FileBrowser so the
// tree grows across playthroughs instead of spoiling everything up front.
export function isFileVisible(
  file: VFile,
  ctx: {
    flags: Record<string, number | string | boolean>;
    inventory: string[];
    loopCount: number;
    completedSideQuests: string[];
  },
): boolean {
  const req = file.requires;
  if (!req) return true;
  if (req.minLoopCount !== undefined && ctx.loopCount < req.minLoopCount) {
    return false;
  }
  if (req.flag && !ctx.flags[req.flag]) return false;
  if (req.hasClue && !ctx.inventory.includes(req.hasClue)) return false;
  if (req.questDone && !ctx.completedSideQuests.includes(req.questDone)) {
    return false;
  }
  return true;
}

// All files (root + tree) in render order. Folders first, then files,
// preserving the authored order within each group.
export const ALL_FILES: VFile[] = [...FILE_SYSTEM, ...ROOT_FILES];
