import type { CSSProperties, ReactNode } from 'react';

// uiverse-inspired Neon Frame: 围绕子元素的霓虹发光边框，带轻微呼吸效果。
// 参考来源: https://uiverse.io
//
// 适配本项目：默认血红色霓虹，用于 RuleCard 的规则卡片，让每条规则
// 读起来像被血光刻在墙上。实现: 双层 box-shadow（内层锐利 + 外层发散）
// + @keyframes neonPulse 呼吸，比单纯的 border 更有"发光"感。
// 已内置 prefers-reduced-motion 支持（在 index.css 中禁用动画）。

interface Props {
  children: ReactNode;
  /** 霓虹颜色（默认 blood-bright） */
  color?: string;
  /** 是否启用呼吸动画（默认 true） */
  pulse?: boolean;
  /** 边框圆角（默认 0，符合本项目硬朗风格） */
  radius?: number | string;
  className?: string;
  style?: CSSProperties;
}

export default function NeonFrame({
  children,
  color = 'rgba(200, 30, 30, 0.85)',
  pulse = true,
  radius = 0,
  className = '',
  style,
}: Props) {
  return (
    <div
      className={`relative ${pulse ? 'animate-neon-pulse' : ''} ${className}`}
      style={{
        // 双层边框：1px 锐利内边框 + 多层发散 box-shadow 制造霓虹辉光
        border: `1px solid ${color}`,
        borderRadius: typeof radius === 'number' ? `${radius}px` : radius,
        boxShadow: `
          0 0 8px ${color},
          0 0 18px ${color.replace(/[\d.]+\)$/, '0.45)')},
          inset 0 0 12px ${color.replace(/[\d.]+\)$/, '0.18)')}
        `,
        // CSS 变量供 @keyframes neonPulse 调用，避免硬编码颜色
        ['--neon-color' as string]: color,
        ...style,
      }}
    >
      {children}
    </div>
  );
}
