import { useMemo } from "react";
import { useGame } from "@/engine/store";

// Atmospheric overlay layers: film grain, scanline, vignette, plus reactive
// layers driven by player state (low sanity blood drips + heartbeat vignette).
// Applied once at the app root. Pure CSS, GPU-cheap, respects reduced motion.

// Number of blood threads rendered when sanity is critically low.
const BLOOD_THREAD_COUNT = 14;

// Deterministic layout for blood threads so they don't reshuffle on re-render.
function useBloodThreads(count: number, seed: number) {
  return useMemo(() => {
    let s = seed;
    const rand = () => {
      s = (s * 1664525 + 1013904223) | 0;
      return ((s >>> 0) % 1000) / 1000;
    };
    return Array.from({ length: count }, () => ({
      left: `${Math.round(rand() * 100)}%`,
      height: `${Math.round(20 + rand() * 60)}%`,
      delay: `${(rand() * 6).toFixed(2)}s`,
      duration: `${(5 + rand() * 5).toFixed(2)}s`,
    }));
  }, [count, seed]);
}

export default function Atmosphere() {
  const sanity = useGame((s) => s.sanity);
  const ruleBreakCount = useGame((s) => s.ruleBreakCount);
  const loopCount = useGame((s) => s.loopCount);

  // Blood threads appear once sanity is below 45%; density grows as sanity falls.
  const dangerLevel = sanity <= 0 ? 0 : sanity < 25 ? 2 : sanity < 45 ? 1 : 0;
  const bloodActive = dangerLevel > 0;
  const bloodThreads = useBloodThreads(
    dangerLevel === 2 ? BLOOD_THREAD_COUNT : Math.round(BLOOD_THREAD_COUNT / 2),
    42 + ruleBreakCount * 7 + loopCount * 13,
  );

  // The heartbeat vignette only kicks in at the second danger level so the
  // first threshold remains atmospheric rather than alarming.
  const showHeartbeat = dangerLevel === 2;

  return (
    <>
      {/* Base grain / scanline / vignette — present at all times */}
      <div
        aria-hidden
        className="film-grain scanline vignette pointer-events-none fixed inset-0 z-40"
      />

      {/* Loop-count glitch veil: occasional full-screen skew when the player
          has looped before, hinting that reality is fraying at the seams. */}
      {loopCount > 0 && (
        <div
          aria-hidden
          className="pointer-events-none fixed inset-0 z-[41] animate-glitch-skew"
          style={{
            background:
              "linear-gradient(90deg, rgba(139,0,0,0.04) 0%, transparent 30%, transparent 70%, rgba(30,30,80,0.04) 100%)",
            opacity: 0.5,
          }}
        />
      )}

      {/* Heartbeat vignette — pulses with the player's presumed pulse when
          sanity is critically low. The screen itself seems to be dying. */}
      {showHeartbeat && (
        <div aria-hidden className="heartbeat-vignette" />
      )}

      {/* Blood drip layer — vertical red threads seeping down from the top
          of the screen when the player's mind starts to crack. */}
      {bloodActive && (
        <div aria-hidden className={`blood-layer active`}>
          {bloodThreads.map((t, i) => (
            <span
              key={i}
              className="blood-thread"
              style={{
                left: t.left,
                height: t.height,
                animationDelay: t.delay,
                animationDuration: t.duration,
                opacity: dangerLevel === 2 ? 0.9 : 0.5,
              }}
            />
          ))}
        </div>
      )}
    </>
  );
}
