// --- SFX presets -----------------------------------------------------------
type SfxName =
  | 'click'
  | 'stinger'
  | 'reveal'
  | 'death'
  | 'type'    // soft per-letter typewriter tick
  | 'hover'   // UI hover blip
  | 'chime'   // clue discovered bell
  | 'rumble'  // rule card reveal low rumble
  | 'whoosh'  // scene transition wind
  | 'phone_ring'  // incoming call — old-school bell, loops
  | 'phone_busy'  // call declined / busy tone
  | 'phone_pickup' // call answered — soft click + connect chirp
  | 'objection';   // Ace Attorney-style correct-objection brass stab

class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  // BGM state
  private bgmNodes: AudioNode[] = [];
  private bgmGain: GainNode | null = null;
  private currentTrack: TrackKey | null = null;
  private bgmVolume = 0.6;
  private sfxVolume = 0.7;

  // Phone ring state — the ring loops until answered or declined, so it
  // needs its own node set that we can stop independently of the SFX bus.
  private phoneRingNodes: AudioNode[] = [];
  private phoneRingTimer: number | null = null;

  // Muted by default in dev/debug so the loop stays silent while iterating.
  // Toggle via setMuted() (e.g. from the Settings panel) to test audio.
  private muted = import.meta.env?.DEV ?? false;

  /** Returns true when audio is currently muted. */
  isMuted(): boolean {
    return this.muted;
  }

  /** Mute (debug) or unmute (test audio). When muting, stop active sound. */
  setMuted(v: boolean) {
    this.muted = v;
    if (v) {
      this.stopBGM();
    }
  }

  /** Lazily create the AudioContext on first user gesture. */
  private ensureContext(): AudioContext | null {
    if (this.muted) return null;
    if (typeof window === 'undefined') return null;
    if (!this.ctx) {
      try {
        const AC =
          window.AudioContext ||
          (window as unknown as { webkitAudioContext: typeof AudioContext })
            .webkitAudioContext;
        this.ctx = new AC();
        this.masterGain = this.ctx.createGain();
        this.masterGain.gain.value = 1;
        this.masterGain.connect(this.ctx.destination);
      } catch {
        return null;
      }
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
    return this.ctx;
  }

  setVolumes(bgm: number, sfx: number) {
    this.bgmVolume = bgm;
    this.sfxVolume = sfx;
    if (this.bgmGain && this.ctx) {
      this.bgmGain.gain.setTargetAtTime(bgm, this.ctx.currentTime, 0.1);
    }
  }

  // --- BGM -----------------------------------------------------------------
  playBGM(track: TrackKey, volume?: number) {
    if (track === this.currentTrack) return;
    const ctx = this.ensureContext();
    if (!ctx || !this.masterGain) return;

    // Fade out existing drone, then dispose.
    if (this.bgmGain && this.bgmNodes.length > 0) {
      this.fadeOutAndDispose(this.bgmGain, this.bgmNodes, 0.9);
      this.bgmNodes = [];
      this.bgmGain = null;
    }

    const preset = DRONES[track] ?? DRONES.drone_low;
    const target = volume ?? this.bgmVolume;

    const bgmGain = ctx.createGain();
    bgmGain.gain.setValueAtTime(0.0001, ctx.currentTime);
    bgmGain.gain.linearRampToValueAtTime(target, ctx.currentTime + 1.4);
    bgmGain.connect(this.masterGain);
    this.bgmGain = bgmGain;

    const nodes: AudioNode[] = [bgmGain];

    // Low-pass filter on the drone bus.
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = preset.filterFreq;
    filter.Q.value = 0.7;
    filter.connect(bgmGain);
    nodes.push(filter);

    // Voices.
    for (const [freq, type, gain] of preset.voices) {
      const osc = ctx.createOscillator();
      osc.type = type;
      osc.frequency.value = freq;
      const g = ctx.createGain();
      g.gain.value = gain;
      osc.connect(g).connect(filter);
      osc.start();
      nodes.push(osc, g);

      // Slow detune drift for organic movement.
      const drift = ctx.createOscillator();
      drift.frequency.value = 0.03 + Math.random() * 0.05;
      const driftGain = ctx.createGain();
      driftGain.gain.value = 1.5;
      drift.connect(driftGain).connect(osc.frequency);
      drift.start();
      nodes.push(drift, driftGain);
    }

    // LFO breathing on the master drone gain.
    if (preset.lfoDepth > 0) {
      const lfo = ctx.createOscillator();
      lfo.type = 'sine';
      lfo.frequency.value = preset.lfoFreq;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = preset.lfoDepth * target;
      lfo.connect(lfoGain).connect(bgmGain.gain);
      lfo.start();
      nodes.push(lfo, lfoGain);
    }

    // Optional filtered noise bed (wind / hiss).
    if (preset.noiseGain && preset.noiseGain > 0) {
      const noise = this.createNoiseSource(ctx);
      const noiseFilter = ctx.createBiquadFilter();
      noiseFilter.type = 'lowpass';
      noiseFilter.frequency.value = preset.noiseFilter ?? 400;
      const noiseGain = ctx.createGain();
      noiseGain.gain.value = preset.noiseGain;
      noise.connect(noiseFilter).connect(noiseGain).connect(bgmGain);
      noise.start();
      nodes.push(noise, noiseFilter, noiseGain);
    }

    // Optional rhythmic pulse (heartbeat / clock tick).
    if (preset.pulseHz && preset.pulseGain) {
      const pulse = ctx.createOscillator();
      pulse.type = 'sine';
      pulse.frequency.value = 60;
      const pulseGain = ctx.createGain();
      pulseGain.gain.value = 0; // shaped by LFO gate
      pulse.connect(pulseGain).connect(bgmGain);
      pulse.start();
      // Gate via a second LFO to create sharp pulses.
      const gate = ctx.createOscillator();
      gate.type = 'sawtooth';
      gate.frequency.value = preset.pulseHz;
      const gateGain = ctx.createGain();
      gateGain.gain.value = preset.pulseGain * target;
      // Shape sawtooth into a short blip using a waveshaper-ish gain curve.
      const gateShaper = ctx.createWaveShaper();
      gateShaper.curve = this.makePulseCurve();
      gate.connect(gateShaper).connect(gateGain).connect(pulseGain.gain);
      gate.start();
      nodes.push(pulse, pulseGain, gate, gateGain, gateShaper);
    }

    this.bgmNodes = nodes;
    this.currentTrack = track;
  }

  private fadeOutAndDispose(gain: GainNode, nodes: AudioNode[], seconds: number) {
    const ctx = this.ctx;
    if (!ctx) return;
    try {
      gain.gain.cancelScheduledValues(ctx.currentTime);
      gain.gain.setValueAtTime(gain.gain.value, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.0001, ctx.currentTime + seconds);
    } catch {
      /* ignore */
    }
    setTimeout(() => {
      for (const n of nodes) {
        try {
          if ('stop' in n && typeof (n as OscillatorNode).stop === 'function') {
            (n as OscillatorNode).stop();
          }
          n.disconnect();
        } catch {
          /* ignore */
        }
      }
    }, seconds * 1000 + 80);
  }

  stopBGM() {
    if (!this.ctx) return;
    if (this.bgmGain && this.bgmNodes.length > 0) {
      this.fadeOutAndDispose(this.bgmGain, this.bgmNodes, 0.7);
      this.bgmNodes = [];
      this.bgmGain = null;
    }
    this.currentTrack = null;
  }

  /** Hard cut — dramatic silence before a death or reveal. */
  cutAll() {
    if (!this.ctx) return;
    if (this.bgmGain) {
      try {
        this.bgmGain.gain.cancelScheduledValues(this.ctx.currentTime);
        this.bgmGain.gain.setTargetAtTime(0.0001, this.ctx.currentTime, 0.02);
      } catch {
        /* ignore */
      }
    }
    this.currentTrack = null;
  }

  // --- SFX -----------------------------------------------------------------
  playSFX(name: SfxName | string) {
    const ctx = this.ensureContext();
    if (!ctx || !this.masterGain) return;
    switch (name) {
      case 'click':
        this.sfxClick(ctx);
        break;
      case 'stinger':
        this.sfxStinger(ctx);
        break;
      case 'reveal':
        this.sfxReveal(ctx);
        break;
      case 'death':
        this.sfxDeath(ctx);
        break;
      case 'type':
        this.sfxType(ctx);
        break;
      case 'hover':
        this.sfxHover(ctx);
        break;
      case 'chime':
        this.sfxChime(ctx);
        break;
      case 'rumble':
        this.sfxRumble(ctx);
        break;
      case 'whoosh':
        this.sfxWhoosh(ctx);
        break;
      case 'phone_ring':
        this.startPhoneRing();
        break;
      case 'phone_busy':
        this.stopPhoneRing();
        this.sfxPhoneBusy(ctx);
        break;
      case 'phone_pickup':
        this.stopPhoneRing();
        this.sfxPhonePickup(ctx);
        break;
      case 'objection':
        this.sfxObjection(ctx);
        break;
      default:
        // Unknown name — fall back to a soft click so UI still feels responsive.
        this.sfxClick(ctx);
    }
  }

  private sfxClick(ctx: AudioContext) {
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.setValueAtTime(820, t);
    osc.frequency.exponentialRampToValueAtTime(180, t + 0.04);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.18, t + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.06);
    osc.connect(g).connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 0.08);
  }

  private sfxStinger(ctx: AudioContext) {
    const t = ctx.currentTime;
    // Dissonant cluster — tritone + high shriek.
    const freqs = [220, 311.13, 466.16, 932.32];
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.32, t + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.7);
    g.connect(this.masterGain!);

    for (const f of freqs) {
      const osc = ctx.createOscillator();
      osc.type = 'sawtooth';
      osc.frequency.value = f;
      const oscGain = ctx.createGain();
      oscGain.gain.value = 0.25;
      osc.connect(oscGain).connect(g);
      osc.start(t);
      osc.stop(t + 0.75);
    }

    // Noise burst for the "hit".
    const noise = this.createNoiseSource(ctx);
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'highpass';
    noiseFilter.frequency.value = 1500;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(this.sfxVolume * 0.25, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, t + 0.25);
    noise.connect(noiseFilter).connect(noiseGain).connect(this.masterGain!);
    noise.start(t);
    noise.stop(t + 0.3);
  }

  private sfxReveal(ctx: AudioContext) {
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(420, t);
    osc.frequency.exponentialRampToValueAtTime(1320, t + 0.35);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.22, t + 0.05);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
    osc.connect(g).connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 0.5);

    // Sparkle harmonic.
    const osc2 = ctx.createOscillator();
    osc2.type = 'triangle';
    osc2.frequency.setValueAtTime(840, t + 0.08);
    osc2.frequency.exponentialRampToValueAtTime(2640, t + 0.4);
    const g2 = ctx.createGain();
    g2.gain.setValueAtTime(0.0001, t + 0.08);
    g2.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.08, t + 0.15);
    g2.gain.exponentialRampToValueAtTime(0.0001, t + 0.5);
    osc2.connect(g2).connect(this.masterGain!);
    osc2.start(t + 0.08);
    osc2.stop(t + 0.55);
  }

  // Ace Attorney-style objection stab: a short rising brass-like hit on a
  // perfect fifth, with a bright noise attack. Sells the "you found the
  // contradiction" moment in cross-examination. Distinct from reveal (a
  // sine sparkle) and stinger (a dissonant shriek) so the player reads it
  // as a triumphant hit, not dread or generic success.
  private sfxObjection(ctx: AudioContext) {
    const t = ctx.currentTime;
    // Two brass-ish sawtooth voices a fifth apart (root + fifth), quick rise.
    const root = ctx.createOscillator();
    root.type = 'sawtooth';
    root.frequency.setValueAtTime(330, t);
    root.frequency.exponentialRampToValueAtTime(392, t + 0.12);
    const fifth = ctx.createOscillator();
    fifth.type = 'sawtooth';
    fifth.frequency.setValueAtTime(494, t);
    fifth.frequency.exponentialRampToValueAtTime(587, t + 0.12);
    // Bright octave shimmer on top for the "crack" of the voice.
    const shimmer = ctx.createOscillator();
    shimmer.type = 'triangle';
    shimmer.frequency.setValueAtTime(988, t);
    shimmer.frequency.exponentialRampToValueAtTime(1175, t + 0.1);

    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.28, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.5);
    g.connect(this.masterGain!);

    const rootG = ctx.createGain();
    rootG.gain.value = 0.4;
    const fifthG = ctx.createGain();
    fifthG.gain.value = 0.32;
    const shimG = ctx.createGain();
    shimG.gain.value = 0.18;
    root.connect(rootG).connect(g);
    fifth.connect(fifthG).connect(g);
    shimmer.connect(shimG).connect(g);
    root.start(t);
    fifth.start(t);
    shimmer.start(t);
    root.stop(t + 0.55);
    fifth.stop(t + 0.55);
    shimmer.stop(t + 0.5);

    // Noise attack for the percussive "thwack".
    const noise = this.createNoiseSource(ctx);
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'highpass';
    noiseFilter.frequency.value = 900;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(this.sfxVolume * 0.2, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, t + 0.12);
    noise.connect(noiseFilter).connect(noiseGain).connect(this.masterGain!);
    noise.start(t);
    noise.stop(t + 0.15);
  }

  private sfxDeath(ctx: AudioContext) {
    const t = ctx.currentTime;
    // Descending sub drop.
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(140, t);
    osc.frequency.exponentialRampToValueAtTime(28, t + 1.4);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.4, t + 0.05);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.6);
    osc.connect(g).connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 1.7);

    // Noise rumble.
    const noise = this.createNoiseSource(ctx);
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'lowpass';
    noiseFilter.frequency.setValueAtTime(800, t);
    noiseFilter.frequency.exponentialRampToValueAtTime(120, t + 1.2);
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(this.sfxVolume * 0.2, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, t + 1.5);
    noise.connect(noiseFilter).connect(noiseGain).connect(this.masterGain!);
    noise.start(t);
    noise.stop(t + 1.6);
  }

  // Soft per-letter typewriter tick — very short, very quiet, slightly
  // pitch-randomised so a run of letters feels organic rather than mechanical.
  private sfxType(ctx: AudioContext) {
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'square';
    const base = 1200 + Math.random() * 400;
    osc.frequency.setValueAtTime(base, t);
    osc.frequency.exponentialRampToValueAtTime(base * 0.6, t + 0.02);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.05, t + 0.002);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.03);
    osc.connect(g).connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 0.04);
  }

  // UI hover blip — tiny upward chirp for button focus feedback.
  private sfxHover(ctx: AudioContext) {
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(520, t);
    osc.frequency.exponentialRampToValueAtTime(740, t + 0.04);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.06, t + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.06);
    osc.connect(g).connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 0.07);
  }

  // Clue discovered chime — a soft bell pair, bright but melancholy.
  private sfxChime(ctx: AudioContext) {
    const t = ctx.currentTime;
    const freqs = [880, 1318.5]; // A5 + E6, a perfect fifth
    for (let i = 0; i < freqs.length; i++) {
      const f = freqs[i];
      const start = t + i * 0.08;
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = f;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.18 * (i === 0 ? 1 : 0.7), start + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, start + 0.9);
      osc.connect(g).connect(this.masterGain!);
      osc.start(start);
      osc.stop(start + 1.0);
    }
    // Faint shimmer harmonic an octave up.
    const shimmer = ctx.createOscillator();
    shimmer.type = 'sine';
    shimmer.frequency.value = 2637;
    const sg = ctx.createGain();
    sg.gain.setValueAtTime(0.0001, t + 0.12);
    sg.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.05, t + 0.16);
    sg.gain.exponentialRampToValueAtTime(0.0001, t + 1.1);
    shimmer.connect(sg).connect(this.masterGain!);
    shimmer.start(t + 0.12);
    shimmer.stop(t + 1.2);
  }

  // Rule card reveal rumble — a long low-end swell that lands like a gavel.
  private sfxRumble(ctx: AudioContext) {
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(70, t);
    osc.frequency.exponentialRampToValueAtTime(35, t + 1.2);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.35, t + 0.1);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.4);
    osc.connect(g).connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 1.5);

    // Filtered noise bed for the "weight" of the rumble.
    const noise = this.createNoiseSource(ctx);
    const nf = ctx.createBiquadFilter();
    nf.type = 'lowpass';
    nf.frequency.value = 200;
    const ng = ctx.createGain();
    ng.gain.setValueAtTime(0.0001, t);
    ng.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.12, t + 0.15);
    ng.gain.exponentialRampToValueAtTime(0.0001, t + 1.2);
    noise.connect(nf).connect(ng).connect(this.masterGain!);
    noise.start(t);
    noise.stop(t + 1.3);
  }

  // Scene transition whoosh — a quick filtered noise sweep that sells the wipe.
  private sfxWhoosh(ctx: AudioContext) {
    const t = ctx.currentTime;
    const noise = this.createNoiseSource(ctx);
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.Q.value = 0.8;
    filter.frequency.setValueAtTime(300, t);
    filter.frequency.exponentialRampToValueAtTime(2400, t + 0.25);
    filter.frequency.exponentialRampToValueAtTime(400, t + 0.6);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.18, t + 0.08);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.65);
    noise.connect(filter).connect(g).connect(this.masterGain!);
    noise.start(t);
    noise.stop(t + 0.7);
  }

  // Phone ring — a classic two-tone bell pattern that loops until stopped.
  // We schedule ~6 seconds ahead and re-arm via setTimeout so the ring
  // keeps going for as long as the player ignores the call. Stop by calling
  // stopPhoneRing() (also called from phone_pickup / phone_busy).
  startPhoneRing() {
    // Already ringing — don't stack a second bell on top.
    if (this.phoneRingNodes.length > 0 || this.phoneRingTimer !== null) return;
    const ring = () => {
      if (!this.ctx || !this.masterGain) return;
      const t = this.ctx.currentTime;
      // Two alternating tones — the classic "ring-ring" cadence.
      // 440Hz for ~0.4s, silence, 440Hz for ~0.4s, then ~2s silence, repeat.
      const ringTone = (start: number) => {
        const osc = this.ctx!.createOscillator();
        osc.type = 'sine';
        osc.frequency.value = 440;
        // Add a higher harmonic for the bell character.
        const harm = this.ctx!.createOscillator();
        harm.type = 'sine';
        harm.frequency.value = 880;
        const g = this.ctx!.createGain();
        g.gain.setValueAtTime(0.0001, start);
        g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.18, start + 0.03);
        g.gain.setValueAtTime(this.sfxVolume * 0.18, start + 0.3);
        g.gain.exponentialRampToValueAtTime(0.0001, start + 0.45);
        const harmGain = this.ctx!.createGain();
        harmGain.gain.setValueAtTime(0.0001, start);
        harmGain.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.06, start + 0.04);
        harmGain.gain.exponentialRampToValueAtTime(0.0001, start + 0.45);
        osc.connect(g).connect(this.masterGain!);
        harm.connect(harmGain).connect(this.masterGain!);
        osc.start(start);
        harm.start(start);
        osc.stop(start + 0.5);
        harm.stop(start + 0.5);
        this.phoneRingNodes.push(osc, harm, g, harmGain);
      };
      // Ring-ring cadence: two bursts, then ~2s of silence, then loop.
      ringTone(t);
      ringTone(t + 0.6);
      // Re-arm. The 3s interval gives the classic ring-ring... ring-ring...
      // pacing without hammering the listener.
      this.phoneRingTimer = window.setTimeout(ring, 3000);
      // Prune disposed nodes so the array doesn't grow unbounded.
      this.phoneRingNodes = this.phoneRingNodes.filter((n) => {
        try {
          return !(n as OscillatorNode).context;
        } catch {
          return false;
        }
      });
    };
    ring();
  }

  stopPhoneRing() {
    if (this.phoneRingTimer !== null) {
      window.clearTimeout(this.phoneRingTimer);
      this.phoneRingTimer = null;
    }
    for (const n of this.phoneRingNodes) {
      try {
        if ('stop' in n && typeof (n as OscillatorNode).stop === 'function') {
          (n as OscillatorNode).stop();
        }
        n.disconnect();
      } catch {
        /* ignore */
      }
    }
    this.phoneRingNodes = [];
  }

  // Phone busy — the engage tone when the player declines a call. Two
  // short low beeps, dense and final.
  private sfxPhoneBusy(ctx: AudioContext) {
    const t = ctx.currentTime;
    for (let i = 0; i < 2; i++) {
      const start = t + i * 0.22;
      const osc = ctx.createOscillator();
      osc.type = 'square';
      osc.frequency.value = 480;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.15, start + 0.01);
      g.gain.setValueAtTime(this.sfxVolume * 0.15, start + 0.15);
      g.gain.exponentialRampToValueAtTime(0.0001, start + 0.18);
      osc.connect(g).connect(this.masterGain!);
      osc.start(start);
      osc.stop(start + 0.2);
    }
  }

  // Phone pickup — a soft click followed by a connect chirp, signalling
  // the line opened and the caller is now speaking.
  private sfxPhonePickup(ctx: AudioContext) {
    const t = ctx.currentTime;
    // Click
    const click = ctx.createOscillator();
    click.type = 'square';
    click.frequency.setValueAtTime(220, t);
    click.frequency.exponentialRampToValueAtTime(80, t + 0.03);
    const cg = ctx.createGain();
    cg.gain.setValueAtTime(0.0001, t);
    cg.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.12, t + 0.005);
    cg.gain.exponentialRampToValueAtTime(0.0001, t + 0.05);
    click.connect(cg).connect(this.masterGain!);
    click.start(t);
    click.stop(t + 0.06);
    // Connect chirp
    const chirp = ctx.createOscillator();
    chirp.type = 'sine';
    chirp.frequency.setValueAtTime(600, t + 0.08);
    chirp.frequency.exponentialRampToValueAtTime(900, t + 0.18);
    const chg = ctx.createGain();
    chg.gain.setValueAtTime(0.0001, t + 0.08);
    chg.gain.exponentialRampToValueAtTime(this.sfxVolume * 0.08, t + 0.12);
    chg.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    chirp.connect(chg).connect(this.masterGain!);
    chirp.start(t + 0.08);
    chirp.stop(t + 0.24);
  }

  // --- Helpers -------------------------------------------------------------
  private createNoiseSource(ctx: AudioContext): AudioBufferSourceNode {
    const buffer = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    return src;
  }

  private makePulseCurve(): Float32Array {
    // Shape a sawtooth into short positive blips (sharp attack, fast decay).
    const n = 1024;
    const curve = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      const x = (i / n) * 2 - 1;
      // Only the top of the sawtooth passes signal — creates a narrow pulse.
      curve[i] = x > 0.6 ? (x - 0.6) / 0.4 : 0;
    }
    return curve;
  }
}

export const audio = new AudioEngine();
