import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useGame } from '@/engine/store';
import { Puzzle, X } from 'lucide-react';

export const CLUE_NAMES: Record<string, string> = {
  clue_white_room: 'The White Room — punishment is not always immediate',
  clue_corridor: 'The Corridor — a rule that leads into the dark is the dark itself',
  clue_corridor_fail: 'The Corridor — you followed the trap to learn its name',
  clue_feast: 'The Feast — the lie always promises more than the truth',
  clue_mirror: 'The Mirror — the traitor and the ally can be the same person',
  clue_clock: 'The Clock — the one who breaks the game becomes the game',
  clue_choice: 'The Choice — refusal is a move the game cannot answer',
  clue_truth: 'The Truth — the lie is that the game can be won by playing',
  clue_dream_fragment: 'The Dream — you have been here before. You cannot remember how it ends',
  clue_old_photo: 'The Photograph — seven faces, but one has no reflection',
  clue_overheard: 'The Whisper — someone here has played this game before you',
  // [HIDDEN THREAD] Suspect clues — these do not name a culprit. They are
  // fragments of behaviour that only make sense if someone in the room has
  // been here before. The player must combine them to form a theory.
  clue_suspect_opening: 'The Opening — two of them answered too quickly. As if they had rehearsed',
  clue_suspect_linye: 'Lin Ye — he spoke of what the game "rewards" before the game had rewarded anything',
  clue_suspect_baijing: 'Bai Jing — she reports to the game. The game reports to no one. Who does she serve?',
  clue_suspect_loop: 'The Loop — a voice that is no one\'s has watched Su-wan die three times. Someone else is counting',
  clue_outside_contact: 'Elena Krause — a voice from outside the room. She sat in your seat three loops ago and walked out',
};

// Per-clue SVG glyphs. Each is a small abstract sigil keyed to the scene the
// clue came from, rendered in the bone/blood palette so the board reads as a
// collected set of occult marks rather than a plain text list.
function ClueIcon({ id }: { id: string }) {
  const common = {
    width: 28,
    height: 28,
    viewBox: '0 0 32 32',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 1.4,
    className: 'shrink-0 text-blood-bright',
  } as const;
  switch (id) {
    case 'clue_white_room':
      // Empty rectangle — the featureless room.
      return (
        <svg {...common}>
          <rect x="6" y="6" width="20" height="20" rx="1" />
          <circle cx="16" cy="16" r="1.5" fill="currentColor" stroke="none" />
        </svg>
      );
    case 'clue_corridor':
    case 'clue_corridor_fail':
      // Converging lines — the vanishing-point corridor.
      return (
        <svg {...common}>
          <path d="M4 6 L28 16 L4 26" />
          <path d="M28 6 L4 16 L28 26" opacity="0.5" />
        </svg>
      );
    case 'clue_feast':
      // A plate / chalice — the empty feast.
      return (
        <svg {...common}>
          <circle cx="16" cy="16" r="9" />
          <circle cx="16" cy="16" r="3" />
          <path d="M16 4 L16 7 M16 25 L16 28" />
        </svg>
      );
    case 'clue_mirror':
      // A rhombus split — fragmented reflection.
      return (
        <svg {...common}>
          <path d="M16 3 L28 16 L16 29 L4 16 Z" />
          <path d="M16 3 L16 29" opacity="0.6" />
        </svg>
      );
    case 'clue_clock':
      // Clock hands — the spinning face.
      return (
        <svg {...common}>
          <circle cx="16" cy="16" r="10" />
          <path d="M16 16 L16 9 M16 16 L21 19" />
        </svg>
      );
    case 'clue_choice':
      // Forked path — the branching choice.
      return (
        <svg {...common}>
          <path d="M16 28 L16 18" />
          <path d="M16 18 L8 8 M16 18 L24 8" />
          <circle cx="8" cy="8" r="1.5" fill="currentColor" stroke="none" />
          <circle cx="24" cy="8" r="1.5" fill="currentColor" stroke="none" />
        </svg>
      );
    case 'clue_truth':
      // An open eye — the revealed lie.
      return (
        <svg {...common}>
          <path d="M3 16 Q16 6 29 16 Q16 26 3 16 Z" />
          <circle cx="16" cy="16" r="3" fill="currentColor" stroke="none" />
        </svg>
      );
    case 'clue_dream_fragment':
      // A crescent moon over waves — the dream void.
      return (
        <svg {...common}>
          <path d="M22 6 A10 10 0 1 0 22 26 A8 8 0 1 1 22 6 Z" />
          <path d="M4 24 Q8 22 12 24 T20 24 T28 24" opacity="0.6" />
        </svg>
      );
    case 'clue_old_photo':
      // A framed photograph — the old photo.
      return (
        <svg {...common}>
          <rect x="5" y="7" width="22" height="18" rx="1" />
          <circle cx="12" cy="14" r="2.5" />
          <path d="M7 23 Q12 18 17 23" />
          <path d="M17 23 Q21 19 25 23" opacity="0.5" />
        </svg>
      );
    case 'clue_overheard':
      // Sound waves — the overheard whisper.
      return (
        <svg {...common}>
          <path d="M4 16 Q4 10 8 10 Q8 16 8 16 Q8 22 4 22 Z" fill="currentColor" stroke="none" opacity="0.6" />
          <path d="M12 12 Q14 16 12 20" />
          <path d="M16 10 Q19 16 16 22" />
          <path d="M20 8 Q24 16 20 24" opacity="0.5" />
        </svg>
      );
    case 'clue_suspect_opening':
      // Two faces, one tilted — the rehearsed answer.
      return (
        <svg {...common}>
          <circle cx="11" cy="16" r="6" />
          <circle cx="22" cy="14" r="5" opacity="0.6" />
          <circle cx="11" cy="16" r="1" fill="currentColor" stroke="none" />
          <circle cx="22" cy="14" r="0.8" fill="currentColor" stroke="none" />
        </svg>
      );
    case 'clue_suspect_linye':
      // An eye that knows — narrow, with a vertical pupil.
      return (
        <svg {...common}>
          <path d="M4 16 Q16 8 28 16 Q16 24 4 16 Z" />
          <ellipse cx="16" cy="16" rx="1.5" ry="3" fill="currentColor" stroke="none" />
        </svg>
      );
    case 'clue_suspect_baijing':
      // A hand reaching up toward a higher rule.
      return (
        <svg {...common}>
          <path d="M16 24 L16 16" />
          <path d="M16 16 L13 12 M16 16 L19 12 M16 16 L16 10" />
          <path d="M8 6 L24 6" opacity="0.5" />
        </svg>
      );
    case 'clue_suspect_loop':
      // An ouroboros — a circle that consumes itself.
      return (
        <svg {...common}>
          <circle cx="16" cy="16" r="9" />
          <path d="M22 11 L25 8 L25 12 L21 12 Z" fill="currentColor" stroke="none" />
          <path d="M10 21 L7 24 L7 20 L11 20 Z" fill="currentColor" stroke="none" />
        </svg>
      );
    case 'clue_outside_contact':
      // A signal reaching inward through a wall — concentric arcs breaking
      // a barrier. Elena, calling from outside.
      return (
        <svg {...common}>
          <path d="M3 16 L13 16" opacity={0.4} />
          <path d="M4 10 Q16 16 4 22" />
          <path d="M8 7 Q20 16 8 25" opacity={0.6} />
          <circle cx="13" cy="16" r="1.4" fill="currentColor" stroke="none" />
        </svg>
      );
    default:
      // Generic sigil for any uncategorised clue.
      return (
        <svg {...common}>
          <path d="M16 4 L19 13 L28 13 L21 19 L24 28 L16 22 L8 28 L11 19 L4 13 L13 13 Z" />
        </svg>
      );
  }
}

// Deduction board: shows collected clues. Accessible from the in-game menu.
export default function DeductionBoard({ onClose }: { onClose: () => void }) {
  const inventory = useGame((s) => s.inventory);
  const deductions = useGame((s) => s.deductions);
  const flags = useGame((s) => s.flags);
  const setFlag = useGame((s) => s.setFlag);

  const clues = inventory.filter((i) => i.startsWith('clue_'));
  const required = ['clue_white_room', 'clue_corridor', 'clue_feast', 'clue_mirror', 'clue_clock'];
  const truthReady = required.every((c) => inventory.includes(c));

  // Suspect clues — the hidden-thread fragments that hint someone in the
  // room has been here before. The "propose a theory" panel only appears
  // once the player has collected at least three of these, so the player
  // has enough material to form a real hypothesis rather than guessing blind.
  const suspectClues = clues.filter((c) => c.startsWith('clue_suspect_'));
  const theoryReady = suspectClues.length >= 3;

  // The player's current theory (if any). Stored in flags so it persists
  // across scenes and can be read by the ending screen for a custom epilogue
  // line. One of: 'linye' | 'baijing' | 'self' | 'nobody'.
  const currentTheory =
    (flags.theory_linye && 'linye') ||
    (flags.theory_baijing && 'baijing') ||
    (flags.theory_self && 'self') ||
    (flags.theory_nobody && 'nobody') ||
    null;

  const [showTheoryPanel, setShowTheoryPanel] = useState(false);

  const proposeTheory = (who: 'linye' | 'baijing' | 'self' | 'nobody') => {
    // Clear any prior theory, then set the new one. Each theory is a single
    // boolean flag so the ending screen can branch on whichever is true.
    setFlag('theory_linye', who === 'linye');
    setFlag('theory_baijing', who === 'baijing');
    setFlag('theory_self', who === 'self');
    setFlag('theory_nobody', who === 'nobody');
    setShowTheoryPanel(false);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-40 flex items-center justify-center bg-void/95 backdrop-blur-md"
    >
      <div className="relative w-full max-w-2xl px-6">
        <button
          onClick={onClose}
          className="absolute right-4 top-4 text-muted hover:text-bone transition-colors"
          aria-label="Close"
        >
          <X size={20} />
        </button>

        <div className="mb-6 flex items-center gap-3">
          <Puzzle size={18} className="text-blood" />
          <h2 className="font-mono text-xs uppercase tracking-[0.4em] text-blood-bright">
            Deduction Board
          </h2>
        </div>

        <p className="mb-5 font-serif text-sm italic text-muted">
          The clues you have gathered. Combine them to find the lie.
        </p>

        <div className="space-y-3">
          {clues.length === 0 && (
            <p className="font-mono text-xs text-muted/60">
              No clues collected yet. Observe. Break the right rules. Remember.
            </p>
          )}
          {clues.map((clue, i) => (
            <motion.div
              key={clue}
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: i * 0.06, duration: 0.3 }}
              className="flex items-start gap-3 border-l-2 border-blood-bright/60 pl-4 py-2"
            >
              <span className="mt-0.5" style={{ filter: 'drop-shadow(0 0 4px rgba(200,30,30,0.4))' }}>
                <ClueIcon id={clue} />
              </span>
              <p className="font-serif text-sm text-bone">
                {CLUE_NAMES[clue] ?? clue}
              </p>
            </motion.div>
          ))}
        </div>

        {deductions.length > 0 && (
          <div className="mt-6 border-t border-ash pt-4">
            <p className="mb-2 font-mono text-[10px] uppercase tracking-widest text-blood">
              Deductions
            </p>
            {deductions.map((d) => (
              <p key={d} className="font-serif text-sm italic text-bone/80">
                ◈ {d.replace(/_/g, ' ')}
              </p>
            ))}
          </div>
        )}

        {truthReady && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5 }}
            className="mt-6 font-serif text-sm italic text-blood-bright"
          >
            You have all the pieces. On the final day, the lie will reveal itself.
          </motion.p>
        )}

        {/* Suspect theory panel — appears once the player has collected at
            least three hidden-thread clues. Lets the player name who they
            believe has been here before. The choice is stored in flags and
            echoed back in the ending screen; it does not change which ending
            is reached, only the epilogue's final line. This is the "verify
            your推理" outlet — the board listens, but does not judge. */}
        {theoryReady && (
          <div className="mt-6 border-t border-ash pt-4">
            <p className="mb-2 font-mono text-[10px] uppercase tracking-widest text-blood">
              Suspect Theory
            </p>
            <p className="mb-3 font-serif text-sm italic text-muted">
              You have gathered enough fragments to form a theory. Who do you
              believe has played this game before you?
            </p>
            <AnimatePresence mode="wait">
              {currentTheory && !showTheoryPanel ? (
                <motion.div
                  key="theory-set"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="flex items-center justify-between gap-3"
                >
                  <p className="font-serif text-sm text-bone">
                    Your theory:{' '}
                    <span className="text-blood-bright">
                      {currentTheory === 'linye' && 'Lin Ye remembers.'}
                      {currentTheory === 'baijing' && 'Bai Jing serves the game.'}
                      {currentTheory === 'self' && 'You have been here before.'}
                      {currentTheory === 'nobody' && 'The traitor is the game itself.'}
                    </span>
                  </p>
                  <button
                    onClick={() => setShowTheoryPanel(true)}
                    className="font-mono text-[9px] uppercase tracking-wider text-muted hover:text-blood-bright transition-colors"
                  >
                    revise
                  </button>
                </motion.div>
              ) : showTheoryPanel ? (
                <motion.div
                  key="theory-form"
                  initial={{ opacity: 0, y: 6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -6 }}
                  className="flex flex-col gap-2"
                >
                  {([
                    ['linye', 'Lin Ye — he speaks of what the game "rewards".'],
                    ['baijing', 'Bai Jing — she reports to the game.'],
                    ['self', 'Yourself — you have been here before.'],
                    ['nobody', 'No one — the traitor is the game itself.'],
                  ] as const).map(([who, label]) => (
                    <button
                      key={who}
                      onClick={() => proposeTheory(who)}
                      className="vn-choice px-4 py-2 text-left font-serif text-sm text-bone hover:text-white"
                    >
                      {label}
                    </button>
                  ))}
                  <button
                    onClick={() => setShowTheoryPanel(false)}
                    className="mt-1 font-mono text-[9px] uppercase tracking-wider text-muted hover:text-bone transition-colors"
                  >
                    cancel
                  </button>
                </motion.div>
              ) : (
                <motion.button
                  key="theory-open"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  onClick={() => setShowTheoryPanel(true)}
                  className="vn-choice px-4 py-2 text-left font-mono text-[10px] uppercase tracking-wider text-bone hover:text-white"
                >
                  ◈ Propose a theory
                </motion.button>
              )}
            </AnimatePresence>
          </div>
        )}
      </div>
    </motion.div>
  );
}
