import { motion } from 'framer-motion';
import { useGame } from '@/engine/store';
import { getBackground } from '@/lib/assets';
import SceneFX from './effects/SceneFX';
import { isChapterLocked, getChapterLock } from '@/data/flowchart';
import { audio } from '@/engine/audioEngine';
import { Home, Lock } from 'lucide-react';

// Chapter select — lets the player jump back into the story at any day they
// have reached. Unlocked once the player has finished the game at least once
// (loopCount >= 1) so first-time players are not tempted to skip ahead.
//
// Each entry jumps to the intro scene of that day, inheriting the current
// trust/inventory state. This is not a full save — it is a "rehearsal" mode
// for exploring branches without replaying the whole week.
//
// Keep Out story-locks: spoiler-heavy chapters (e.g. Day 7 — The Truth) are
// gated behind a clue or loop-count condition. The chapter card remains
// visible — the lock is a tease, not a removal — but it cannot be entered
// until the player has gathered the required material in a prior playthrough.

const CHAPTERS: { sceneId: string; day: number; title: string; subtitle: string }[] = [
  { sceneId: 'd1_intro', day: 1, title: 'The White Room', subtitle: 'Seven strangers wake. The screen speaks.' },
  { sceneId: 'd2_intro', day: 2, title: 'The Corridor', subtitle: 'A rule that leads into the dark.' },
  { sceneId: 'd3_intro', day: 3, title: 'The Feast', subtitle: 'The lie that promises mercy.' },
  { sceneId: 'd4_intro', day: 4, title: 'The Mirror', subtitle: 'The traitor and the ally can be the same.' },
  { sceneId: 'd5_intro', day: 5, title: 'The Clock', subtitle: 'Time is taken, not given.' },
  { sceneId: 'd6_intro', day: 6, title: 'The Choice', subtitle: 'One stays so the others may leave.' },
  { sceneId: 'd7_intro', day: 7, title: 'The Truth', subtitle: 'Identify the lie that was true every day.' },
];

// Side stories — optional character arcs unlocked by completing a side
// quest. Rendered with a non-numeric glyph so they read as extras. Only
// shown when the corresponding scene id is in unlockedSideStories.
const CHAPTERS_SIDESTORIES: { sceneId: string; title: string; subtitle: string }[] = [
  {
    sceneId: 'elena_full_story',
    title: 'Elena Krause — The One Who Walked Out',
    subtitle: 'A voice on the line, finally telling you everything.',
  },
];

export default function ChapterSelectScreen() {
  const startChapter = useGame((s) => s.startChapter);
  const goToTitle = useGame((s) => s.goToTitle);
  const inventory = useGame((s) => s.inventory);
  const loopCount = useGame((s) => s.loopCount);
  const unlockedSideStories = useGame((s) => s.unlockedSideStories);
  const { img, gradient } = getBackground('title');

  // Side stories are appended to the chapter list when unlocked. They use a
  // non-numeric day glyph (◊) so they read as extras, not main days.
  const sideStories = CHAPTERS_SIDESTORIES.filter((s) =>
    unlockedSideStories.includes(s.sceneId),
  );

  return (
    <div
      className="relative h-full w-full overflow-hidden"
      style={{ background: gradient }}
    >
      {img && (
        <img
          src={img}
          alt=""
          className="bg-ken-burns absolute inset-0 h-full w-full object-cover opacity-30"
          onError={(e) => {
            (e.currentTarget as HTMLImageElement).style.display = 'none';
          }}
        />
      )}
      <SceneFX backgroundKey="title" />

      <div className="relative z-10 flex h-full flex-col items-center justify-center px-6 py-12 overflow-y-auto">
        <motion.p
          initial={{ opacity: 0, letterSpacing: '0.2em' }}
          animate={{ opacity: 1, letterSpacing: '0.6em' }}
          transition={{ duration: 1 }}
          className="mb-3 font-mono text-[10px] uppercase tracking-[0.6em] text-blood-bright md:text-xs"
        >
          ◊ Chapter Select ◊
        </motion.p>

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3, duration: 0.8 }}
          className="mb-8 max-w-md text-center font-serif text-sm italic text-muted"
        >
          Rehearse any day. Your current trust and clues carry over.
        </motion.p>

        <div className="grid w-full max-w-3xl gap-3 sm:grid-cols-2">
          {CHAPTERS.map((ch, i) => {
            const locked = isChapterLocked(ch.sceneId, inventory, loopCount);
            const lock = getChapterLock(ch.sceneId);
            return (
              <motion.button
                key={ch.sceneId}
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 + i * 0.08, duration: 0.4 }}
                whileHover={locked ? {} : { scale: 1.02, x: 4 }}
                whileTap={locked ? {} : { scale: 0.98 }}
                onClick={() => {
                  if (locked) {
                    // Locked chapters can't be entered — a soft stinger
                    // reinforces the "Keep Out" beat without nagging.
                    audio.playSFX('stinger');
                    return;
                  }
                  startChapter(ch.sceneId);
                }}
                className={[
                  'vn-choice group relative overflow-hidden px-5 py-4 text-left',
                  locked ? 'cursor-not-allowed opacity-60' : '',
                ].join(' ')}
              >
                <div className="flex items-baseline gap-3">
                  <span
                    className={[
                      'font-serif text-2xl font-semibold',
                      locked ? 'text-muted/60' : 'text-blood-bright',
                    ].join(' ')}
                  >
                    {ch.day}
                  </span>
                  <div className="flex-1">
                    <p
                      className={[
                        'font-serif text-base',
                        locked ? 'text-muted/70' : 'text-bone group-hover:text-white',
                      ].join(' ')}
                    >
                      {ch.title}
                    </p>
                    <p className="mt-0.5 font-mono text-[9px] uppercase tracking-wider text-muted">
                      {ch.subtitle}
                    </p>
                  </div>
                  {locked && (
                    <Lock
                      size={14}
                      className="shrink-0 text-blood-bright/70 animate-pulse-slow"
                    />
                  )}
                </div>
                {/* Keep Out overlay — a faint red barrier over the locked
                    chapter, with the lock's flavour text. The card stays
                    visible (the player can see what they're missing) but
                    cannot be entered. */}
                {locked && lock && (
                  <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
                    <div className="absolute inset-0 border-2 border-dashed border-blood/40" />
                    <span className="relative bg-void/80 px-3 py-1 font-mono text-[9px] uppercase tracking-[0.3em] text-blood-bright">
                      {lock.lockText}
                    </span>
                  </div>
                )}
              </motion.button>
            );
          })}
        </div>

        {/* Side stories — unlocked optional arcs. Rendered below the main
            week so the seven days stay the primary structure. Each is a
            single long scene reachable only when its quest is complete. */}
        {sideStories.length > 0 && (
          <div className="mt-6 w-full max-w-3xl">
            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.6, duration: 0.8 }}
              className="mb-3 text-center font-mono text-[9px] uppercase tracking-[0.4em] text-blood-bright/70"
            >
              ◊ Side Stories ◊
            </motion.p>
            <div className="grid gap-3 sm:grid-cols-2">
              {sideStories.map((s, i) => (
                <motion.button
                  key={s.sceneId}
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.7 + i * 0.08, duration: 0.4 }}
                  whileHover={{ scale: 1.02, x: 4 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => startChapter(s.sceneId)}
                  className="vn-choice group relative overflow-hidden px-5 py-4 text-left"
                >
                  <div className="flex items-baseline gap-3">
                    <span className="font-serif text-2xl font-semibold text-blood-bright">
                      ◊
                    </span>
                    <div className="flex-1">
                      <p className="font-serif text-base text-bone group-hover:text-white">
                        {s.title}
                      </p>
                      <p className="mt-0.5 font-mono text-[9px] uppercase tracking-wider text-muted">
                        {s.subtitle}
                      </p>
                    </div>
                  </div>
                </motion.button>
              ))}
            </div>
          </div>
        )}

        <motion.button
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1 + CHAPTERS.length * 0.08 }}
          onClick={goToTitle}
          className="vn-choice mt-8 flex items-center gap-2 px-6 py-2.5 font-mono text-xs uppercase tracking-[0.3em] text-bone hover:text-white"
        >
          <Home size={12} /> Back
        </motion.button>
      </div>
    </div>
  );
}
