import { useEffect, useRef, useState } from 'react';

// Decrypted text: cycles random glyphs before resolving to the target text,
// left to right. Inspired by React Bits' DecryptedText but tuned for the
// horror aesthetic — encrypted chars are blood-red, resolved chars are bone.
// Used for system / glitch dialogue lines so the Game Master's voice arrives
// like a signal breaking through static rather than a plain CSS text-shadow.

const SCRAMBLE_CHARS =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*<>?/\\|~';

// Pure helper — has no dependency on props/state, so it lives outside the
// component to avoid being re-created on every render and to make the
// useState initializer below read naturally top-to-bottom.
function pickRandom(): string {
  return SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)];
}

interface Props {
  text: string;
  /** ms between each scramble frame */
  speed?: number;
  /** max random iterations per character before it locks in */
  maxIterations?: number;
  /** class applied to resolved characters */
  className?: string;
  /** class applied to still-scrambling characters */
  encryptedClassName?: string;
}

export default function DecryptedText({
  text,
  speed = 40,
  maxIterations = 8,
  className = '',
  encryptedClassName = '',
}: Props) {
  const [display, setDisplay] = useState<string[]>(() =>
    Array.from(text, () => pickRandom()),
  );
  // Per-character iteration counter so each glyph locks in independently.
  const countersRef = useRef<number[]>(Array.from({ length: text.length }, () => 0));
  const frameRef = useRef<number | null>(null);

  useEffect(() => {
    // Reset when text changes: scramble every letter/digit so the new line
    // arrives as static, then resolves left-to-right.
    countersRef.current = Array.from({ length: text.length }, () => 0);
    setDisplay(Array.from(text, () => pickRandom()));

    const tick = () => {
      const next = text.split('');
      let allDone = true;
      for (let i = 0; i < text.length; i++) {
        // Spaces and punctuation lock in immediately — only letters scramble.
        const ch = text[i];
        if (ch === ' ' || !/[A-Za-z0-9]/.test(ch)) {
          next[i] = ch;
          continue;
        }
        if (countersRef.current[i] >= maxIterations) {
          next[i] = ch;
          continue;
        }
        // Stagger the lock-in so characters resolve left-to-right: a position
        // only starts iterating after the previous one has resolved ~60%.
        const prevLock = countersRef.current[i - 1] ?? maxIterations;
        if (prevLock < maxIterations * 0.6) {
          next[i] = pickRandom();
          allDone = false;
          continue;
        }
        countersRef.current[i] += 1;
        next[i] =
          countersRef.current[i] >= maxIterations ? ch : pickRandom();
        if (countersRef.current[i] < maxIterations) allDone = false;
      }
      setDisplay(next);
      if (!allDone) {
        frameRef.current = window.setTimeout(tick, speed);
      }
    };
    frameRef.current = window.setTimeout(tick, speed);
    return () => {
      if (frameRef.current) window.clearTimeout(frameRef.current);
    };
  }, [text, speed, maxIterations]);

  return (
    <span className="inline-block whitespace-pre-wrap">
      {display.map((ch, i) => {
        const resolved = countersRef.current[i] >= maxIterations || !/[A-Za-z0-9]/.test(text[i] ?? '');
        return (
          <span
            key={i}
            className={resolved ? className : encryptedClassName}
          >
            {ch}
          </span>
        );
      })}
    </span>
  );
}
