import { useMemo } from 'react';

// Aceternity-inspired Meteors: 从屏幕右上角斜向划入的流星雨。
// 参考来源: https://ui.aceternity.com/components/meteors
//
// 适配本项目：流星改为 blood-red 拖尾，从右上斜向左下划过，
// 用于 TitleScreen 营造"规则从天而降"的不安感。每颗流星有独立的
// delay + duration，错落出现，避免整齐划一的机械感。
// 仅在桌面端可见（移动端性能考虑），prefers-reduced-motion 时停止。

interface Props {
  /** 流星数量（默认 12） */
  number?: number;
  className?: string;
}

// 用 mulberry32 伪随机生成稳定的流星布局，避免 re-render 时重排。
function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export default function Meteors({ number = 12, className = '' }: Props) {
  const meteors = useMemo(() => {
    const rand = mulberry32(7);
    return Array.from({ length: number }, () => ({
      top: `${Math.round(rand() * 60)}%`, // 只在屏幕上半部分生成
      left: `${Math.round(40 + rand() * 60)}%`, // 只在屏幕右半部分生成
      delay: `${(rand() * 8).toFixed(2)}s`,
      duration: `${(3 + rand() * 4).toFixed(2)}s`,
      length: `${Math.round(80 + rand() * 120)}px`, // 拖尾长度
    }));
  }, [number]);

  return (
    <div
      aria-hidden
      className={`pointer-events-none absolute inset-0 overflow-hidden ${className}`}
    >
      {meteors.map((m, i) => (
        <span
          key={i}
          className="absolute block animate-meteor"
          style={{
            top: m.top,
            left: m.left,
            animationDelay: m.delay,
            animationDuration: m.duration,
            // 流星本体 + 拖尾：用线性渐变制造从亮到透明的拖尾效果，
            // 旋转 -45deg 让流星从右上斜向左下划过。
            width: m.length,
            height: '1px',
            background:
              'linear-gradient(90deg, rgba(200,30,30,0) 0%, rgba(200,30,30,0.6) 50%, rgba(232,232,232,0.95) 100%)',
            transform: 'rotate(-45deg)',
            boxShadow: '0 0 6px rgba(200,30,30,0.5)',
            opacity: 0,
          }}
        />
      ))}
    </div>
  );
}
