import { useState } from 'react';
import { motion } from 'framer-motion';
import { useGame } from '@/engine/store';
import { listSaveSlots, deleteSave, type SaveSlotMeta } from '@/engine/saveManager';
import { ArrowLeft, Save, Trash2, Upload } from 'lucide-react';

export default function SaveLoadScreen({ mode }: { mode: 'save' | 'load' }) {
  const setScreen = useGame((s) => s.setScreen);
  const saveToSlot = useGame((s) => s.saveToSlot);
  const loadFromSlot = useGame((s) => s.loadFromSlot);
  const [slots, setSlots] = useState<SaveSlotMeta[]>(() => listSaveSlots());

  const refresh = () => setSlots(listSaveSlots());

  const handleSave = (slot: number) => {
    saveToSlot(slot);
    refresh();
  };
  const handleLoad = (slot: number | 'autosave') => {
    loadFromSlot(slot as unknown as number);
  };
  const handleDelete = (slot: number | 'autosave') => {
    deleteSave(slot);
    refresh();
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="absolute inset-0 z-40 flex flex-col bg-void"
    >
      <header className="flex items-center justify-between border-b border-ash px-6 py-4">
        <button
          onClick={() => setScreen('title')}
          className="flex items-center gap-2 font-mono text-xs uppercase tracking-widest text-muted hover:text-bone transition-colors"
        >
          <ArrowLeft size={14} /> Back
        </button>
        <h2 className="font-mono text-xs uppercase tracking-[0.4em] text-blood-bright">
          {mode === 'save' ? 'Save Game' : 'Load Game'}
        </h2>
        <span className="w-12" />
      </header>

      <div className="flex-1 overflow-y-auto p-6">
        <div className="mx-auto grid max-w-3xl gap-3">
          {/* Autosave slot */}
          <SaveRow
            meta={slots.find((s) => s.slot === 'autosave')}
            label="Autosave"
            mode={mode}
            onSave={() => handleSave(0)}
            onLoad={() => handleLoad('autosave')}
            onDelete={() => handleDelete('autosave')}
          />

          {/* 5 manual slots */}
          {Array.from({ length: 5 }).map((_, i) => {
            const slotNum = i + 1;
            const meta = slots.find((s) => s.slot === slotNum);
            return (
              <SaveRow
                key={slotNum}
                meta={meta}
                label={`Slot ${slotNum}`}
                mode={mode}
                onSave={() => handleSave(slotNum)}
                onLoad={() => handleLoad(slotNum)}
                onDelete={() => handleDelete(slotNum)}
              />
            );
          })}
        </div>
      </div>
    </motion.div>
  );
}

function SaveRow({
  meta,
  label,
  mode,
  onSave,
  onLoad,
  onDelete,
}: {
  meta?: SaveSlotMeta;
  label: string;
  mode: 'save' | 'load';
  onSave: () => void;
  onLoad: () => void;
  onDelete: () => void;
}) {
  const date = meta ? new Date(meta.timestamp) : null;
  const isSalvation = meta?.gameMode === 'salvation';
  return (
    <div className="vn-panel flex items-center justify-between gap-4 px-5 py-4">
      <div className="flex-1">
        <div className="flex items-center gap-3">
          <span className="font-mono text-xs uppercase tracking-widest text-bone">
            {label}
          </span>
          {meta && meta.loopCount > 0 && (
            <span className="font-mono text-[10px] text-blood-bright">
              ◊ Loop {meta.loopCount}
            </span>
          )}
          {meta && isSalvation && (
            <span className="font-mono text-[10px] text-bone/70">
              ◊ Salvation
            </span>
          )}
        </div>
        {meta ? (
          <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-0.5 font-mono text-[10px] uppercase tracking-wider text-muted">
            {isSalvation ? (
              <>
                <span>Round {meta.chapter || 1} / 3</span>
                <span className="text-bone/80">Freed {meta.savedCount ?? 0}</span>
                <span className="text-blood-bright/80">Lost {meta.punishedCount ?? 0}</span>
              </>
            ) : (
              <>
                <span>Day {meta.chapter} / 7</span>
                <span>Sanity {meta.sanity}</span>
              </>
            )}
            <span>{date?.toLocaleString()}</span>
          </div>
        ) : (
          <p className="mt-1 font-mono text-[10px] uppercase tracking-wider text-muted/50">
            — Empty —
          </p>
        )}
      </div>

      <div className="flex items-center gap-2">
        {meta && (
          <>
            {mode === 'load' && (
              <button
                onClick={onLoad}
                className="flex items-center gap-1.5 border border-blood/40 px-3 py-2 font-mono text-[10px] uppercase tracking-wider text-bone hover:border-blood-bright hover:text-white transition-colors"
              >
                <Upload size={12} /> Load
              </button>
            )}
            <button
              onClick={onDelete}
              className="border border-ash p-2 text-muted hover:border-blood hover:text-blood-bright transition-colors"
              aria-label="Delete save"
            >
              <Trash2 size={12} />
            </button>
          </>
        )}
        {mode === 'save' && (
          <button
            onClick={onSave}
            className="flex items-center gap-1.5 border border-blood/40 px-3 py-2 font-mono text-[10px] uppercase tracking-wider text-bone hover:border-blood-bright hover:text-white transition-colors"
          >
            <Save size={12} /> Save
          </button>
        )}
      </div>
    </div>
  );
}
