// Starting scene for a fresh game.
export const START_SCENE_ID = "d1_intro";

// Determine whether the player has gathered enough clues for the true ending.
export function hasAllClues(items: string[]): boolean {
  const required = ["clue_white_room", "clue_corridor", "clue_feast", "clue_mirror", "clue_clock"];
  return required.every((c) => items.includes(c));
}
