// Asset manifest. Backgrounds use the text-to-image API per project image
// guideline, layered over CSS gradient fallbacks for reliability. If a
// generated image is slow or unavailable, the gradient still sets the mood.

const IMG_API =
  'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image';

function bg(prompt: string): string {
  return `${IMG_API}?prompt=${encodeURIComponent(prompt)}&image_size=landscape_16_9`;
}

