// CSS gradient fallbacks shown behind/instead of generated images.
export const GRADIENTS: Record<string, string> = {
  white_room:
    'radial-gradient(ellipse at 50% 30%, #2a2a30 0%, #14141a 45%, #08080c 100%)',
  corridor:
    'linear-gradient(180deg, #050507 0%, #0c0c14 40%, #0a0a10 100%), radial-gradient(ellipse at 50% 60%, rgba(60,40,40,0.25), transparent 60%)',
  feast:
    'radial-gradient(ellipse at 50% 50%, #1a1010 0%, #0c0808 50%, #050404 100%)',
  mirror:
    'radial-gradient(ellipse at 30% 40%, #1a0a14 0%, #0a0608 55%, #050304 100%)',
  clock:
    'radial-gradient(circle at 50% 45%, #161018 0%, #0a060c 55%, #040406 100%)',
  choice:
    'radial-gradient(ellipse at 50% 55%, #141018 0%, #0a080c 55%, #040404 100%)',
  truth:
    'radial-gradient(ellipse at 50% 50%, #2a0606 0%, #140202 45%, #050000 100%)',
  title:
    'radial-gradient(ellipse at 50% 60%, #1a0606 0%, #0a0202 50%, #030000 100%)',
  ending:
    'radial-gradient(ellipse at 50% 50%, #1a1a22 0%, #0a0a0e 55%, #040406 100%)',
  void:
    'radial-gradient(circle at 50% 50%, #0a0204 0%, #050002 40%, #000000 100%)',
  loop_transition:
    'radial-gradient(ellipse at 50% 50%, #1a0408 0%, #0a0204 40%, #020002 70%, #000000 100%), conic-gradient(from 0deg at 50% 50%, rgba(139,0,0,0.1), transparent 25%, rgba(30,0,0,0.15) 50%, transparent 75%, rgba(139,0,0,0.1))',
  night:
    'radial-gradient(ellipse at 30% 70%, #1a0608 0%, #0a0204 45%, #020002 80%, #000000 100%)',
};

export function getBackground(key?: string): { img: string | null; gradient: string } {
  if (!key) return { img: null, gradient: GRADIENTS.truth };
  return {
    img: BACKGROUNDS[key] ?? null,
    gradient: GRADIENTS[key] ?? GRADIENTS.truth,
  };
}
