import type { GameLine } from '@/engine/types';

// Tiger Dojo — Fate/stay night-inspired bad-end teaching.
// After a Bad End, the Game Master returns as "the one who corrects the rule"
// and reviews which rule the player actually violated. Rule-horror makes this
// diegetic: the rule itself is the lesson. Each entry is keyed by endingId
// and is shown once per save (the game remembers you have already sat
// through this lesson).

export interface DojoLine {
  speaker?: string;
  text: string;
}

export interface DojoEntry {
  id: string;
  endingId: string;
  // The rule the player actually broke (or failed to read) to land here.
  violatedRule: string;
  // Soft direction toward a non-bad path. Phrased as a riddle, not a hint.
  hint: string;
  // The dialogue the Game Master delivers, line by line.
  lines: DojoLine[];
}

