// Ordered list of dojo ids — used to count progress toward the dojo-master
// easter egg (one per bad end, four total).
export const ALL_DOJO_IDS = Object.keys(BAD_END_DOJOS);

// Is the given endingId a Bad End that warrants a dojo lesson?
export function isBadEnd(endingId: string | null): boolean {
  return !!endingId && endingId in BAD_END_DOJOS;
}

// Convenience: render a dojo's lines as GameLine[] so DialogueBox / typewriter
// consumers can treat them uniformly.
export function dojoAsLines(entry: DojoEntry): GameLine[] {
  return entry.lines.map((l) => ({
    speaker: l.speaker,
    text: l.text,
    effect: l.speaker === 'system' ? 'glitch' : 'fade',
  }));
}
