import { useState } from 'react';
import { motion } from 'framer-motion';
import { useGame } from '@/engine/store';
import {
  ALL_NODES,
  EDGES,
  TIER_COLOR,
  type FlowNode,
} from '@/data/flowchart';

// Ending flow-chart view — an SVG rendering of how the 7-day story branches
// into its endings. Replaces the grid view on the Endings gallery when the
// player toggles "Flow". Locked endings show as "???" nodes with faint
// dashed connectors; unlocked endings show their title + a one-line trigger
// hint. Hovering a node surfaces its full condition.
//
// Inspired by Fate/stay night's route map and 428's timeline chart, but kept
// lightweight: pure SVG, no graph library, no animation physics.

interface Props {
  // Optional: callback when a player clicks an unlocked ending node. Used by
  // the gallery to surface the ending's epilogue in a side panel.
  onSelectEnding?: (endingId: string) => void;
}

export default function FlowChartView({ onSelectEnding }: Props) {
  const unlockedEndings = useGame((s) => s.unlockedEndings);
  const [hovered, setHovered] = useState<FlowNode | null>(null);

  const nodeById = new Map(ALL_NODES.map((n) => [n.id, n]));

  return (
    <div className="relative w-full max-w-4xl">
      {/* The flowchart itself — responsive via viewBox. */}
      <div className="relative aspect-[16/10] w-full overflow-hidden border border-ash/60 bg-void/40">
        <svg
          viewBox="0 0 100 100"
          preserveAspectRatio="xMidYMid meet"
          className="h-full w-full"
        >
          {/* Edges — spine + branches. Rendered first so nodes overlay them. */}
          {EDGES.map((edge, i) => {
            const from = nodeById.get(edge.from);
            const to = nodeById.get(edge.to);
            if (!from || !to) return null;
            // A hidden edge to a still-locked ending renders as a faint dashed
            // line — the player can see "something connects here" without the
            // spoiler of where it leads.
            const toUnlocked =
              !to.endingId || unlockedEndings.includes(to.endingId);
            const isHidden = edge.style === 'hidden' || !toUnlocked;
            const stroke = isHidden
              ? 'rgba(107,107,123,0.25)'
              : edge.style === 'main'
                ? 'rgba(139,0,0,0.5)'
                : 'rgba(200,30,30,0.4)';
            return (
              <line
                key={`edge-${i}`}
                x1={from.x}
                y1={from.y}
                x2={to.x}
                y2={to.y}
                stroke={stroke}
                strokeWidth={isHidden ? 0.25 : 0.4}
                strokeDasharray={isHidden ? '1.5 1.5' : undefined}
                vectorEffect="non-scaling-stroke"
              />
            );
          })}

          {/* The day-axis — a subtle horizontal rule anchoring the spine. */}
          <line
            x1={4}
            y1={50}
            x2={94}
            y2={50}
            stroke="rgba(107,107,123,0.18)"
            strokeWidth={0.2}
            strokeDasharray="0.5 1"
            vectorEffect="non-scaling-stroke"
          />

          {/* Nodes */}
          {ALL_NODES.map((node) => {
            const isDay = node.kind === 'day';
            const isEnding = node.kind === 'ending';
            const isUnlocked =
              !isEnding || !node.endingId || unlockedEndings.includes(node.endingId);
            const color = isEnding
              ? TIER_COLOR[node.tier ?? 'bad']
              : '#6b6b7b';
            const isHovered = hovered?.id === node.id;
            return (
              <g
                key={node.id}
                transform={`translate(${node.x}, ${node.y})`}
                onMouseEnter={() => setHovered(node)}
                onMouseLeave={() => setHovered(null)}
                onClick={() => {
                  if (isEnding && isUnlocked && node.endingId) {
                    onSelectEnding?.(node.endingId);
                  }
                }}
                style={{ cursor: isEnding && isUnlocked ? 'pointer' : 'default' }}
              >
                {/* Pulse ring on hover for unlocked endings — visual feedback
                    that this node is selectable. */}
                {isEnding && isUnlocked && isHovered && (
                  <circle
                    r={3.5}
                    fill="none"
                    stroke={color}
                    strokeWidth={0.3}
                    opacity={0.5}
                    vectorEffect="non-scaling-stroke"
                  />
                )}
                {/* Node shape: diamond for days, circle for endings. */}
                {isDay ? (
                  <rect
                    x={-1.6}
                    y={-1.6}
                    width={3.2}
                    height={3.2}
                    transform="rotate(45)"
                    fill="#0a0a0f"
                    stroke={color}
                    strokeWidth={0.35}
                    vectorEffect="non-scaling-stroke"
                  />
                ) : (
                  <circle
                    r={isUnlocked ? 2.4 : 1.8}
                    fill={isUnlocked ? '#0a0a0f' : '#1a1a24'}
                    stroke={isUnlocked ? color : 'rgba(107,107,123,0.4)'}
                    strokeWidth={isUnlocked ? 0.4 : 0.3}
                    vectorEffect="non-scaling-stroke"
                    style={
                      isUnlocked
                        ? { filter: `drop-shadow(0 0 2px ${color}80)` }
                        : {}
                    }
                  />
                )}
                {/* Label */}
                {isDay && (
                  <text
                    y={5.5}
                    textAnchor="middle"
                    fontSize={2.4}
                    fill="#6b6b7b"
                    fontFamily="'JetBrains Mono', monospace"
                  >
                    {node.label}
                  </text>
                )}
                {isEnding && (
                  <text
                    y={isUnlocked ? (node.y > 50 ? 6 : -4) : 4}
                    textAnchor="middle"
                    fontSize={isUnlocked ? 2.2 : 2}
                    fill={isUnlocked ? color : '#2a2a36'}
                    fontFamily="'Cormorant Garamond', serif"
                    fontStyle={isUnlocked ? 'normal' : 'italic'}
                  >
                    {isUnlocked ? node.label : '???'}
                  </text>
                )}
              </g>
            );
          })}
        </svg>

        {/* Hover tooltip — surfaces the trigger condition. Rendered as an
            HTML overlay so we get crisp text + easy positioning. */}
        {hovered && hovered.kind === 'ending' && (
          <div className="pointer-events-none absolute bottom-3 left-1/2 max-w-xs -translate-x-1/2 px-4 py-2 text-center">
            <p
              className="font-mono text-[9px] uppercase tracking-[0.3em]"
              style={{ color: TIER_COLOR[hovered.tier ?? 'bad'] }}
            >
              {unlockedEndings.includes(hovered.endingId ?? '')
                ? hovered.label
                : 'Locked'}
            </p>
            <p className="mt-1 font-serif text-xs italic text-muted">
              {unlockedEndings.includes(hovered.endingId ?? '')
                ? hovered.condition
                : 'Reach this ending to reveal its trigger.'}
            </p>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="mt-3 flex flex-wrap items-center justify-center gap-x-5 gap-y-1 font-mono text-[9px] uppercase tracking-[0.3em] text-muted">
        <LegendDot color={TIER_COLOR.good} label="Aspirational" />
        <LegendDot color={TIER_COLOR.true} label="True / Hidden" />
        <LegendDot color={TIER_COLOR.bad} label="Bleak" />
        <span className="text-muted/50">◇</span>
        <span className="text-muted/60">??? = not yet witnessed</span>
      </div>

      {/* Day axis hint */}
      <p className="mt-2 text-center font-mono text-[8px] uppercase tracking-[0.4em] text-muted/40">
        Day 1 → Day 7 ◊ the branch fans outward
      </p>
    </div>
  );
}

function LegendDot({ color, label }: { color: string; label: string }) {
  return (
    <span className="flex items-center gap-1.5">
      <motion.span
        animate={{ opacity: [0.6, 1, 0.6] }}
        transition={{ duration: 2.4, repeat: Infinity, ease: 'easeInOut' }}
        className="block h-1.5 w-1.5 rounded-full"
        style={{ background: color, boxShadow: `0 0 6px ${color}` }}
      />
      {label}
    </span>
  );
}
