import type {
  ScreenState,
  GameScene,
  GameAction,
  GameChoice,
  GameSettings,
  LogEntry,
  GameMode,
} from '@/engine/types';
import { SCENES, START_SCENE_ID, hasAllClues } from '@/data/chapters';
import {
  SALVATION_SCENES,
  SALVATION_START_SCENE_ID,
  SALVATION_POOL,
} from '@/data/salvationScenes';
import { loadSave, writeSave, type SavePayload } from '@/engine/saveManager';
