import type { CrossExamTestimony } from '@/engine/types';

// Mode-aware scene lookup. The classic 7-day story lives in SCENES; the
// Salvation Protocol alternate mode lives in SALVATION_SCENES. Both share
// the same engine — only the data set and the verify-board mechanic differ.
function getSceneForMode(sceneId: string, mode: GameMode): GameScene | null {
  if (mode === 'salvation') return SALVATION_SCENES[sceneId] ?? null;
  return SCENES[sceneId] ?? null;
}

const INITIAL_TRUST: Record<string, number> = {
  linye: 50,
  suwan: 50,
  chenmo: 40,
  xiaohe: 50,
  laozhou: 55,
  baijing: 45,
};

const DEFAULT_SETTINGS: GameSettings = {
  textSpeed: 28, // ms per char
  bgmVolume: 0.6,
  sfxVolume: 0.7,
};

interface GameState {
  screen: ScreenState;
  sceneId: string;
  scene: GameScene | null;
  lineIndex: number;
  showingChoices: boolean;
  showingRuleCard: boolean;
  flags: Record<string, number | string | boolean>;
  sanity: number;
  trust: Record<string, number>;
  inventory: string[];
  deductions: string[];
  ruleBreakCount: number;
  loopCount: number;
  retainedClues: string[];
  endingId: string | null;
  settings: GameSettings;
  // DDLC-inspired player name: the Game Master can address the player by
  // name at scripted beats, breaking the fourth wall. Set once on first
  // New Game (via an inline prompt on the title screen), persisted to
  // localStorage so it survives reloads and loops. Empty string means the
  // player declined to give one — the GM then uses "Stranger" / "you".
  // Surfaced in dialogue via a `{player}` placeholder substituted at
  // render time in DialogueBox (system speaker only).
  playerName: string;
  log: LogEntry[];
  hasExistingSave: boolean;
  saveLoadMode: 'save' | 'load';
  // Endings the player has reached at least once. Persisted in localStorage
  // so the gallery survives page reloads. Drives the endings-gallery screen
  // and the "Begin Loop N+1" prompt on the title screen.
  unlockedEndings: string[];

  // Tiger Dojo: bad-end corrections the player has sat through. Persisted in
  // localStorage so the dojo gallery survives reloads. Drives the small
  // "corrections witnessed" meter on the DojoOverlay and a 100%-collection
  // acknowledgement line. Each bad end has exactly one dojo entry.
  seenDojos: string[];

  // Phone Trigger (Steins;Gate-style): ids of phone events already fired in
  // the current loop. Reset on loopBack so calls re-arrive each playthrough.
  // This is session state, not persisted — the phone is a live device, not
  // a log. The *resolved* calls (answered / declined / missed) are persisted
  // separately via phoneLog so the Codex can review them later.
  triggeredPhoneEvents: string[];

  // Phone log — resolved calls and messages, persisted to localStorage so
  // the Codex's "Calls" tab can review them across sessions. Each entry is
  // a snapshot of the phone event at the moment the player resolved it
  // (answered, declined, or auto-missed by leaving the scene).
  phoneLog: PhoneLogEntry[];

  // Character profile destruction (DDLC-inspired): ids of character
  // profiles the player has "destroyed" from the Cast panel. Persisted to
  // localStorage as a separate profile store so the corruption survives
  // reloads. Destroying a profile triggers the FakeCrashOverlay and marks
  // the character's dialogue as corrupted (glitched) until restored.
  destroyedProfiles: string[];

  // DDLC-inspired "character remembers being destroyed": when a profile is
  // restored via the FakeCrashOverlay recovery, the character id is added
  // here. Persisted across loops / reloads. Characters in this list "know"
  // the player tried to erase them — surfaced in the Cast panel as a
  // disturbed note and exposed as a `remembers_<id>` flag so scene choices
  // can gate on it. One-way: once a character remembers, they do not forget.
  rememberedDestruction: string[];

  // Slay the Princess-inspired cumulative choice memory. Records every
  // choice the player has made, keyed by sceneId + loopCount. Persisted in
  // its own localStorage key (like unlockedEndings) so it survives reloads
  // and loops — it is the protagonist's accumulated memory of having chosen
  // before, not a per-save property. On a second playthrough (loopCount>=1),
  // entering a scene where a prior loop made a choice surfaces a déjà-vu
  // whisper ("you chose this before") without forcing the same branch.
  choiceLog: { sceneId: string; choiceText: string; loopCount: number }[];
  // The déjà-vu choice for the *current* scene, if any. Computed in
  // loadSceneState from choiceLog (filtered to prior loops). Null when the
  // player is on a first loop or has not chosen in this scene before.
  déjàVuChoice: { choiceText: string; loopCount: number } | null;

  // Slay the Princess-inspired hesitation memory: records choices the player
  // hovered over (weighed) but did NOT take. The game remembers the weight of
  // an unmade choice as clearly as a made one. Persisted in its own key so it
  // survives reloads and loops — it is the protagonist's accumulated memory of
  // having doubted, not a per-save property. On a second playthrough, the
  // ChoiceMenu surfaces a faint "...you weighed this before" whisper on
  // options the player hesitated over in a prior loop, without forcing the
  // same branch. Keyed by sceneId + choiceText so it tracks the option, not
  // the slot.
  hesitatedChoices: { sceneId: string; choiceText: string; loopCount: number }[];

  // Cross-examination state (逆转裁判). When the current scene has a
  // `crossExam` config and the intro lines are exhausted, advance() sets
  // crossExamActive so GameStage renders CrossExamMode instead of the
  // normal choice menu. Testimony index + presenting UI are managed locally
  // inside CrossExamMode; the store owns the active flag and the
  // resolve/give-up transitions (which go through loadSceneState).
  crossExamActive: boolean;

  // Verified rules: rule ids the player has resolved (tested by breaking or
  // by following and observing the outcome). A verified rule disappears from
  // the active rule card — the player has read it — but stays in the Codex
  // for reference and KEEPS taking effect mechanically. Unverified rules
  // remain on the card. Cleared on loopBack so each loop re-tests the player.
  verifiedRules: string[];

  // Flipped rules: rule ids whose truth value inverted on Day 3 (the game
  // "glitches"). Populated when the player enters a chapter >= 3 scene that
  // carries a `flipsOnDay3` config. Used by the Codex to display the new
  // truth value and by scene choices to gate on the flip. Not cleared on
  // loopBack — once a player has seen the flip, the Codex remembers it.
  flippedRules: string[];

  // Completed side quests: ids of optional character arcs the player has
  // finished (e.g. elena_sidequest when all three Elena calls resolve).
  // Persisted to localStorage so completion survives reloads and loops.
  // When a side quest completes, its full story is unlocked — surfaced via
  // the `unlockedSideStories` flag list so scenes can gate on it.
  completedSideQuests: string[];
  // Unlocked side stories: narrative scene ids unlocked by completing a
  // side quest. The player can reach them from the chapter-select / a
  // dedicated entry once the parent quest is done. Persisted alongside
  // completedSideQuests.
  unlockedSideStories: string[];

  // DDLC-inspired virtual file system: ids of files the player has deleted
  // from the FileBrowser. Persisted to localStorage so deletions survive
  // reloads and loops — the file system remembers what the player unmade.
  // Deleting certain files grants clues / sets flags / triggers the
  // FakeCrashOverlay (for .chr files); the deletion itself is recorded
  // here so the browser renders the file as [deleted] afterwards.
  deletedFiles: string[];

  // Game mode selector. 'classic' = the original 7-day rule-horror story.
  // 'salvation' = the Salvation Protocol alternate mode (same setting, new
  // contract: verifying rules frees or punishes souls). Drives the
  // mode-aware scene lookup (getSceneForMode) and the ending resolver.
  gameMode: GameMode;

  // Salvation Mode: souls saved by correct verification. Each successful
  // verification of a fake rule (definite save) or a real rule (50% save)
  // increments this and moves a name from the rescue pool into savedPeople.
  // Drives the HUD tally and the salvation ending resolver.
  savedCount: number;
  // Salvation Mode: souls punished by failed verification (wrong judgment).
  // Each wrong judgment increments this and moves a name from the rescue
  // pool into punishedPeople.
  punishedCount: number;
  // Salvation Mode: character ids that have been saved this run. Paired
  // with savedCount; the pool depletes as souls are resolved. Used by the
  // HUD to render the named souls freed.
  savedPeople: string[];
  // Salvation Mode: character ids that have been punished this run.
  punishedPeople: string[];
  // Salvation Mode: the remaining souls in peril — the pool each save /
  // punish draws from. Starts as SALVATION_POOL; depletes as souls are
  // resolved. When empty, further saves/punishes increment the count only.
  rescuePool: string[];

  // Salvation Mode verify board: when the current scene has a verifyBoard
  // config and the intro lines are exhausted, advance() sets
  // verifyBoardActive so GameStage renders the VerifyBoard instead of the
  // choice menu. The board owns the per-rule judging UI; the store owns the
  // active flag, the resolveVerify outcome, and the continue transition.
  verifyBoardActive: boolean;
  // The outcome of the most recent verify judgment, surfaced so the
  // VerifyBoard can render immediate feedback ("Saved: Bai Jing", "Punished:
  // Chen Mo", "The truth held — no soul was freed"). Cleared on scene load.
  lastVerifyResult: {
    ruleId: string;
    judgedAs: 'real' | 'fake';
    outcome: 'save_certain' | 'save_maybe' | 'save_failed' | 'punish';
    targetId?: string; // the character id saved/punished, if any
  } | null;

  // actions
  boot: () => void;
  startNewGame: () => void;
  // Salvation Mode: start a fresh run of the Salvation Protocol. Resets
  // the soul tally + rescue pool and loads the salvation intro scene.
  startSalvationMode: () => void;
  loadFromSlot: (slot: number) => void;
  saveToSlot: (slot: number) => void;
  setScreen: (s: ScreenState) => void;
  openSaveLoad: (mode: 'save' | 'load') => void;
  updateSettings: (partial: Partial<GameSettings>) => void;
  advance: () => void; // advance line or scene
  selectChoice: (choice: GameChoice) => void;
  acceptRuleCard: () => void;
  loopBack: () => void;
  goToTitle: () => void;
  startChapter: (sceneId: string) => void; // jump to a scene (chapter select)
  unlockEnding: (id: string) => void; // record an ending in the gallery
  recordDojo: (id: string) => void; // record a Tiger Dojo correction as seen
  // Phone Trigger: mark an event as fired this loop (prevents re-firing on
  // scene re-entry). Returns true if the event was newly triggered.
  triggerPhoneEvent: (id: string) => boolean;
  // Phone Trigger: record a resolved call/message in the phone log. Persisted
  // so the Codex's "Calls" tab can review it later. Also grants the clue if
  // the event carries grantsClue and the player answered / read it.
  recordPhoneLog: (entry: PhoneLogEntry) => void;
  // Phone Trigger: grant a clue to the player outside the scene action
  // pipeline. Used by PhoneDevice when an answered call carries grantsClue.
  // Adds to inventory + retainedClues so the clue survives the loop.
  addClue: (clue: string) => void;
  // Apply a set of GameActions outside the scene-choice pipeline. Used by
  // the Steins;Gate phone reply system AND the DDLC file browser when a
  // player action (picking a reply, deleting a file) carries trust/sanity/
  // flag changes. Runs through the same applyActions pipeline as scene
  // choices so the effects behave identically, then re-syncs derived flags
  // (is_looping, trust_*_high) so the active scene's choice gating reads
  // the post-action state without a scene transition.
  applyGameActions: (actions: GameAction[]) => void;
  // DDLC file system: record a file as deleted. Persisted to localStorage
  // so the deletion survives reloads and loops. The FileBrowser calls this
  // when the player deletes a file; the consequences (clue / flag / crash)
  // are handled by the component, which has access to the file's onDelete
  // config. This method only records the deletion itself.
  deleteFile: (fileId: string) => void;
  // Character profile destruction: mark a character's profile file as
  // destroyed. Persisted to localStorage. The destruction is permanent
  // within a save — restoring is only possible via the FakeCrashOverlay's
  // recovery sequence, which the Game Master frames as "repairing the file."
  destroyProfile: (id: string) => void;
  restoreProfile: (id: string) => void;
  setFlag: (key: string, value: number | string | boolean) => void;
  // DDLC player name: set once on first New Game. Persisted to localStorage
  // so the Game Master can address the player by name across reloads and
  // loops. Empty string is a valid "declined" value.
  setPlayerName: (name: string) => void;
  // Slay the Princess hesitation: record that the player weighed a choice
  // without taking it. Called by ChoiceMenu after a hover dwells past the
  // hesitation threshold. Persisted so the doubt survives reloads and loops.
  // Deduped per (sceneId, choiceText, loopCount) so re-hovering does not
  // bloat the log.
  recordHesitation: (sceneId: string, choiceText: string) => void;
  // Cross-exam: apply a correct objection — runs the testimony's present
  // actions and advances to present.next. Mirrors selectChoice's flow.
  crossExamResolve: (testimony: CrossExamTestimony) => void;
  // Cross-exam: apply a wrong objection — costs sanity (witness patience)
  // and stays in the cross-exam.
  crossExamWrongPresent: (cost: number) => void;
  // Cross-exam: give up without finding the contradiction. Advances to
  // the scene's configured giveUpNext (if any), else does nothing.
  crossExamGiveUp: () => void;
  // Salvation Mode: judge a rule as "real" or "fake". Looks up the rule's
  // actual truth value and applies the contract:
  //   - Fake judged "fake" (correct) → one soul DEFINITELY saved.
  //   - Real judged "real" (correct) → one soul MIGHT be saved (50%).
  //   - Wrong judgment (either direction) → verification FAILED → one soul
  //     DEFINITELY punished.
  // Marks the rule as verified and surfaces the outcome via lastVerifyResult
  // so the VerifyBoard can render immediate feedback. No-op if the rule was
  // already judged.
  resolveVerify: (ruleId: string, judgedAs: 'real' | 'fake') => void;
  // Salvation Mode: advance past the verify board once every rule on the
  // card has been judged. Loads the scene's verifyBoard.next. Mirrors the
  // crossExamResolve hand-off.
  verifyBoardContinue: () => void;
  // Mark a rule as verified (resolved by the player). Removes it from the
  // active rule card; the rule keeps taking effect. Called by selectChoice
  // when a choice carries `verifiesRule`. No-op if already verified.
  verifyRule: (ruleId: string) => void;
  // Complete a side quest and unlock its associated side story scene.
  // Persists to localStorage. Called when the quest's completion condition
  // is met (e.g. all Elena calls resolved). Idempotent.
  completeSideQuest: (questId: string, storySceneId: string) => void;
}

function applyActions(
  state: GameState,
  actions: GameAction[] | undefined,
): Partial<GameState> {
  // 防御性默认值：当 state 因 save 损坏 / 热更新丢字段而出现 undefined 时，
  // 仍然返回一个结构完整的快照，避免下游 loadSceneState 读取 .linye 等属性时
  // 抛出 "Cannot read properties of undefined"。
  const flags = { ...(state.flags ?? {}) };
  let sanity = typeof state.sanity === 'number' ? state.sanity : 100;
  const trust = { ...(state.trust ?? INITIAL_TRUST) };
  const inventory = [...(state.inventory ?? [])];
  const deductions = [...(state.deductions ?? [])];
  let ruleBreakCount = state.ruleBreakCount ?? 0;
  let loopCount = state.loopCount ?? 0;
  const retainedClues = [...(state.retainedClues ?? [])];

  if (!actions || actions.length === 0) {
    // Return a full snapshot derived from state (not an empty object) so
    // callers that read .trust / .inventory / .flags off the result never
    // hit "Cannot read properties of undefined". The values are unchanged
    // copies — merging them back is a no-op.
    return { flags, sanity, trust, inventory, deductions, ruleBreakCount, loopCount, retainedClues };
  }

  for (const a of actions) {
    switch (a.type) {
      case 'setFlag':
        if (a.key) flags[a.key] = a.value as never;
        break;
      case 'adjustSanity':
        sanity = Math.max(0, Math.min(100, sanity + (a.value as number)));
        break;
      case 'adjustTrust':
        if (a.key) {
          const cur = trust[a.key] ?? 0;
          trust[a.key] = Math.max(0, Math.min(100, cur + (a.value as number)));
        }
        break;
      case 'addItem': {
        const v = a.value as string;
        if (!inventory.includes(v)) inventory.push(v);
        if (!retainedClues.includes(v)) retainedClues.push(v);
        break;
      }
      case 'addDeduction': {
        const v = a.value as string;
        if (!deductions.includes(v)) deductions.push(v);
        break;
      }
      case 'incrementLoop':
        loopCount += 1;
        break;
      case 'adjustRuleBreak':
        ruleBreakCount += (a.value as number) || 1;
        break;
    }
  }
  return { flags, sanity, trust, inventory, deductions, ruleBreakCount, loopCount, retainedClues };
}

// Map a rule-card scene id (e.g. "d1_rules") to the rule id its break-choice
// tests. Each day's break-choice targets the day's lie rule, so we look up
// the scene's ruleCard and return the first rule marked isLie. Used as a
// fallback when a break-choice does not carry an explicit `verifiesRule`.
function inferRuleId(sceneId: string, mode: GameMode): string | undefined {
  const scene = getSceneForMode(sceneId, mode);
  if (!scene?.ruleCard) return undefined;
  const lie = scene.ruleCard.find((r) => r.isLie);
  return lie?.id;
}

// Salvation Mode ending resolver. The mode has no sanity/trust/loop logic —
// the ending is determined solely by the saved/punished tally across the
// three rounds. The Game Master counts souls, not sanity.
//   - saved >= 5              → THE SALVATION (good)
//   - punished > saved        → THE CONDEMNATION (bad)
//   - saved >= 3              → THE PARTIAL RECKONING (neutral)
//   - otherwise (tally even)  → THE WEIGHT (mixed)
function resolveSalvationEnding(state: GameState): string {
  const saved = state.savedCount ?? 0;
  const punished = state.punishedCount ?? 0;
  if (saved >= 5) return 'salvation_good';
  if (punished > saved) return 'salvation_bad';
  if (saved >= 3) return 'salvation_neutral';
  return 'salvation_mixed';
}

function resolveEnding(state: GameState): string {
  // Salvation Mode has its own resolver — the classic sanity/trust/loop
  // flags do not apply. The tally of saved vs punished souls is the only
  // signal the Game Master reads.
  if (state.gameMode === 'salvation') {
    return resolveSalvationEnding(state);
  }
  if (state.sanity <= 0) return 'collapse';
  if (state.flags.sacrificed_self === true) return 'sacrifice';
  const allClues = hasAllClues(state.inventory);
  if (allClues && state.flags.identified_lie === true && state.loopCount >= 1) {
    return 'game_master';
  }
  if (state.flags.identified_lie === true) return 'truth_seeker';
  // Rebel: the player broke five or more rules across the week without
  // ever identifying the meta-lie. They escaped by refusal, not by reading.
  // Checked before isolation so a rebellious loner gets the rebel ending
  // rather than the isolation one — refusal is a more specific statement.
  // Note: at this point TS has narrowed identified_lie to non-true (the
  // truth_seeker return above guards the === true case), so we simply
  // check the rule-break threshold.
  if (state.ruleBreakCount >= 5) {
    return 'rebel';
  }
  // Isolation: survived and sane, but alienated every NPC. The game never
  // required trust to survive — only to matter. Checked after the truth-based
  // endings so a well-informed loner still gets the revelatory ending.
  const trustNpcs = ['linye', 'suwan', 'chenmo', 'xiaohe', 'laozhou', 'baijing'];
  const avgTrust =
    trustNpcs.reduce((sum, id) => sum + (state.trust?.[id] ?? 0), 0) / trustNpcs.length;
  if (avgTrust <= 20) return 'isolation';
  return 'perfect_survivor';
}

function loadSceneState(state: GameState, sceneId: string): Partial<GameState> {
  const mode: GameMode = state.gameMode ?? 'classic';
  const scene = getSceneForMode(sceneId, mode);
  if (!scene) return { sceneId, scene };
  const enterActions = applyActions(state, scene.onEnter);
  const log = [...state.log];
  // Play BGM if specified
  if (scene.bgm) {
    audio.playBGM(scene.bgm, state.settings.bgmVolume);
  }
  // Rule card reveal: a low rumble lands like a gavel as the rules appear.
  if (scene.ruleCard && scene.ruleCard.length > 0) {
    audio.playSFX('rumble');
  }

  // Sync derived state into flags so GameChoice.requires (which only reads
  // flags) can gate options on trust level, loop count, or clue ownership.
  // This keeps the scene data declarative — the store computes the derived
  // flags on every scene transition, and the scene's choices just read them.
  // applyActions always returns a full snapshot (trust/inventory/flags/etc),
  // 但我们仍保留多重重保护，防止 save 损坏 / 热更新导致 undefined 访问。
  const enterTrust = enterActions.trust ?? state.trust ?? INITIAL_TRUST;
  const enterInventory = enterActions.inventory ?? state.inventory ?? [];
  const flags = { ...(enterActions.flags ?? state.flags) };
  flags.is_looping = state.loopCount >= 1;
  const npcs = ['linye', 'suwan', 'chenmo', 'xiaohe', 'laozhou', 'baijing'];
  for (const id of npcs) {
    // 双重保护：enterTrust?.[id] 防止 enterTrust 自身为 undefined，
    // ?? 0 保证 NaN 比较时返回 false 而不是抛错。
    const v = Number(enterTrust?.[id] ?? 0);
    flags[`trust_${id}_high`] = (Number.isFinite(v) ? v : 0) >= 75;
  }
  flags.any_trust_high = npcs.some((id) => (Number(enterTrust?.[id] ?? 0) || 0) >= 75);
  flags.has_loop_clue = enterInventory.includes('clue_suspect_loop');
  // DDLC-inspired: expose a per-character `remembers_<id>` flag whenever the
  // player has destroyed+restored that profile before. Scene choices can gate
  // on it (e.g. a hidden "you tried to erase me" dialogue branch).
  for (const id of state.rememberedDestruction) {
    flags[`remembers_${id}`] = true;
  }

  // Slay the Princess déjà-vu: on a second playthrough, look up whether the
  // player chose in this scene during a PRIOR loop. If so, surface the prior
  // choice text so the GameStage can whisper it back to the player. We pick
  // the most recent prior-loop entry (closest loopCount below current) so the
  // whisper reflects the immediately preceding playthrough, not the first.
  let déjàVuChoice: GameState['déjàVuChoice'] = null;
  if (state.loopCount >= 1) {
    const priorChoices = state.choiceLog.filter(
      (c) => c.sceneId === sceneId && c.loopCount < state.loopCount,
    );
    if (priorChoices.length > 0) {
      const latest = priorChoices.reduce((a, b) => (a.loopCount > b.loopCount ? a : b));
      déjàVuChoice = { choiceText: latest.choiceText, loopCount: latest.loopCount };
    }
  }

  // Day-3 rule inversion: once the player reaches chapter 3, any Day-1 rule
  // carrying a `flipsOnDay3` config is marked flipped. We collect the ids
  // here so the Codex can display the new truth value and scenes can gate on
  // `flippedRules` / the `rule_<id>_flipped` flag. Persisted once seen.
  // Classic-mode only — Salvation Mode has its own rule set and no flips.
  const flippedRules = [...state.flippedRules];
  if (mode === 'classic' && scene.chapter >= 3) {
    const day1Scene = SCENES['d1_rules'];
    if (day1Scene?.ruleCard) {
      for (const rule of day1Scene.ruleCard) {
        if (rule.flipsOnDay3 && !flippedRules.includes(rule.id)) {
          flippedRules.push(rule.id);
        }
      }
    }
    if (flippedRules.length !== state.flippedRules.length) {
      try {
        localStorage.setItem('btr_flipped_rules', JSON.stringify(flippedRules));
      } catch {
        /* ignore quota errors */
      }
    }
  }
  // Expose per-rule flip flags so choices can gate on the inversion.
  for (const id of flippedRules) {
    flags[`rule_${id}_flipped`] = true;
  }

  // Side-quest completion check (Elena Krause thread). When the player has
  // resolved all three Elena phone events (logged in phoneLog), the quest is
  // complete and her full side story scene is unlocked. We re-check on every
  // scene load so completion is detected the moment the third call resolves.
  const completedSideQuests = [...state.completedSideQuests];
  const unlockedSideStories = [...state.unlockedSideStories];
  const elenaCallIds = [
    'phone_d3_elena_ping',
    'phone_d7_elena_reveal',
    'phone_d7_elena_identity',
  ];
  const elenaResolved = elenaCallIds.every((id) =>
    state.phoneLog.some((e) => e.id === id),
  );
  if (elenaResolved && !completedSideQuests.includes('elena_sidequest')) {
    completedSideQuests.push('elena_sidequest');
    if (!unlockedSideStories.includes('elena_full_story')) {
      unlockedSideStories.push('elena_full_story');
    }
    try {
      localStorage.setItem(
        'btr_side_quests',
        JSON.stringify({ completed: completedSideQuests, unlocked: unlockedSideStories }),
      );
    } catch {
      /* ignore quota errors */
    }
  }
  // Expose side-quest flags so scenes can gate on them.
  for (const q of completedSideQuests) {
    flags[`quest_${q}_done`] = true;
  }
  for (const s of unlockedSideStories) {
    flags[`story_${s}_unlocked`] = true;
  }

  return {
    sceneId,
    scene,
    lineIndex: 0,
    showingChoices: false,
    showingRuleCard: !!scene.ruleCard && scene.ruleCard.length > 0,
    // Cross-exam always starts inactive on scene load. If the scene has a
    // crossExam config, advance() flips this on once the intro lines are done.
    crossExamActive: false,
    // Verify board (Salvation Mode) always starts inactive on scene load.
    // If the scene has a verifyBoard config, advance() flips this on once
    // the intro lines are done — same hand-off pattern as cross-exam.
    verifyBoardActive: false,
    // Clear the last verify result so feedback from a prior round does not
    // bleed into a fresh board.
    lastVerifyResult: null,
    déjàVuChoice,
    flippedRules,
    completedSideQuests,
    unlockedSideStories,
    log,
    ...enterActions,
    flags,
  };
}

export const useGame = create<GameState>((set, get) => ({
  screen: 'title',
  sceneId: START_SCENE_ID,
  scene: null,
  lineIndex: 0,
  showingChoices: false,
  showingRuleCard: false,
  flags: {},
  sanity: 100,
  trust: { ...INITIAL_TRUST },
  inventory: [],
  deductions: [],
  ruleBreakCount: 0,
  loopCount: 0,
  retainedClues: [],
  endingId: null,
  settings: { ...DEFAULT_SETTINGS },
  playerName: '',
  log: [],
  hasExistingSave: false,
  saveLoadMode: 'load',
  unlockedEndings: [],
  seenDojos: [],
  triggeredPhoneEvents: [],
  phoneLog: [],
  destroyedProfiles: [],
  rememberedDestruction: [],
  choiceLog: [],
  déjàVuChoice: null,
  hesitatedChoices: [],
  crossExamActive: false,
  verifiedRules: [],
  flippedRules: [],
  completedSideQuests: [],
  unlockedSideStories: [],
  deletedFiles: [],
  // Salvation Mode state — inactive until the player starts the Salvation
  // Protocol from the title screen. The tally + pool reset on each new run.
  gameMode: 'classic',
  savedCount: 0,
  punishedCount: 0,
  savedPeople: [],
  punishedPeople: [],
  rescuePool: [],
  verifyBoardActive: false,
  lastVerifyResult: null,

  boot: () => {
    const savedSettings = localStorage.getItem('btr_settings');
    let settings = { ...DEFAULT_SETTINGS };
    if (savedSettings) {
      try {
        settings = { ...settings, ...JSON.parse(savedSettings) };
      } catch {
        /* ignore */
      }
    }
    audio.setVolumes(settings.bgmVolume, settings.sfxVolume);
    const autosave = localStorage.getItem('btr_autosave');
    // Load the endings gallery from localStorage so unlocked endings persist
    // across sessions. If the key is missing or invalid, start empty.
    let unlockedEndings: string[] = [];
    const savedEndings = localStorage.getItem('btr_endings');
    if (savedEndings) {
      try {
        const parsed = JSON.parse(savedEndings);
        if (Array.isArray(parsed)) unlockedEndings = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load the Tiger Dojo collection — bad-end corrections the player has
    // already sat through. Persisted so the dojo meter survives reloads and
    // the player is not forced to re-watch a lesson on every session.
    let seenDojos: string[] = [];
    const savedDojos = localStorage.getItem('btr_dojos');
    if (savedDojos) {
      try {
        const parsed = JSON.parse(savedDojos);
        if (Array.isArray(parsed)) seenDojos = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load the phone log — resolved calls/messages from prior sessions.
    // Persisted so the Codex's "Calls" tab can review missed calls and
    // answered messages across reloads, like a real phone's call history.
    let phoneLog: PhoneLogEntry[] = [];
    const savedPhoneLog = localStorage.getItem('btr_phone_log');
    if (savedPhoneLog) {
      try {
        const parsed = JSON.parse(savedPhoneLog);
        if (Array.isArray(parsed)) phoneLog = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load destroyed character profiles — the DDLC-inspired "file deletion"
    // state. Persisted so the corruption survives reloads and the game
    // remembers which characters the player tried to erase.
    let destroyedProfiles: string[] = [];
    const savedDestroyed = localStorage.getItem('btr_destroyed_profiles');
    if (savedDestroyed) {
      try {
        const parsed = JSON.parse(savedDestroyed);
        if (Array.isArray(parsed)) destroyedProfiles = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load remembered-destruction state — characters who "know" the player
    // tried to erase them (post-restore). Persisted across loops/reloads.
    let rememberedDestruction: string[] = [];
    const savedRemembered = localStorage.getItem('btr_remembered_destruction');
    if (savedRemembered) {
      try {
        const parsed = JSON.parse(savedRemembered);
        if (Array.isArray(parsed)) rememberedDestruction = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load the cumulative choice log (Slay the Princess déjà-vu). Persisted
    // in its own key so it survives reloads and loops regardless of save
    // slot — it is the protagonist's accumulated memory of prior choices.
    let choiceLog: GameState['choiceLog'] = [];
    const savedChoiceLog = localStorage.getItem('btr_choice_log');
    if (savedChoiceLog) {
      try {
        const parsed = JSON.parse(savedChoiceLog);
        if (Array.isArray(parsed)) choiceLog = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load flipped-rules state (Day-3 inversion). Persisted so the Codex
    // remembers the flip across reloads once the player has reached Day 3.
    let flippedRules: string[] = [];
    const savedFlipped = localStorage.getItem('btr_flipped_rules');
    if (savedFlipped) {
      try {
        const parsed = JSON.parse(savedFlipped);
        if (Array.isArray(parsed)) flippedRules = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load completed side quests + unlocked side stories. Persisted so
    // completed optional arcs survive reloads and loops — once Elena's
    // thread is done, her full story stays reachable.
    let completedSideQuests: string[] = [];
    let unlockedSideStories: string[] = [];
    const savedQuests = localStorage.getItem('btr_side_quests');
    if (savedQuests) {
      try {
        const parsed = JSON.parse(savedQuests);
        if (parsed && Array.isArray(parsed.completed)) completedSideQuests = parsed.completed;
        if (parsed && Array.isArray(parsed.unlocked)) unlockedSideStories = parsed.unlocked;
      } catch {
        /* ignore */
      }
    }
    // Load deleted file system files (DDLC file browser). Persisted so the
    // file system remembers what the player unmade across reloads and loops.
    let deletedFiles: string[] = [];
    const savedDeletedFiles = localStorage.getItem('btr_deleted_files');
    if (savedDeletedFiles) {
      try {
        const parsed = JSON.parse(savedDeletedFiles);
        if (Array.isArray(parsed)) deletedFiles = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load the player name (DDLC meta). Persisted so the Game Master can
    // address the player by name across reloads and loops. Empty string is
    // a valid "declined" value — we do not re-prompt once set.
    let playerName = '';
    const savedName = localStorage.getItem('btr_player_name');
    if (savedName) {
      try {
        const parsed = JSON.parse(savedName);
        if (typeof parsed === 'string') playerName = parsed;
      } catch {
        /* ignore */
      }
    }
    // Load the hesitation log (Slay the Princess doubt memory). Persisted in
    // its own key so it survives reloads and loops — it is the protagonist's
    // accumulated memory of having doubted, not a per-save property.
    let hesitatedChoices: GameState['hesitatedChoices'] = [];
    const savedHesitations = localStorage.getItem('btr_hesitations');
    if (savedHesitations) {
      try {
        const parsed = JSON.parse(savedHesitations);
        if (Array.isArray(parsed)) hesitatedChoices = parsed;
      } catch {
        /* ignore */
      }
    }
    set({
      settings,
      hasExistingSave: !!autosave,
      unlockedEndings,
      seenDojos,
      phoneLog,
      destroyedProfiles,
      rememberedDestruction,
      choiceLog,
      flippedRules,
      completedSideQuests,
      unlockedSideStories,
      deletedFiles,
      playerName,
      hesitatedChoices,
      déjàVuChoice: null,
      crossExamActive: false,
    });
  },

  startNewGame: () => {
    const fresh: GameState = {
      ...get(),
      screen: 'dialogue',
      sceneId: START_SCENE_ID,
      scene: null,
      lineIndex: 0,
      showingChoices: false,
      showingRuleCard: false,
      flags: {},
      sanity: 100,
      trust: { ...INITIAL_TRUST },
      inventory: [...get().retainedClues], // keep clues from prior loops
      deductions: [],
      ruleBreakCount: 0,
      loopCount: get().loopCount,
      retainedClues: get().retainedClues,
      endingId: null,
      log: [],
      // Transient state resets. choiceLog is intentionally preserved — it is
      // the protagonist's accumulated memory of prior loops, not a per-save
      // property. déjàVuChoice is recomputed by loadSceneState below.
      déjàVuChoice: null,
      crossExamActive: false,
      // Verified rules reset each loop — the player must re-test the rules
      // every playthrough. flippedRules persists (see boot comment).
      verifiedRules: [],
      // Classic mode: clear the Salvation Protocol tally + pool so a prior
      // alternate-mode run does not leak into the classic story. The HUD
      // only renders the salvation tally when gameMode === 'salvation'.
      gameMode: 'classic',
      savedCount: 0,
      punishedCount: 0,
      savedPeople: [],
      punishedPeople: [],
      rescuePool: [],
      verifyBoardActive: false,
      lastVerifyResult: null,
    };
    const loaded = loadSceneState(fresh, START_SCENE_ID);
    set({ ...fresh, ...loaded } as GameState);
  },

  startSalvationMode: () => {
    // Reset the soul tally + rescue pool for a fresh Salvation Protocol run.
    // The classic story's flags / sanity / trust are irrelevant here — the
    // mode has no sanity meter and no trust network. Only the tally matters.
    const fresh: GameState = {
      ...get(),
      screen: 'dialogue',
      sceneId: SALVATION_START_SCENE_ID,
      scene: null,
      lineIndex: 0,
      showingChoices: false,
      showingRuleCard: false,
      flags: {},
      sanity: 100,
      trust: { ...INITIAL_TRUST },
      inventory: [],
      deductions: [],
      ruleBreakCount: 0,
      loopCount: 0,
      retainedClues: [],
      endingId: null,
      log: [],
      déjàVuChoice: null,
      crossExamActive: false,
      verifiedRules: [],
      // Salvation Mode: activate the mode and seed the rescue pool with the
      // seven souls in peril. The tally starts at zero — every save / punish
      // is earned by judging a rule on the verify board.
      gameMode: 'salvation',
      savedCount: 0,
      punishedCount: 0,
      savedPeople: [],
      punishedPeople: [],
      rescuePool: [...SALVATION_POOL],
      verifyBoardActive: false,
      lastVerifyResult: null,
    };
    const loaded = loadSceneState(fresh, SALVATION_START_SCENE_ID);
    set({ ...fresh, ...loaded } as GameState);
  },

  loadFromSlot: (slot: number) => {
    const data = loadSave(slot);
    if (!data) return;
    const restored: GameState = {
      ...get(),
      screen: 'dialogue',
      sceneId: data.sceneId,
      // Defend against corrupted / partial saves: missing fields fall back to
      // safe defaults so loadSceneState never receives undefined trust / flags.
      flags: data.flags ?? {},
      sanity: data.sanity ?? 100,
      trust: data.trust ?? { ...INITIAL_TRUST },
      inventory: data.inventory ?? [],
      deductions: data.deductions ?? [],
      ruleBreakCount: data.ruleBreakCount ?? 0,
      loopCount: data.loopCount ?? 0,
      retainedClues: data.retainedClues ?? [],
      endingId: null,
      log: [],
      // Restore verified rules from the save so the active rule card stays
      // accurate across load. flippedRules / sideQuests are global state
      // loaded once at boot — not part of per-slot saves.
      verifiedRules: data.verifiedRules ?? [],
      // Restore the game mode + Salvation Protocol tally / pool so a save
      // made mid-mode loads back into the correct scene map. Defaults to
      // classic for saves made before the mode existed.
      gameMode: data.gameMode ?? 'classic',
      savedCount: data.savedCount ?? 0,
      punishedCount: data.punishedCount ?? 0,
      savedPeople: data.savedPeople ?? [],
      punishedPeople: data.punishedPeople ?? [],
      rescuePool: data.rescuePool ?? (data.gameMode === 'salvation' ? [...SALVATION_POOL] : []),
      verifyBoardActive: false,
      lastVerifyResult: null,
      // Transient state — recompute via loadSceneState below.
      déjàVuChoice: null,
      crossExamActive: false,
    };
    const loaded = loadSceneState(restored, data.sceneId);
    set({ ...restored, ...loaded } as GameState);
  },

  saveToSlot: (slot: number) => {
    const s = get();
    const payload: SavePayload = {
      sceneId: s.sceneId,
      flags: s.flags,
      sanity: s.sanity,
      trust: s.trust,
      inventory: s.inventory,
      deductions: s.deductions,
      ruleBreakCount: s.ruleBreakCount,
      loopCount: s.loopCount,
      retainedClues: s.retainedClues,
      verifiedRules: s.verifiedRules,
      // Persist the game mode + Salvation tally / pool so a save made mid-mode
      // loads back into the correct scene map with the correct soul count.
      gameMode: s.gameMode,
      savedCount: s.savedCount,
      punishedCount: s.punishedCount,
      savedPeople: s.savedPeople,
      punishedPeople: s.punishedPeople,
      rescuePool: s.rescuePool,
    };
    writeSave(slot, payload);
    set({ hasExistingSave: true });
  },

  setScreen: (s) => set({ screen: s }),

  openSaveLoad: (mode) => set({ screen: 'save_load', saveLoadMode: mode }),

  updateSettings: (partial) => {
    const settings = { ...get().settings, ...partial };
    localStorage.setItem('btr_settings', JSON.stringify(settings));
    audio.setVolumes(settings.bgmVolume, settings.sfxVolume);
    set({ settings });
  },

  advance: () => {
    const s = get();
    if (s.screen !== 'dialogue' || !s.scene) return;

    // If rule card is showing, advance does nothing (use acceptRuleCard)
    if (s.showingRuleCard) return;

    // If choices are showing, advance does nothing (use selectChoice)
    if (s.showingChoices) return;

    // If cross-exam is active, advance does nothing — the CrossExamMode
    // component owns input and resolves via crossExamResolve/giveUp.
    if (s.crossExamActive) return;

    // If the Salvation Mode verify board is active, advance does nothing —
    // the VerifyBoard component owns input and resolves via
    // resolveVerify / verifyBoardContinue.
    if (s.verifyBoardActive) return;

    // Append current line to log if it has a speaker or meaningful text
    const currentLine = s.scene.lines[s.lineIndex];
    if (currentLine && (currentLine.text || currentLine.speaker)) {
      const entry: LogEntry = {
        speaker: currentLine.speaker ?? '',
        text: currentLine.text,
        ts: Date.now(),
      };
      // Keep log bounded
      const log = [...s.log, entry].slice(-200);
      set({ log });
    }

    // Advance line
    if (s.lineIndex < s.scene.lines.length - 1) {
      set({ lineIndex: s.lineIndex + 1 });
      audio.playSFX('click');
      return;
    }

    // End of lines reached — show choices, activate cross-exam, or go next.
    // Cross-exam (逆转裁判): if the scene has a crossExam config, the intro
    // lines have just finished — hand control to the CrossExamMode component
    // instead of showing the choice menu. The player examines the witness's
    // testimony and presents evidence to find the contradiction.
    if (s.scene.crossExam && !s.crossExamActive) {
      audio.playSFX('rumble');
      set({ crossExamActive: true });
      return;
    }
    // Salvation Mode verify board (救赎模式): if the scene has a verifyBoard
    // config, the intro lines have just finished — hand control to the
    // VerifyBoard component instead of showing the choice menu. The player
    // judges each rule on the card as "Real" or "Fake" and the store weighs
    // each verdict against the contract (fake→definite save, real→maybe
    // save, wrong→punish).
    if (s.scene.verifyBoard && !s.verifyBoardActive) {
      audio.playSFX('rumble');
      set({ verifyBoardActive: true });
      return;
    }
    if (s.scene.choices && s.scene.choices.length > 0) {
      set({ showingChoices: true });
      return;
    }
    if (s.scene.isEnding) {
      const endingId = resolveEnding(s);
      // Dramatic audio: cut the bed, then play a stinger based on the outcome.
      audio.cutAll();
      if (endingId === 'collapse') {
        audio.playSFX('death');
      } else if (endingId === 'truth_seeker' || endingId === 'game_master') {
        audio.playSFX('reveal');
      } else {
        audio.playSFX('stinger');
      }
      // Record the ending in the gallery. Persisted to localStorage so the
      // player can see which endings they have reached across sessions.
      const unlocked = [...new Set([...s.unlockedEndings, endingId])];
      try {
        localStorage.setItem('btr_endings', JSON.stringify(unlocked));
      } catch {
        /* ignore quota errors */
      }
      set({ screen: 'ending', endingId, unlockedEndings: unlocked });
      return;
    }
    if (s.scene.next) {
      const next = loadSceneState(get(), s.scene.next);
      set({ ...next } as Partial<GameState>);
      // Scene transition: a soft whoosh sells the wipe.
      audio.playSFX('whoosh');
    }
  },

  selectChoice: (choice) => {
    const s = get();
    const actionState = applyActions(s, choice.actions);
    // If breaking a rule, play a stinger; if a clue is unlocked, play a
    // dedicated chime so discoveries feel distinct from generic advances.
    const unlocksClue = choice.actions?.some((a) => a.type === 'addItem' || a.type === 'addDeduction');
    if (choice.breakRule) {
      audio.playSFX('stinger');
    } else if (unlocksClue) {
      audio.playSFX('chime');
    } else {
      audio.playSFX('click');
    }
    // Slay the Princess déjà-vu: record this choice in the cumulative log so
    // a subsequent loop can whisper it back. Persisted in its own key so it
    // survives reloads and loops. Deduped per (sceneId, loopCount, text) so
    // re-entering a scene and re-choosing the same option does not bloat it.
    const choiceLog = [...s.choiceLog];
    const entry = { sceneId: s.sceneId, choiceText: choice.text, loopCount: s.loopCount };
    const exists = choiceLog.some(
      (c) => c.sceneId === entry.sceneId && c.choiceText === entry.choiceText && c.loopCount === entry.loopCount,
    );
    if (!exists) {
      choiceLog.push(entry);
      try {
        localStorage.setItem('btr_choice_log', JSON.stringify(choiceLog));
      } catch {
        /* ignore quota errors */
      }
    }
    const next = loadSceneState({ ...s, ...actionState, choiceLog } as GameState, choice.next);
    // Rule verification: if the choice carries `verifiesRule`, mark that
    // rule as verified so it disappears from the active rule card. The rule
    // keeps taking effect mechanically — only its visibility changes. We
    // also auto-verify when a choice breaks a rule (the player has tested
    // it by breaking), unless the choice explicitly names a different rule.
    const verifiedRules = [...s.verifiedRules];
    const ruleToVerify = choice.verifiesRule ?? (choice.breakRule ? inferRuleId(s.sceneId, s.gameMode) : undefined);
    if (ruleToVerify && !verifiedRules.includes(ruleToVerify)) {
      verifiedRules.push(ruleToVerify);
    }
    set({ showingChoices: false, ...actionState, ...next, choiceLog, verifiedRules } as Partial<GameState>);
  },

  acceptRuleCard: () => {
    audio.playSFX('click');
    set({ showingRuleCard: false });
  },

  loopBack: () => {
    const s = get();
    // Salvation Mode: "loop again" restarts the Salvation Protocol with a
    // fresh tally + pool. There is no loop-count memory in this mode — the
    // tally is the only state, and it resets to zero. We do NOT increment
    // loopCount (the déjà-vu / memory-flash systems are classic-mode only).
    if (s.gameMode === 'salvation') {
      audio.cutAll();
      audio.playSFX('whoosh');
      const fresh: GameState = {
        ...s,
        sceneId: SALVATION_START_SCENE_ID,
        scene: null,
        lineIndex: 0,
        showingChoices: false,
        showingRuleCard: false,
        flags: {},
        sanity: 100,
        trust: { ...INITIAL_TRUST },
        inventory: [],
        deductions: [],
        ruleBreakCount: 0,
        endingId: null,
        log: [],
        déjàVuChoice: null,
        crossExamActive: false,
        verifiedRules: [],
        verifyBoardActive: false,
        lastVerifyResult: null,
        // Fresh soul tally + pool — every save / punish is earned anew.
        savedCount: 0,
        punishedCount: 0,
        savedPeople: [],
        punishedPeople: [],
        rescuePool: [...SALVATION_POOL],
      };
      const loaded = loadSceneState(fresh, SALVATION_START_SCENE_ID);
      set({ screen: 'dialogue', ...loaded } as Partial<GameState>);
      return;
    }
    const newLoopCount = s.loopCount + 1;
    const retainedClues = [...s.retainedClues];
    // Loop transition: cut the current bed and play a whoosh to sell the
    // reality-fray as the player spirals back to the start.
    audio.cutAll();
    audio.playSFX('whoosh');
    set({
      loopCount: newLoopCount,
      retainedClues,
      inventory: [...retainedClues],
      flags: {},
      sanity: 100,
      trust: { ...INITIAL_TRUST },
      deductions: [],
      ruleBreakCount: 0,
      endingId: null,
      // Phone events re-fire each loop — the phone is a live device. The
      // phone log (resolved calls) persists across loops so the Codex can
      // review them, but the "already triggered" set clears so calls ring
      // again on a fresh playthrough.
      triggeredPhoneEvents: [],
      // Transient UI state resets. choiceLog + rememberedDestruction +
      // flippedRules are intentionally NOT cleared — they are the
      // protagonist's accumulated memory across loops (Slay the Princess
      // déjà-vu + DDLC remembers + the Day-3 flip the Codex already logged).
      // verifiedRules DOES clear — each loop re-tests the player on the rules.
      déjàVuChoice: null,
      crossExamActive: false,
      verifiedRules: [],
      // Classic loopBack: ensure Salvation Mode state is cleared so a prior
      // alternate-mode run does not leak into the classic loop.
      verifyBoardActive: false,
      lastVerifyResult: null,
    });
    const fresh = get();
    const loaded = loadSceneState(fresh, START_SCENE_ID);
    set({ screen: 'dialogue', ...loaded } as Partial<GameState>);
  },

  goToTitle: () => {
    audio.stopBGM();
    const autosave = localStorage.getItem('btr_autosave');
    set({ screen: 'title', hasExistingSave: !!autosave });
  },

  // Chapter select — jump directly to a scene. Used by the chapter-select
  // screen to let players re-enter the story at a chosen day without playing
  // from the beginning. Inherits current trust/inventory state so choices
  // gated on trust still behave reasonably.
  startChapter: (sceneId: string) => {
    const s = get();
    const loaded = loadSceneState(s, sceneId);
    set({ screen: 'dialogue', ...loaded } as Partial<GameState>);
  },

  // Record an ending in the gallery without transitioning to the ending
  // screen. Currently the ending is recorded inline in advance(); this
  // method is exposed for future use (e.g. dev tools, achievements).
  unlockEnding: (id: string) => {
    const unlocked = [...new Set([...get().unlockedEndings, id])];
    try {
      localStorage.setItem('btr_endings', JSON.stringify(unlocked));
    } catch {
      /* ignore */
    }
    set({ unlockedEndings: unlocked });
  },

  // Record a Tiger Dojo correction as witnessed. Called when the DojoOverlay
  // is dismissed. Persisted to localStorage so the collection meter survives
  // reloads and the player is not forced to re-watch lessons they've seen.
  recordDojo: (id: string) => {
    const seen = [...new Set([...get().seenDojos, id])];
    try {
      localStorage.setItem('btr_dojos', JSON.stringify(seen));
    } catch {
      /* ignore quota errors */
    }
    set({ seenDojos: seen });
  },

  // Phone Trigger: mark an event as fired this loop so it does not re-fire
  // on scene re-entry. Returns true when newly triggered, false if already
  // fired. Callers use the return value to decide whether to play the
  // ringtone and surface the PhoneDevice.
  triggerPhoneEvent: (id: string) => {
    const s = get();
    if (s.triggeredPhoneEvents.includes(id)) return false;
    set({ triggeredPhoneEvents: [...s.triggeredPhoneEvents, id] });
    return true;
  },

  // Phone Trigger: record a resolved call/message in the phone log. Dedupes
  // by id (a re-answered call updates its status rather than duplicating),
  // and persists to localStorage so the Codex's "Calls" tab can review the
  // history across sessions. If the event carries grantsClue and the status
  // is answered/read, the clue is added to inventory + retainedClues so it
  // survives the loop.
  recordPhoneLog: (entry: PhoneLogEntry) => {
    const s = get();
    // Replace any existing entry with the same id (loop replay), then
    // prepend the new one so the log reads newest-first.
    const filtered = s.phoneLog.filter((e) => e.id !== entry.id);
    const phoneLog = [entry, ...filtered].slice(0, 60);
    try {
      localStorage.setItem('btr_phone_log', JSON.stringify(phoneLog));
    } catch {
      /* ignore quota errors */
    }
    set({ phoneLog });
  },

  // Phone Trigger: grant a clue outside the scene action pipeline. Adds to
  // inventory + retainedClues so the clue survives the loop. No-op if the
  // player already holds the clue.
  addClue: (clue: string) => {
    const s = get();
    if (s.inventory.includes(clue)) return;
    set({
      inventory: [...s.inventory, clue],
      retainedClues: s.retainedClues.includes(clue)
        ? s.retainedClues
        : [...s.retainedClues, clue],
    });
  },

  // Apply a set of GameActions outside the scene-choice pipeline (used by
  // Steins;Gate phone replies and the DDLC file browser). Runs them through
  // the same applyActions pipeline as scene choices so trust, sanity, flags,
  // and clues all update consistently. Does NOT advance the scene — it only
  // mutates state. Also re-syncs derived flags (is_looping, trust_*_high)
  // so any action that swings trust immediately reflects in the active
  // scene's choice gating without waiting for a scene transition.
  applyGameActions: (actions: GameAction[]) => {
    const s = get();
    const applied = applyActions(s, actions);
    // Re-sync derived flags from the updated trust/inventory so the active
    // scene's choice gating reads the post-action state without waiting for
    // a scene transition.
    const flags = { ...(applied.flags ?? s.flags) };
    flags.is_looping = (applied.loopCount ?? s.loopCount) >= 1;
    const npcs = ['linye', 'suwan', 'chenmo', 'xiaohe', 'laozhou', 'baijing'];
    const trust = applied.trust ?? s.trust;
    for (const id of npcs) {
      const v = Number(trust?.[id] ?? 0);
      flags[`trust_${id}_high`] = (Number.isFinite(v) ? v : 0) >= 75;
    }
    flags.any_trust_high = npcs.some((id) => (Number(trust?.[id] ?? 0) || 0) >= 75);
    set({ ...applied, flags } as Partial<GameState>);
  },

  // DDLC file system: record a file as deleted. Persisted to localStorage
  // so the deletion survives reloads and loops. Only records the deletion —
  // the FileBrowser handles the consequences (clue / flag / crash overlay)
  // since it has access to the file's onDelete config.
  deleteFile: (fileId: string) => {
    const s = get();
    if (s.deletedFiles.includes(fileId)) return;
    const deletedFiles = [...s.deletedFiles, fileId];
    try {
      localStorage.setItem('btr_deleted_files', JSON.stringify(deletedFiles));
    } catch {
      /* ignore quota errors */
    }
    set({ deletedFiles });
  },

  // Character profile destruction: mark a character's profile file as
  // destroyed. Persisted to localStorage so the corruption survives
  // reloads. The Game Master frames this as "the player edited something
  // they should not have" — the FakeCrashOverlay fires shortly after.
  destroyProfile: (id: string) => {
    const s = get();
    if (s.destroyedProfiles.includes(id)) return;
    const destroyed = [...s.destroyedProfiles, id];
    try {
      localStorage.setItem('btr_destroyed_profiles', JSON.stringify(destroyed));
    } catch {
      /* ignore quota errors */
    }
    set({ destroyedProfiles: destroyed });
  },

  // Character profile restoration: "repair" a destroyed file. Called by
  // the FakeCrashOverlay's recovery sequence. The restoration is diegetic
  // — the Game Master returns the character to the game as if fixing a
  // corrupted save, but the game remembers the player tried to erase them.
  // DDLC-inspired: the character now "remembers" being destroyed. The
  // memory is one-way and persists across loops/reloads — it surfaces in
  // the Cast panel as a disturbed note and exposes a `remembers_<id>` flag
  // (synced in loadSceneState) so scene choices can gate on it.
  restoreProfile: (id: string) => {
    const s = get();
    const destroyed = s.destroyedProfiles.filter((p) => p !== id);
    try {
      localStorage.setItem('btr_destroyed_profiles', JSON.stringify(destroyed));
    } catch {
      /* ignore */
    }
    const rememberedDestruction = s.rememberedDestruction.includes(id)
      ? s.rememberedDestruction
      : [...s.rememberedDestruction, id];
    try {
      localStorage.setItem('btr_remembered_destruction', JSON.stringify(rememberedDestruction));
    } catch {
      /* ignore quota errors */
    }
    // Also set the runtime flag immediately so the current scene's choices
    // can react without waiting for the next loadSceneState pass.
    set({
      destroyedProfiles: destroyed,
      rememberedDestruction,
      flags: { ...s.flags, [`remembers_${id}`]: true },
    });
  },

  // Set a single flag. Used by the DeductionBoard's "propose a theory"
  // panel to persist the player's accusation across scenes without going
  // through the choice/action pipeline.
  setFlag: (key, value) => {
    set({ flags: { ...get().flags, [key]: value } });
  },

  // DDLC player name: persist to localStorage so it survives reloads. We trim
  // and cap the length so the Game Master's address line never overflows the
  // dialogue box. Once set (including to empty), we do not re-prompt — the
  // name is the player's first act in the game and the game remembers it.
  setPlayerName: (name) => {
    const trimmed = name.trim().slice(0, 24);
    try {
      localStorage.setItem('btr_player_name', JSON.stringify(trimmed));
    } catch {
      /* ignore quota errors */
    }
    set({ playerName: trimmed });
  },

  // Slay the Princess hesitation: record a weighed-but-untaken choice.
  // Tagged with the current loopCount so a later loop can surface it as a
  // "...you weighed this before" whisper. Deduped per (sceneId, choiceText,
  // loopCount) so re-hovering the same option in the same loop does not
  // bloat the log. Persisted in its own key alongside choiceLog.
  recordHesitation: (sceneId, choiceText) => {
    const s = get();
    const loopCount = s.loopCount;
    const exists = s.hesitatedChoices.some(
      (h) =>
        h.sceneId === sceneId &&
        h.choiceText === choiceText &&
        h.loopCount === loopCount,
    );
    if (exists) return;
    const hesitatedChoices = [
      ...s.hesitatedChoices,
      { sceneId, choiceText, loopCount },
    ];
    try {
      localStorage.setItem('btr_hesitations', JSON.stringify(hesitatedChoices));
    } catch {
      /* ignore quota errors */
    }
    set({ hesitatedChoices });
  },

  // Cross-exam: a correct objection. Runs the testimony's present actions
  // (clue grants, flag sets, trust changes) and advances to the present's
  // `next` scene. Mirrors selectChoice's flow minus the choiceLog recording
  // (cross-exam resolutions are not choices the player would repeat).
  crossExamResolve: (testimony) => {
    const s = get();
    const present = testimony.present;
    if (!present) return;
    const actionState = applyActions(s, present.actions);
    // Correct objection: the objection brass stab lands first (the "hit"),
    // then the scene advances. Distinct from a generic reveal so the player
    // reads it as a triumphant courtroom beat.
    audio.playSFX('objection');
    const next = loadSceneState({ ...s, ...actionState } as GameState, present.next);
    set({ crossExamActive: false, ...actionState, ...next } as Partial<GameState>);
  },

  // Cross-exam: a wrong objection. Costs sanity (the witness's patience
  // wearing thin) and stays in the cross-exam so the player can try again.
  // Capped at sanity 0 by applyActions. Plays a dissonant stinger so the
  // mistake reads as a beat, not a silent no-op.
  crossExamWrongPresent: (cost) => {
    const s = get();
    const actionState = applyActions(s, [{ type: 'adjustSanity', value: -Math.max(0, cost) }]);
    audio.playSFX('stinger');
    set({ ...actionState } as Partial<GameState>);
  },

  // Cross-exam: the player gives up. Advances to the scene's giveUpNext if
  // configured; otherwise does nothing (the player must keep examining).
  // No sanity cost — giving up is its own narrative consequence (the
  // contradiction goes unexposed), no need to also punish mechanically.
  crossExamGiveUp: () => {
    const s = get();
    const giveUpNext = s.scene?.crossExam?.giveUpNext;
    if (!giveUpNext) return;
    audio.playSFX('whoosh');
    const next = loadSceneState(s, giveUpNext);
    set({ crossExamActive: false, ...next } as Partial<GameState>);
  },

  // Salvation Mode: judge a rule on the verify board. Looks up the rule's
  // actual truth value (isLie) and applies the contract:
  //   - Fake rule judged "fake" (correct)  → save_certain (definite save)
  //   - Real rule judged "real" (correct)  → save_maybe (50% save; on miss,
  //     save_failed — no one saved AND no one punished, the "might" clause)
  //   - Wrong judgment (either direction)  → punish (definite punish)
  // Saves/punishes draw a name from the rescue pool; once the pool is empty
  // the count still increments but no name is assigned (the tally is the
  // only thing the ending resolver reads). Marks the rule verified so the
  // VerifyBoard hides it; surfaces the outcome via lastVerifyResult.
  resolveVerify: (ruleId: string, judgedAs: 'real' | 'fake') => {
    const s = get();
    if (!s.scene?.ruleCard) return;
    // Already judged — no double-weighing.
    if (s.verifiedRules.includes(ruleId)) return;
    const rule = s.scene.ruleCard.find((r) => r.id === ruleId);
    if (!rule) return;

    const judgedLie = judgedAs === 'fake';
    const correct = judgedLie === rule.isLie;

    let outcome: 'save_certain' | 'save_maybe' | 'save_failed' | 'punish';
    let savedCount = s.savedCount;
    let punishedCount = s.punishedCount;
    const savedPeople = [...s.savedPeople];
    const punishedPeople = [...s.punishedPeople];
    const rescuePool = [...s.rescuePool];
    let targetId: string | undefined;

    // The verify config may bind a specific soul to this round via
    // `targetSoul`. When set, the save/punish outcome targets that character
    // instead of a random draw — this lets the narrative tie a judgment to a
    // named soul whose story the player just read. Falls back to random if
    // the target is no longer in the pool (already resolved earlier).
    const boundSoul = s.scene.verifyBoard?.targetSoul;
    const drawFromPool = (): string | undefined => {
      if (rescuePool.length === 0) return undefined;
      if (boundSoul && rescuePool.includes(boundSoul)) {
        const i = rescuePool.indexOf(boundSoul);
        return rescuePool.splice(i, 1)[0];
      }
      const idx = Math.floor(Math.random() * rescuePool.length);
      return rescuePool.splice(idx, 1)[0];
    };

    if (correct && rule.isLie) {
      // Fake rule verified → DEFINITE save. The lies are the Game Master's
      // gifts — exposing them frees a soul for certain.
      outcome = 'save_certain';
      targetId = drawFromPool();
      if (targetId) savedPeople.push(targetId);
      savedCount += 1;
      audio.playSFX('chime');
    } else if (correct && !rule.isLie) {
      // Real rule verified → MIGHT save (50%). The truth is heavier than
      // the lie; verifying it only sometimes frees a soul.
      if (Math.random() < 0.5) {
        outcome = 'save_maybe';
        targetId = drawFromPool();
        if (targetId) savedPeople.push(targetId);
        savedCount += 1;
        audio.playSFX('chime');
      } else {
        // The "might" did not land — no one saved, no one punished. The
        // verification succeeded but the truth was too heavy to lift anyone
        // out. Distinct from punish (a wrong judgment).
        outcome = 'save_failed';
        audio.playSFX('click');
      }
    } else {
      // Wrong judgment → verification FAILED → DEFINITE punish. The Game
      // Master does not describe the punishment; he only counts it.
      outcome = 'punish';
      targetId = drawFromPool();
      if (targetId) punishedPeople.push(targetId);
      punishedCount += 1;
      audio.playSFX('stinger');
    }

    // Mark the rule verified so the VerifyBoard hides it. The rule keeps
    // taking effect mechanically — verification is reading, not repeal.
    const verifiedRules = [...s.verifiedRules, ruleId];

    set({
      savedCount,
      punishedCount,
      savedPeople,
      punishedPeople,
      rescuePool,
      verifiedRules,
      lastVerifyResult: { ruleId, judgedAs, outcome, targetId },
    } as Partial<GameState>);
  },

  // Salvation Mode: advance past the verify board once every rule on the
  // card has been judged. The VerifyBoard only renders this button when
  // verifiedRules covers every rule in scene.ruleCard, so this is safe to
  // call — it loads the scene's verifyBoard.next and hands control back to
  // the normal advance flow.
  verifyBoardContinue: () => {
    const s = get();
    const next = s.scene?.verifyBoard?.next;
    if (!next) return;
    audio.playSFX('whoosh');
    const loaded = loadSceneState(s, next);
    set({ verifyBoardActive: false, ...loaded } as Partial<GameState>);
  },

  // Mark a rule as verified. Called by selectChoice when a choice carries
  // `verifiesRule`. Exposed publicly so future UI (e.g. a "mark as read"
  // button on the rule card) can also verify without going through a choice.
  verifyRule: (ruleId: string) => {
    const s = get();
    if (s.verifiedRules.includes(ruleId)) return;
    set({ verifiedRules: [...s.verifiedRules, ruleId] });
  },

  // Complete a side quest and unlock its associated side story scene.
  // Persists to localStorage so the completion survives reloads. Idempotent.
  completeSideQuest: (questId: string, storySceneId: string) => {
    const s = get();
    const completedSideQuests = s.completedSideQuests.includes(questId)
      ? s.completedSideQuests
      : [...s.completedSideQuests, questId];
    const unlockedSideStories = s.unlockedSideStories.includes(storySceneId)
      ? s.unlockedSideStories
      : [...s.unlockedSideStories, storySceneId];
    try {
      localStorage.setItem(
        'btr_side_quests',
        JSON.stringify({ completed: completedSideQuests, unlocked: unlockedSideStories }),
      );
    } catch {
      /* ignore quota errors */
    }
    set({ completedSideQuests, unlockedSideStories });
  },
}));

// Autosave on scene change (subscribed outside React for safety)
useGame.subscribe((state, prev) => {
  if (state.sceneId !== prev.sceneId && state.screen === 'dialogue') {
    const payload: SavePayload = {
      sceneId: state.sceneId,
      flags: state.flags,
      sanity: state.sanity,
      trust: state.trust,
      inventory: state.inventory,
      deductions: state.deductions,
      ruleBreakCount: state.ruleBreakCount,
      loopCount: state.loopCount,
      retainedClues: state.retainedClues,
      verifiedRules: state.verifiedRules,
      // Persist the game mode + Salvation tally / pool so an autosave made
      // mid-mode loads back into the correct scene map with the right count.
      gameMode: state.gameMode,
      savedCount: state.savedCount,
      punishedCount: state.punishedCount,
      savedPeople: state.savedPeople,
      punishedPeople: state.punishedPeople,
      rescuePool: state.rescuePool,
    };
    writeSave('autosave' as unknown as number, payload);
  }
});
