import { useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import { useGame } from '@/engine/store';
import { SCENES } from '@/data/chapters';
import type { GameRule } from '@/engine/types';
import type { PhoneLogEntry } from '@/data/phoneEvents';
import { BookMarked, MapPin, ScrollText, X, Lock, Phone, MessageSquare } from 'lucide-react';

// Codex / Journal — a unified reference panel inspired by VA-11 Hall-A's
// client binder and DDLC's poem collection. Unlike the Deduction Board
// (which is a *gameplay* surface for combining clues into theories), the
// Codex is a *passive* reference: it catalogues the rules the player has
// witnessed and the locations they have visited, so they can refresh their
// memory without replaying the chapter.
//
// What's shown:
//  - Rules Witnessed: every ruleCard the player has reached, grouped by day.
//    The lie stays hidden unless the player has the `identified_lie` flag
//    (so the Codex never spoils the puzzle, but does confirm a guess).
//  - Locations: a brief atmospheric entry for each background setting the
//    player has visited, unlocked progressively by chapter.
//
// Opened via the in-game menu or the 'J' hotkey.

// Static lore entries for each location setting. Unlocked by chapter.
// These are intentionally brief — flavor, not exposition — so the Codex
// reads like a field journal rather than an encyclopedia.
const LOCATIONS: { key: string; chapter: number; name: string; note: string }[] = [
  {
    key: 'white_room',
    chapter: 1,
    name: 'The White Room',
    note: 'No source of light, no shadow. The first place you wake. The screen speaks from nowhere.',
  },
  {
    key: 'corridor',
    chapter: 2,
    name: 'The Endless Corridor',
    note: 'Lights that dim in the wrong direction. A floor that counts your steps. It does not end at one thousand.',
  },
  {
    key: 'feast',
    chapter: 3,
    name: 'The Feast',
    note: 'A long table set for seven. The food is real. The host is absent. Empty plates mean safety.',
  },
  {
    key: 'mirror',
    chapter: 4,
    name: 'The Mirror Hall',
    note: 'Reflections that smile out of sync. One of you does not cast one. The traitor has many faces here.',
  },
  {
    key: 'clock',
    chapter: 5,
    name: 'The Clock Room',
    note: 'A pendulum the size of a person. It does not tell the time — it takes it. Someone must give theirs.',
  },
  {
    key: 'choice',
    chapter: 6,
    name: 'The Choice',
    note: 'A door that opens for one and closes for the rest. The room asks you to nominate.',
  },
  {
    key: 'truth',
    chapter: 7,
    name: 'The Truth',
    note: 'No walls. Only the screen, larger now, patient. It waits for you to name the lie.',
  },
];

// All rule cards defined in the scene graph, indexed by chapter. Pre-computed
// once so the Codex can render them without scanning SCENES on every render.
const RULES_BY_CHAPTER: Record<number, GameRule[]> = (() => {
  const map: Record<number, GameRule[]> = {};
  for (const scene of Object.values(SCENES)) {
    if (!scene.ruleCard || scene.ruleCard.length === 0) continue;
    const ch = scene.chapter;
    // Use the first scene we find per chapter that has a ruleCard — there
    // is only ever one ruleCard scene per day, so this avoids duplicates.
    if (!map[ch]) map[ch] = scene.ruleCard;
  }
  return map;
})();

type Tab = 'rules' | 'locations' | 'calls';

export default function CodexPanel({ onClose }: { onClose: () => void }) {
  const scene = useGame((s) => s.scene);
  const flags = useGame((s) => s.flags);
  const loopCount = useGame((s) => s.loopCount);
  const phoneLog = useGame((s) => s.phoneLog);
  const verifiedRules = useGame((s) => s.verifiedRules);
  const flippedRules = useGame((s) => s.flippedRules);

  // Current chapter caps how much the Codex reveals — you can't read ahead
  // about a room you haven't entered. The cap is the player's current
  // chapter, so the Codex grows with progression.
  const currentChapter = scene?.chapter ?? 1;
  const identifiedLie = flags.identified_lie === true;

  const [tab, setTab] = useState<Tab>('rules');

  // Loop-aware: on a second playthrough, the Codex remembers everything
  // from the previous loop (all chapters) — your journal doesn't forget
  // just because the game did.
  const revealedChapters = loopCount > 0 ? 7 : currentChapter;

  const visibleRules = useMemo(() => {
    const result: { chapter: number; rules: GameRule[] }[] = [];
    for (let ch = 1; ch <= revealedChapters; ch++) {
      const rules = RULES_BY_CHAPTER[ch];
      if (rules && rules.length > 0) result.push({ chapter: ch, rules });
    }
    return result;
  }, [revealedChapters]);

  const visibleLocations = useMemo(
    () => LOCATIONS.filter((l) => l.chapter <= revealedChapters),
    [revealedChapters],
  );

  // Total rules and lies for the header counter — gives the player a sense
  // of how much they've witnessed and how many lies might still be hidden.
  const totalRules = visibleRules.reduce((n, g) => n + g.rules.length, 0);
  const liesFound = visibleRules.reduce(
    (n, g) => n + g.rules.filter((r) => r.isLie && identifiedLie).length,
    0,
  );
  const verifiedCount = visibleRules.reduce(
    (n, g) => n + g.rules.filter((r) => verifiedRules.includes(r.id)).length,
    0,
  );

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-50 flex items-center justify-center bg-void/92 backdrop-blur-md"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.96, y: 10 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.96, y: 10 }}
        onClick={(e) => e.stopPropagation()}
        className="vn-panel relative flex max-h-[85vh] w-full max-w-2xl flex-col px-6 py-6 md:px-8"
      >
        {/* Header */}
        <div className="mb-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <BookMarked size={16} className="text-blood-bright" />
            <span className="font-mono text-xs uppercase tracking-[0.4em] text-blood-bright">
              Codex
            </span>
            <span className="font-mono text-[9px] uppercase tracking-wider text-muted/60">
              {totalRules} rules witnessed
            </span>
            {verifiedCount > 0 && (
              <span className="font-mono text-[9px] uppercase tracking-wider text-muted/70">
                ◊ {verifiedCount} verified
              </span>
            )}
            {identifiedLie && (
              <span className="font-mono text-[9px] uppercase tracking-wider text-blood-bright/80">
                ◊ {liesFound} lie named
              </span>
            )}
          </div>
          <button
            onClick={onClose}
            className="text-muted transition-colors hover:text-bone"
            aria-label="Close"
          >
            <X size={18} />
          </button>
        </div>

        {/* Tabs */}
        <div className="mb-4 flex gap-2 border-b border-ash/60 pb-2">
          <TabButton
            active={tab === 'rules'}
            onClick={() => setTab('rules')}
            icon={<ScrollText size={12} />}
            label="Rules Witnessed"
          />
          <TabButton
            active={tab === 'locations'}
            onClick={() => setTab('locations')}
            icon={<MapPin size={12} />}
            label="Locations"
          />
          <TabButton
            active={tab === 'calls'}
            onClick={() => setTab('calls')}
            icon={<Phone size={12} />}
            label="Calls"
          />
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto pr-2">
          {tab === 'rules' && (
            <div className="flex flex-col gap-5">
              {visibleRules.length === 0 && (
                <p className="py-12 text-center font-serif text-sm italic text-muted/60">
                  You have witnessed no rules yet. The first day has not spoken.
                </p>
              )}
              {visibleRules.map(({ chapter, rules }) => (
                <div key={chapter}>
                  <div className="mb-2 flex items-baseline gap-3">
                    <span className="font-mono text-[10px] uppercase tracking-[0.4em] text-blood-bright">
                      Day {chapter}
                    </span>
                    <span className="h-px flex-1 bg-gradient-to-r from-blood/40 to-transparent" />
                  </div>
                  <ul className="flex flex-col gap-2">
                    {rules.map((rule) => {
                      const isVerified = verifiedRules.includes(rule.id);
                      // Day-3 flip: if the rule carries flipsOnDay3 and the
                      // player has reached chapter 3, the Codex shows the
                      // FLIPPED truth value. The original truth is struck
                      // through beneath, so the player can see the inversion
                      // happened — but only after they have seen Day 3.
                      const isFlipped =
                        rule.flipsOnDay3 && flippedRules.includes(rule.id);
                      const effectiveIsLie = isFlipped
                        ? rule.flipsOnDay3!.isLie
                        : rule.isLie;
                      const flipText = isFlipped
                        ? rule.flipsOnDay3!.text
                        : undefined;
                      // Only reveal which rule was the lie once the player
                      // has the identified_lie flag — otherwise mark every
                      // rule as "unknown" so the Codex never solves the
                      // puzzle for the player. A flipped rule's new truth
                      // follows the same gate.
                      const revealLie = effectiveIsLie && identifiedLie;
                      return (
                        <li
                          key={rule.id}
                          className={[
                            'flex items-start gap-2 border-l-2 pl-3 py-1.5',
                            revealLie
                              ? 'border-blood-bright bg-blood/5'
                              : isVerified
                              ? 'border-ash/40'
                              : 'border-ash/60',
                          ].join(' ')}
                        >
                          <span
                            className={[
                              'mt-1.5 h-1 w-1 shrink-0 rotate-45',
                              isVerified ? 'bg-muted' : 'bg-blood-bright',
                            ].join(' ')}
                          />
                          <div className="flex-1">
                            {/* If flipped, show the original (now-struck) text
                                beneath the new text so the inversion is visible. */}
                            {isFlipped && (
                              <p className="font-mono text-[10px] leading-relaxed text-muted/60 line-through">
                                {rule.text}
                              </p>
                            )}
                            <p
                              className={[
                                'font-mono text-xs leading-relaxed',
                                revealLie
                                  ? 'text-blood-bright line-through opacity-90'
                                  : isVerified
                                  ? 'text-bone/55'
                                  : 'text-bone/80',
                              ].join(' ')}
                            >
                              {flipText ?? rule.text}
                            </p>
                            {isFlipped && (
                              <span className="mt-0.5 block font-mono text-[8px] uppercase tracking-wider text-blood-bright/70">
                                ◊ truth inverted on day 3
                              </span>
                            )}
                          </div>
                          {isVerified && !revealLie && (
                            <span className="ml-auto shrink-0 font-mono text-[8px] uppercase tracking-wider text-muted/70">
                              ◊ verified
                            </span>
                          )}
                          {revealLie && (
                            <span className="ml-auto shrink-0 font-mono text-[8px] uppercase tracking-wider text-blood-bright">
                              ◊ {isFlipped ? 'lie now' : 'lie'}
                            </span>
                          )}
                        </li>
                      );
                    })}
                  </ul>
                </div>
              ))}
              {!identifiedLie && totalRules > 0 && (
                <p className="mt-2 text-center font-serif text-xs italic text-muted/70">
                  One rule each day is a lie. The Codex will not name it for you.
                </p>
              )}
              {flippedRules.length > 0 && (
                <p className="mt-2 text-center font-serif text-xs italic text-blood-bright/70">
                  Two rules from Day 1 have inverted. The game did not announce it.
                </p>
              )}
            </div>
          )}

          {tab === 'locations' && (
            <div className="flex flex-col gap-3">
              {visibleLocations.map((loc) => (
                <motion.div
                  key={loc.key}
                  initial={{ opacity: 0, x: -8 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.3 }}
                  className="border-l-2 border-blood-bright/40 pl-4 py-2"
                >
                  <div className="flex items-baseline justify-between gap-2">
                    <span className="font-serif text-base font-semibold text-bone">
                      {loc.name}
                    </span>
                    <span className="font-mono text-[9px] uppercase tracking-[0.3em] text-muted">
                      Day {loc.chapter}
                    </span>
                  </div>
                  <p className="mt-1 font-serif text-sm italic leading-relaxed text-bone/65">
                    {loc.note}
                  </p>
                </motion.div>
              ))}
              {/* Locked future locations tease what's ahead without spoiling. */}
              {LOCATIONS.filter((l) => l.chapter > revealedChapters).map((loc) => (
                <div
                  key={loc.key}
                  className="flex items-center gap-2 border-l-2 border-ash/40 pl-4 py-2 opacity-50"
                >
                  <Lock size={11} className="shrink-0 text-muted" />
                  <span className="font-mono text-xs uppercase tracking-wider text-muted">
                    Day {loc.chapter} — Not yet entered
                  </span>
                </div>
              ))}
            </div>
          )}

          {tab === 'calls' && <CallsTab entries={phoneLog} />}
        </div>

        {/* Footer */}
        <p className="mt-3 text-center font-mono text-[9px] uppercase tracking-[0.3em] text-muted/50">
          Esc to return ◊ {loopCount > 0 ? 'A loop remembers what a loop forgets' : 'The Codex grows as you go'}
        </p>
      </motion.div>
    </motion.div>
  );
}

function TabButton({
  active,
  onClick,
  icon,
  label,
}: {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}) {
  return (
    <button
      onClick={onClick}
      className={[
        'flex items-center gap-2 px-3 py-1.5 font-mono text-[10px] uppercase tracking-[0.25em] transition-all',
        active
          ? 'text-blood-bright border-b-2 border-blood-bright -mb-[9px] pb-[7px]'
          : 'text-muted hover:text-bone border-b-2 border-transparent',
      ].join(' ')}
    >
      <span className={active ? 'text-blood-bright' : 'text-muted/60'}>{icon}</span>
      {label}
    </button>
  );
}

// Calls tab — the phone's call history. Shows resolved calls and messages,
// newest-first, with a status badge (answered / declined / missed / read).
// Empty state teases that the phone is a live device the player hasn't
// engaged with yet.
function CallsTab({ entries }: { entries: PhoneLogEntry[] }) {
  if (entries.length === 0) {
    return (
      <div className="py-12 text-center">
        <Phone size={20} className="mx-auto mb-3 text-muted/40" />
        <p className="font-serif text-sm italic text-muted/60">
          No calls yet. The phone rings when the game wants your attention.
        </p>
        <p className="mt-1 font-mono text-[9px] uppercase tracking-[0.3em] text-muted/40">
          Answer to receive what it carries.
        </p>
      </div>
    );
  }
  return (
    <div className="flex flex-col gap-2.5">
      {entries.map((entry) => {
        const isCall = entry.kind === 'call';
        const Icon = isCall ? Phone : MessageSquare;
        const statusColor =
          entry.status === 'answered' || entry.status === 'read'
            ? 'text-bone/80'
            : entry.status === 'declined'
            ? 'text-muted/60'
            : 'text-blood-bright/70'; // missed
        const statusLabel =
          entry.status === 'answered'
            ? 'answered'
            : entry.status === 'declined'
            ? 'declined'
            : entry.status === 'read'
            ? 'read'
            : 'missed';
        return (
          <motion.div
            key={entry.id}
            initial={{ opacity: 0, x: -8 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.3 }}
            className={[
              'border-l-2 pl-4 py-2',
              entry.status === 'missed'
                ? 'border-blood-bright/60'
                : 'border-ash/60',
            ].join(' ')}
          >
            <div className="flex items-baseline justify-between gap-2">
              <div className="flex items-center gap-2">
                <Icon size={11} className="shrink-0 text-blood-bright/70" />
                <span className="font-mono text-[10px] uppercase tracking-[0.2em] text-bone">
                  {entry.from}
                </span>
              </div>
              <div className="flex items-center gap-2">
                <span className="font-mono text-[8px] uppercase tracking-wider text-muted/50">
                  loop {entry.loopCount}
                </span>
                <span
                  className={[
                    'font-mono text-[8px] uppercase tracking-[0.25em]',
                    statusColor,
                  ].join(' ')}
                >
                  {statusLabel}
                </span>
              </div>
            </div>
            <p className="mt-1 font-serif text-xs italic leading-relaxed text-bone/65">
              {entry.text}
            </p>
            {/* Steins;Gate reply: if the player picked a reply option, show
                the full conversation — the player's line and the caller's
                response — so the call history reads as a dialogue, not just
                an incoming line. */}
            {entry.chosenReply && (
              <div className="mt-2 space-y-1.5 border-l-2 border-muted/30 pl-3">
                <div>
                  <span className="block font-mono text-[7px] uppercase tracking-[0.3em] text-muted/50">
                    you replied
                  </span>
                  <p className="font-serif text-[11px] italic leading-relaxed text-bone/55">
                    {entry.chosenReply}
                  </p>
                </div>
                {entry.replyResponse && (
                  <p className="font-serif text-[11px] italic leading-relaxed text-bone/55">
                    {entry.replyResponse}
                  </p>
                )}
              </div>
            )}
          </motion.div>
        );
      })}
    </div>
  );
}
