import { motion } from 'framer-motion';
import type { Emotion } from '@/engine/types';
import { CHARACTERS } from '@/data/characters';
import { useGame } from '@/engine/store';

// CharacterFace — a full-figure portrait per character: head + body.
// The face is composed from the same primitive SVG shapes (eyes, brows,
// mouth) parametrised by character id and emotion, plus per-character
// hair, accessories (glasses, beard) and distinguishing features (mole,
// beauty mark, age lines). The body (neck, torso, arms, legs, clothing,
// gesture) is drawn from each profile's build/clothing/gesture fields so
// each character reads as a distinct complete person. The same emotion
// reads differently on different people, and each character has a
// signature pose/gesture that fires on certain emotions.
//
// The "you" face is intentionally ambiguous: no hair, no features, a
// near-blank mask. It sometimes glances toward the viewer and on certain
// emotions briefly takes on another character's tint — a visual whisper
// that the protagonist may not be under the player's full control.

export interface CharacterFaceProps {
  id: string;
  color: string;
  emotion: Emotion;
  // Optional override tint — used for the protagonist's "not-quite-you"
  // moments, where the face briefly flushes with another character's colour
  // to imply outside control.
  foreignTint?: string;
  // A subtle flag that nudges the protagonist's gaze toward the camera.
  lookingAtViewer?: boolean;
}

// Per-character face parameters. These describe the resting geometry of each
// face so the same emotion reads differently on different people — e.g.
// Chen Mo's narrow eyes stay narrow even when he is afraid, while Kohane's
// wide eyes go wider still.
interface FaceParams {
  eyeShape: 'round' | 'narrow' | 'droop' | 'sharp' | 'closed' | 'wide';
  browAngle: number; // degrees, positive = inner-down (angry), negative = inner-up (sad)
  mouthCurve: number; // positive = smile, negative = frown, 0 = flat
  // Asymmetric feature makes a face feel off — used sparingly to suggest
  // the face is a mask.
  asymmetry?: number;
}

function restingFace(id: string): FaceParams {
  switch (id) {
    case 'linye':
      return { eyeShape: 'narrow', browAngle: 0, mouthCurve: 0 };
    case 'suwan':
      return { eyeShape: 'round', browAngle: -3, mouthCurve: 0.4 };
    case 'chenmo':
      return { eyeShape: 'narrow', browAngle: 4, mouthCurve: -0.3, asymmetry: 1.5 };
    case 'xiaohe':
      return { eyeShape: 'wide', browAngle: -2, mouthCurve: -0.1 };
    case 'laozhou':
      return { eyeShape: 'closed', browAngle: 0, mouthCurve: 0.2 };
    case 'baijing':
      return { eyeShape: 'sharp', browAngle: 1, mouthCurve: 0, asymmetry: 0.8 };
    case 'you':
      // The protagonist: deliberately neutral, a near-blank mask.
      return { eyeShape: 'round', browAngle: 0, mouthCurve: 0 };
    default:
      return { eyeShape: 'round', browAngle: 0, mouthCurve: 0 };
  }
}

// Adjust the resting face toward an emotion. We don't fully overwrite the
// resting geometry — emotions nudge it, so a character stays recognisable.
function applyEmotion(base: FaceParams, emotion: Emotion): FaceParams {
  switch (emotion) {
    case 'happy':
      return { ...base, mouthCurve: Math.max(base.mouthCurve, 0.6), browAngle: base.browAngle * 0.5 };
    case 'sad':
      return { ...base, mouthCurve: Math.min(base.mouthCurve, -0.5), browAngle: Math.min(base.browAngle, -4) };
    case 'angry':
      return { ...base, browAngle: Math.max(base.browAngle, 8), mouthCurve: Math.min(base.mouthCurve, -0.4) };
    case 'fear':
      return { ...base, eyeShape: 'wide', browAngle: Math.min(base.browAngle, -5), mouthCurve: Math.min(base.mouthCurve, -0.3) };
    case 'thinking':
      return { ...base, browAngle: base.browAngle + 1, mouthCurve: 0 };
    case 'cold':
      return { ...base, eyeShape: base.eyeShape === 'wide' ? 'narrow' : base.eyeShape, mouthCurve: 0 };
    case 'pained':
      return { ...base, eyeShape: 'droop', browAngle: Math.min(base.browAngle, -3), mouthCurve: Math.min(base.mouthCurve, -0.5) };
    default:
      return base;
  }
}

// --- Hair ---------------------------------------------------------------
// Hair colour per character. Most of the cast has near-black hair; Voss
// is white. We use a dark neutral rather than the accent colour so the
// portraits read as people, not as colour-coded tokens.
function hairColor(id: string): string {
  if (id === 'laozhou') return '#e8e8e8'; // white
  return '#0d0d14'; // near-black (slightly bluer than void for separation)
}

