// --- Accessories: glasses, beard ---------------------------------------
function renderAccessories(id: string, emotion: Emotion) {
  switch (id) {
    case 'linye': {
      // Wire-rim glasses. When thinking, he nudges them up — a quick
      // up-and-back translate on the glasses group.
      const nudge = emotion === 'thinking';
      return (
        <motion.g
          key={`glasses-${id}-${nudge}`}
          stroke="#cfd2dc"
          strokeWidth={1}
          fill="none"
          opacity={0.85}
          initial={false}
          animate={nudge ? { y: [0, -1.6, 0] } : { y: 0 }}
          transition={nudge ? { duration: 0.7, repeat: Infinity, repeatDelay: 1.6 } : { duration: 0.2 }}
        >
          <rect x="32" y="38" width="12" height="8" rx="2" />
          <rect x="56" y="38" width="12" height="8" rx="2" />
          <path d="M 44 42 L 56 42" />
          <path d="M 32 41 L 27 39" />
          <path d="M 68 41 L 73 39" />
        </motion.g>
      );
    }
    case 'laozhou':
      // Round reading glasses on a chain. Steadier than Lin Ye's — Voss
      // does not fidget, he steeples his fingers (implied by the head tilt
      // in poseFor).
      return (
        <g stroke="#cfd2dc" strokeWidth={1} fill="none" opacity={0.8}>
          <circle cx="38" cy="42" r="5.5" />
          <circle cx="62" cy="42" r="5.5" />
          <path d="M 43.5 41 L 56.5 41" />
          {/* chain to the side */}
          <path d="M 67.5 44 Q 74 48 78 52" />
        </g>
      );
    default:
      return null;
  }
}

