// --- Emotion-driven pose ----------------------------------------------
// A whole-body lean/scale/tilt applied to the portrait so each emotion
// has a visible *action* (动作), not just a facial expression. Per-
// character so the gesture matches the person — e.g. Chen Mo puffs up
// when angry (squares shoulders), Kohane shrinks when afraid (hugs
// elbows), Bai Jing tilts her head when cold.
interface Pose {
  x: number;
  y: number;
  scale: number;
  rotate: number;
}
function poseFor(id: string, emotion: Emotion): Pose {
  const base: Pose = { x: 0, y: 0, scale: 1, rotate: 0 };
  const e: Partial<Record<Emotion, Pose>> = {};
  switch (id) {
    case 'chenmo':
      e.angry = { x: 0, y: 1, scale: 1.04, rotate: 0 }; // puffs up
      e.fear = { x: 0, y: -1, scale: 0.98, rotate: 0 };
      break;
    case 'xiaohe':
      e.fear = { x: 0, y: 1.5, scale: 0.95, rotate: -1.5 }; // shrinks
      e.sad = { x: 0, y: 1.5, scale: 0.97, rotate: 0 };
      e.happy = { x: 0, y: -0.5, scale: 1.02, rotate: 0 };
      break;
    case 'baijing':
      e.cold = { x: 0, y: 0, scale: 1, rotate: 3 }; // head tilt (signature)
      e.thinking = { x: 0, y: 0, scale: 1, rotate: 2.5 };
      break;
    case 'laozhou':
      e.thinking = { x: 0, y: 0, scale: 1, rotate: -2 }; // steeples, tilts
      break;
    case 'linye':
      e.thinking = { x: 0, y: 0, scale: 1, rotate: -1.5 };
      e.angry = { x: 0, y: 0.5, scale: 1.02, rotate: 0 };
      break;
    case 'suwan':
      e.sad = { x: 0, y: 1, scale: 0.99, rotate: -1 };
      e.fear = { x: -0.5, y: 0, scale: 0.99, rotate: -1.5 };
      break;
    case 'you':
      e.thinking = { x: 0, y: 0, scale: 1, rotate: -1 };
      break;
  }
  return e[emotion] ?? base;
}

// Render two eyes given a shape. Eyes are placed symmetrically around the
// face's vertical centre line. The asymmetry offset shifts one eye slightly
// to make a face feel hand-drawn rather than mechanical.
function renderEyes(shape: FaceParams['eyeShape'], asymmetry: number, color: string) {
  const lx = 38 - asymmetry;
  const rx = 62 + asymmetry;
  const cy = 42;
  const stroke = color;
  switch (shape) {
    case 'narrow':
      return (
        <g stroke={stroke} strokeWidth={1.6} strokeLinecap="round" fill="none">
          <path d={`M ${lx - 5} ${cy} Q ${lx} ${cy - 2} ${lx + 5} ${cy}`} />
          <path d={`M ${rx - 5} ${cy} Q ${rx} ${cy - 2} ${rx + 5} ${cy}`} />
        </g>
      );
    case 'droop':
      return (
        <g stroke={stroke} strokeWidth={1.6} strokeLinecap="round" fill="none">
          <path d={`M ${lx - 5} ${cy - 2} Q ${lx} ${cy + 2} ${lx + 5} ${cy - 2}`} />
          <path d={`M ${rx - 5} ${cy - 2} Q ${rx} ${cy + 2} ${rx + 5} ${cy - 2}`} />
        </g>
      );
    case 'sharp':
      return (
        <g stroke={stroke} strokeWidth={1.6} strokeLinecap="round" fill="none">
          <path d={`M ${lx - 5} ${cy + 1} L ${lx + 5} ${cy - 2}`} />
          <path d={`M ${rx - 5} ${cy - 2} L ${rx + 5} ${cy + 1}`} />
        </g>
      );
    case 'closed':
      return (
        <g stroke={stroke} strokeWidth={1.6} strokeLinecap="round" fill="none">
          <path d={`M ${lx - 5} ${cy} L ${lx + 5} ${cy}`} />
          <path d={`M ${rx - 5} ${cy} L ${rx + 5} ${cy}`} />
        </g>
      );
    case 'wide':
      return (
        <g>
          <circle cx={lx} cy={cy} r={3.4} fill={color} />
          <circle cx={rx} cy={cy} r={3.4} fill={color} />
          <circle cx={lx} cy={cy} r={1} fill="#0a0a0f" />
          <circle cx={rx} cy={cy} r={1} fill="#0a0a0f" />
        </g>
      );
    case 'round':
    default:
      return (
        <g>
          <circle cx={lx} cy={cy} r={2.6} fill={color} />
          <circle cx={rx} cy={cy} r={2.6} fill={color} />
          <circle cx={lx} cy={cy + 0.3} r={0.8} fill="#0a0a0f" />
          <circle cx={rx} cy={cy + 0.3} r={0.8} fill="#0a0a0f" />
        </g>
      );
  }
}

function renderBrows(angle: number, asymmetry: number, color: string) {
  const lx = 38 - asymmetry;
  const rx = 62 + asymmetry;
  const by = 34;
  // Positive angle => inner ends down (angry). Negative => inner ends up (sad/fear).
  const dy = (angle / 10) * 2;
  return (
    <g stroke={color} strokeWidth={1.4} strokeLinecap="round" fill="none" opacity={0.85}>
      <path d={`M ${lx - 5} ${by - dy} L ${lx + 5} ${by + dy}`} />
      <path d={`M ${rx - 5} ${by + dy} L ${rx + 5} ${by - dy}`} />
    </g>
  );
}

function renderMouth(curve: number, color: string) {
  const mx = 50;
  const my = 56;
  const w = 7;
  // curve in [-1, 1] roughly; map to a quadratic control point Y offset.
  const cy = my - curve * 4;
  return (
    <path
      d={`M ${mx - w} ${my} Q ${mx} ${cy} ${mx + w} ${my}`}
      stroke={color}
      strokeWidth={1.5}
      strokeLinecap="round"
      fill="none"
      opacity={0.85}
    />
  );
}

// --- Body --------------------------------------------------------------
// A full figure per character: neck, shoulders, torso, arms and legs,
// plus clothing and a signature gesture drawn from each profile's
// `build` / `clothing` / `gesture` fields. Rendered in the same
// hairline-stroke aesthetic as the face so head and body read as one
// person rather than "a circle on a candle". Drawn before the head so the
// chin overlaps the neck. Coordinates share the head's frame: head circle
// cx=50 cy=42 r=22 (chin ≈ y=64); the figure runs down to y≈212 inside the
