import { useMemo, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { audio } from '@/engine/audioEngine';
import { useGame } from '@/engine/store';
import {
  ALL_FILES,
  isFileVisible,
  type VFile,
} from '@/data/fileSystem';
import {
  Folder,
  File as FileIcon,
  FileText,
  FileX2,
  ArrowLeft,
  X,
  Lock,
  Terminal,
  AlertTriangle,
} from 'lucide-react';

// DDLC-inspired virtual file browser. Renders the game's back-end file
// system as a navigable tree: folders open, files read, and certain files
// can be deleted to trigger hidden 剧情 — clues, flags, the FakeCrashOverlay
// (for .chr files), or a quiet "the game noticed" reaction.
//
// The browser is the player's hand in the machinery. Most files are
// readable flavour (logs, rule dumps); a few are load-bearing. Deleting a
// load-bearing file is the DDLC move — the game reacts, and the player
// learns something they could not learn by just playing. Protected files
// (rules.dat, loop_counter.dat, you.chr, game_master.exe) cannot be
// removed, but the attempt itself may set a flag or draw a reaction.
//
// Reached from the in-game menu. Same overlay pattern as CodexPanel / Cast.

interface Props {
  onClose: () => void;
  // Triggered when the player deletes a .chr file — the parent (GameStage)
  // shows the FakeCrashOverlay, which "repairs" the file. Mirrors the
  // onDestroy callback used by the Cast panel.
  onCrashProfile?: (profileId: string) => void;
}

// Root folder id = undefined. We render root-level files + top-level folders
// when no folder is open.
const ROOT = undefined as string | undefined;

export default function FileBrowser({ onClose, onCrashProfile }: Props) {
  const flags = useGame((s) => s.flags);
  const inventory = useGame((s) => s.inventory);
  const loopCount = useGame((s) => s.loopCount);
  const completedSideQuests = useGame((s) => s.completedSideQuests);
  const deletedFiles = useGame((s) => s.deletedFiles);
  const deleteFile = useGame((s) => s.deleteFile);
  const addClue = useGame((s) => s.addClue);
  const applyGameActions = useGame((s) => s.applyGameActions);
  const destroyProfile = useGame((s) => s.destroyProfile);

  // Currently open folder id (undefined = root). Breadcrumb navigation.
  const [openFolder, setOpenFolder] = useState<string | undefined>(ROOT);
  // The file currently being read (its content shown in the viewer).
  const [reading, setReading] = useState<VFile | null>(null);
  // The file whose deletion is being confirmed (inline two-click).
  const [confirmId, setConfirmId] = useState<string | null>(null);
  // The most recent game reaction to a deletion / attempted deletion. Shown
  // as a red system whisper at the bottom of the panel.
  const [reaction, setReaction] = useState<string | null>(null);

  const ctx = useMemo(
    () => ({ flags, inventory, loopCount, completedSideQuests }),
    [flags, inventory, loopCount, completedSideQuests],
  );

  // Files visible in the current context (gated by loop/flag/clue/quest).
  const visibleFiles = useMemo(
    () => ALL_FILES.filter((f) => isFileVisible(f, ctx)),
    [ctx],
  );

  // Entries in the current folder: folders first, then files, in authored
  // order. At root, top-level folders + root-level files show together.
  const entries = useMemo(() => {
    const inFolder = visibleFiles.filter((f) => f.folder === openFolder);
    const folders = inFolder.filter((f) => f.kind === 'folder');
    const files = inFolder.filter((f) => f.kind === 'file');
    return [...folders, ...files];
  }, [visibleFiles, openFolder]);

  const currentFolderName = openFolder
    ? visibleFiles.find((f) => f.id === openFolder)?.name ?? '/'
    : '/';

  // Open a folder or file. Folders navigate; files show their content.
  const handleEntryClick = (file: VFile) => {
    if (file.kind === 'folder') {
      audio.playSFX('click');
      setOpenFolder(file.id);
      setReading(null);
      setReaction(null);
      return;
    }
    // Reading a deleted file shows a placeholder — the content is gone.
    if (deletedFiles.includes(file.id)) {
      audio.playSFX('phone_busy');
      setReading(file);
      return;
    }
    audio.playSFX('click');
    setReading(file);
    setReaction(null);
  };

  // Apply a file's deletion consequences. Protected files are refused (the
  // game won't unmake them) but may still surface a reaction / set a flag
  // for the attempt. Non-protected files are marked deleted, and any clue /
  // action / crash consequence fires.
  const handleDelete = (file: VFile) => {
    setConfirmId(null);
    const od = file.onDelete;

    // Protected: the file cannot be removed, but the attempt may carry
    // consequences (a flag, a clue, a refusal line). This is the DDLC
    // "delete yourself" beat — the game refuses, but it noticed.
    if (file.protected) {
      if (od?.actions && od.actions.length > 0) applyGameActions(od.actions);
      if (od?.grantClue) addClue(od.grantClue);
      setReaction(od?.reaction ?? `${file.name} is protected. the game refuses.`);
      audio.playSFX('phone_busy');
      return;
    }

    // .chr files trigger the FakeCrashOverlay via the parent callback. The
    // overlay "repairs" the file (restoreProfile), so we do NOT mark it
    // deleted in the file-system sense — the crash/repair cycle is the
    // consequence, and the file returns readable (though the character
    // remembers the attempt). Hand the crash to the parent and close the
    // browser so the overlay can take over the screen cleanly.
    if (od?.crashProfile) {
      if (od.actions && od.actions.length > 0) applyGameActions(od.actions);
      if (od.grantClue) addClue(od.grantClue);
      if (od.reaction) setReaction(od.reaction);
      // Mark the character profile as destroyed — mirrors the Cast panel's
      // destroy flow. The FakeCrashOverlay's recovery will restoreProfile,
      // which adds the character to rememberedDestruction (they "remember"
      // the deletion attempt). We do NOT deleteFile here: the crash/repair
      // cycle is the consequence, and the .chr returns readable afterwards.
      destroyProfile(od.crashProfile);
      audio.playSFX('death');
      onCrashProfile?.(od.crashProfile);
      return;
    }

    // Non-protected, non-.chr file: mark deleted, apply consequences, show
    // the game's reaction. The deletion is permanent within the loop.
    deleteFile(file.id);
    if (od?.actions && od.actions.length > 0) applyGameActions(od.actions);
    if (od?.grantClue) {
      addClue(od.grantClue);
      window.setTimeout(() => audio.playSFX('chime'), 200);
    }
    if (od?.reaction) setReaction(od.reaction);
    audio.playSFX('stinger');
    // If we just deleted the file we were reading, close the viewer.
    if (reading?.id === file.id) setReading(null);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-50 flex items-center justify-center bg-void/90 backdrop-blur-md"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.94, y: 12 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.94, y: 12 }}
        onClick={(e) => e.stopPropagation()}
        className="vn-panel flex max-h-[88vh] w-full max-w-2xl flex-col overflow-hidden"
      >
        {/* Header — terminal-style title bar */}
        <div className="flex items-center justify-between border-b border-blood/30 px-5 py-3">
          <div className="flex items-center gap-2">
            <Terminal size={15} className="text-blood-bright" />
            <span className="font-mono text-xs uppercase tracking-[0.35em] text-blood-bright">
              file_system
            </span>
          </div>
          <button
            onClick={onClose}
            className="text-muted transition-colors hover:text-bone"
            aria-label="Close"
          >
            <X size={18} />
          </button>
        </div>

        {/* Breadcrumb path bar */}
        <div className="flex items-center gap-2 border-b border-ash/40 px-5 py-2 font-mono text-[10px] uppercase tracking-[0.2em] text-muted">
          {openFolder !== ROOT && (
            <button
              onClick={() => {
                audio.playSFX('click');
                setOpenFolder(ROOT);
                setReading(null);
              }}
              className="flex items-center gap-1 text-muted hover:text-bone"
            >
              <ArrowLeft size={11} /> root
            </button>
          )}
          <span className={openFolder === ROOT ? 'text-bone' : 'text-muted/50'}>
            {openFolder === ROOT ? '/' : '/'}
          </span>
          {openFolder !== ROOT && (
            <span className="text-bone">{currentFolderName}</span>
          )}
          <span className="ml-auto text-muted/40">
            {deletedFiles.length > 0
              ? `${deletedFiles.length} deleted`
              : 'read · delete · do not edit'}
          </span>
        </div>

        {/* Body — two-pane: file list (left) + content viewer (right) */}
        <div className="flex min-h-0 flex-1 flex-col md:flex-row">
          {/* File list */}
          <div
            className={[
              'md:w-1/2 md:border-r md:border-ash/40',
              reading ? 'hidden md:block' : 'block',
            ].join(' ')}
          >
            <div className="max-h-[40vh] overflow-y-auto px-3 py-2 md:max-h-[60vh]">
              {entries.length === 0 && (
                <p className="px-2 py-6 text-center font-mono text-[10px] uppercase tracking-[0.2em] text-muted/50">
                  [ empty ]
                </p>
              )}
              {entries.map((file, i) => {
                const isDeleted = deletedFiles.includes(file.id);
                const isFolder = file.kind === 'folder';
                const Icon = isFolder
                  ? Folder
                  : file.name.endsWith('.chr')
                  ? FileIcon
                  : FileText;
                const isProtected = !isFolder && file.protected;
                const isConfirming = confirmId === file.id;
                return (
                  <motion.div
                    key={file.id}
                    initial={{ opacity: 0, x: -8 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: i * 0.03, duration: 0.25 }}
                    className={[
                      'group flex items-center gap-2.5 border-l-2 px-2.5 py-2 transition-colors',
                      isDeleted
                        ? 'border-blood-bright/30 opacity-45'
                        : reading?.id === file.id
                        ? 'border-blood-bright bg-blood/5'
                        : 'border-transparent hover:border-blood/40 hover:bg-ash/20',
                    ].join(' ')}
                  >
                    <button
                      onClick={() => handleEntryClick(file)}
                      className="flex flex-1 items-center gap-2.5 text-left"
                    >
                      <Icon
                        size={14}
                        className={[
                          'shrink-0',
                          isFolder
                            ? 'text-blood-bright/80'
                            : isDeleted
                            ? 'text-muted/40'
                            : 'text-bone/70',
                        ].join(' ')}
                      />
                      <span className="flex flex-col leading-tight">
                        <span
                          className={[
                            'font-mono text-xs tracking-wide',
                            isDeleted
                              ? 'text-muted/50 line-through'
                              : 'text-bone',
                          ].join(' ')}
                        >
                          {file.name}
                          {isDeleted && ' [deleted]'}
                        </span>
                        {file.note && !isDeleted && (
                          <span className="font-mono text-[8px] uppercase tracking-[0.15em] text-muted/60">
                            {file.note}
                          </span>
                        )}
                      </span>
                    </button>
                    {/* Protected lock indicator */}
                    {isProtected && (
                      <Lock
                        size={10}
                        className="shrink-0 text-muted/40"
                        aria-label="protected"
                      />
                    )}
                    {/* Delete action — small, deliberately uncomfortable.
                        Two-click inline confirmation like the Cast panel. */}
                    {!isFolder && !isDeleted && !isConfirming && (
                      <button
                        onClick={() => setConfirmId(file.id)}
                        className={[
                          'shrink-0 transition-colors',
                          file.protected
                            ? 'text-muted/30 hover:text-muted/60'
                            : 'text-muted/30 hover:text-blood-bright',
                        ].join(' ')}
                        aria-label={`Delete ${file.name}`}
                      >
                        <FileX2 size={12} />
                      </button>
                    )}
                    <AnimatePresence>
                      {isConfirming && (
                        <motion.div
                          initial={{ opacity: 0, width: 0 }}
                          animate={{ opacity: 1, width: 'auto' }}
                          exit={{ opacity: 0, width: 0 }}
                          className="flex shrink-0 items-center gap-1.5 border border-blood/40 bg-blood/10 px-2 py-1"
                        >
                          <AlertTriangle
                            size={9}
                            className="text-blood-bright animate-pulse"
                          />
                          <button
                            onClick={() => setConfirmId(null)}
                            className="font-mono text-[8px] uppercase tracking-wider text-muted hover:text-bone"
                          >
                            no
                          </button>
                          <button
                            onClick={() => handleDelete(file)}
                            className="font-mono text-[8px] uppercase tracking-wider text-blood-bright hover:text-white"
                          >
                            erase
                          </button>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </motion.div>
                );
              })}
            </div>
          </div>

          {/* Content viewer */}
          <div
            className={[
              'min-w-0 flex-1 md:w-1/2',
              reading ? 'block' : 'hidden md:block',
            ].join(' ')}
          >
            {reading ? (
              <FileContentViewer
                file={reading}
                isDeleted={deletedFiles.includes(reading.id)}
                onBack={() => setReading(null)}
              />
            ) : (
              <div className="flex h-full items-center justify-center px-6 py-10 text-center">
                <div>
                  <FileText
                    size={22}
                    className="mx-auto mb-3 text-muted/30"
                  />
                  <p className="font-mono text-[10px] uppercase tracking-[0.25em] text-muted/50">
                    select a file to read
                  </p>
                  <p className="mt-2 font-serif text-[11px] italic text-muted/40">
                    the file system does not lie. it only omits.
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Reaction footer — the game's response to a deletion attempt.
            Surfaces the red system whisper from onDelete.reaction. */}
        <AnimatePresence>
          {reaction && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="border-t border-blood/40 bg-blood/5 px-5 py-2.5"
            >
              <p className="font-mono text-[10px] uppercase tracking-[0.18em] leading-relaxed text-blood-bright/85 fx-dread">
                {reaction}
              </p>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Footer hint */}
        <p className="border-t border-ash/40 px-5 py-2 text-center font-mono text-[9px] uppercase tracking-[0.3em] text-muted/40">
          you may read · you may delete · you may not edit
        </p>
      </motion.div>
    </motion.div>
  );
}

// --- Content viewer --------------------------------------------------------
// Renders a single file's content in a terminal-style read pane. Deleted
// files show a [file deleted] placeholder instead of content — the text is
// gone, but the file's absence is itself information.
function FileContentViewer({
  file,
  isDeleted,
  onBack,
}: {
  file: VFile;
  isDeleted: boolean;
  onBack: () => void;
}) {
  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center gap-2 border-b border-ash/40 px-4 py-2">
        <button
          onClick={onBack}
          className="flex items-center gap-1 font-mono text-[9px] uppercase tracking-[0.2em] text-muted hover:text-bone md:hidden"
        >
          <ArrowLeft size={11} /> back
        </button>
        <FileText size={12} className="text-blood-bright/70" />
        <span className="font-mono text-[10px] uppercase tracking-[0.2em] text-bone">
          {file.name}
        </span>
        {file.protected && (
          <span className="ml-auto flex items-center gap-1 font-mono text-[8px] uppercase tracking-[0.2em] text-muted/50">
            <Lock size={9} /> protected
          </span>
        )}
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto px-5 py-4">
        {isDeleted ? (
          <div className="flex h-full items-center justify-center text-center">
            <div>
              <FileX2
                size={20}
                className="mx-auto mb-3 text-blood-bright/50"
              />
              <p className="font-mono text-[10px] uppercase tracking-[0.25em] text-blood-bright/70">
                [ file deleted ]
              </p>
              <p className="mt-2 font-serif text-[11px] italic text-muted/50">
                the content is gone. what you read here is the shape of its absence.
              </p>
            </div>
          </div>
        ) : (
          <pre className="whitespace-pre-wrap font-serif text-sm italic leading-relaxed text-bone/80">
            {file.content}
          </pre>
        )}
      </div>
    </div>
  );
}
