// Keep Out story-locks — applied to Chapter Select. Certain chapters can
// only be entered if the player has met a condition (a clue from a prior
// loop, or a minimum loop count). This gates spoiler-heavy chapters behind
// progression without removing them from the menu entirely.
export interface ChapterLock {
  sceneId: string;
  // Condition: any of these must be true to unlock. Empty = always unlocked.
  requiresClue?: string;
  requiresLoopCount?: number;
  // The flavour text shown on the locked chapter card.
  lockText: string;
}

// Day 7 (The Truth) is locked behind having seen at least one clue from the
// corridor/feast/mirror/clock set — the player must have gathered at least
// one piece of the truth before the chapter-select lets them rehearse it.
// This avoids the spoiler of jumping straight to the reveal on a first
// playthrough.
export const CHAPTER_LOCKS: ChapterLock[] = [
  {
    sceneId: 'd7_intro',
    requiresClue: 'clue_corridor',
    lockText: 'Keep Out — the truth waits for a reader.',
  },
];

export function getChapterLock(sceneId: string): ChapterLock | null {
  return CHAPTER_LOCKS.find((l) => l.sceneId === sceneId) ?? null;
}

// Is the given chapter currently locked for the player? Takes the player's
// inventory + loop count and returns true if the lock is not yet satisfied.
export function isChapterLocked(
  sceneId: string,
  inventory: string[],
  loopCount: number,
): boolean {
  const lock = getChapterLock(sceneId);
  if (!lock) return false;
  if (lock.requiresClue && !inventory.includes(lock.requiresClue)) return true;
  if (lock.requiresLoopCount && loopCount < lock.requiresLoopCount) return true;
  return false;
}
