import { useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useGame } from '@/engine/store';

// Idle / AFK meta-awareness layer — inspired by DDLC's moments where the
// game acknowledges the player's absence ("Were you watching the whole
// time?"). When the player stops interacting during a dialogue scene, the
// game eventually speaks on its own — a soft, world-breaking whisper that
// implies the Game Space is aware of being watched.
//
// Two escalating tiers, both purely cosmetic (no mechanical effect):
//   60s idle  — a faint whisper at the screen edge: "The game is waiting."
//  120s idle  — a second line, more direct: "You haven't moved. They have."
// Any input (pointer, key, click) immediately resets the timer and hides
// the overlay.
//
// Only triggers on the dialogue screen — idle on the title or settings
// screen is normal (the player is away), and we don't want to nag.

const TIER_ONE_MS = 60_000;
const TIER_TWO_MS = 120_000;
const POLL_MS = 5_000;

const TIER_ONE_LINES = [
  'The game is waiting. It can wait.',
  'You have not pressed a key. The rules have not changed.',
  'Somewhere, a clock ticks. You are not the one keeping time.',
];

const TIER_TWO_LINES = [
  'You haven\'t moved. They are still watching you.',
  'Idleness is also a choice. The game records it.',
  'The screen has not gone dark. It is waiting for you to look away.',
];

function pickStable<T>(arr: T[], seed: number): T {
  // Stable pick so the line doesn't reshuffle every poll while the player
  // stays idle — the same line should persist for the whole idle window.
  return arr[seed % arr.length];
}

export default function IdleWatcher() {
  const screen = useGame((s) => s.screen);
  const [tier, setTier] = useState(0);
  const lastInputRef = useRef<number>(Date.now());
  // Pick a stable line per idle "session" so it doesn't flicker between
  // polls. Refreshed when the player goes fully idle again.
  const seedRef = useRef<number>(Math.floor(Math.random() * 99));

  // Reset the idle timer on any input. We attach to window so it covers
  // pointer moves, clicks, and key presses globally — even if the player
  // isn't focused on the dialogue box itself.
  useEffect(() => {
    const onActivity = () => {
      lastInputRef.current = Date.now();
      setTier(0);
    };
    window.addEventListener('pointerdown', onActivity);
    window.addEventListener('pointermove', onActivity);
    window.addEventListener('keydown', onActivity);
    return () => {
      window.removeEventListener('pointerdown', onActivity);
      window.removeEventListener('pointermove', onActivity);
      window.removeEventListener('keydown', onActivity);
    };
  }, []);

  // Poll the idle duration. Only escalate when the player is actively on
  // the dialogue screen — anywhere else, idleness is fine.
  useEffect(() => {
    if (screen !== 'dialogue') {
      setTier(0);
      return;
    }
    const interval = window.setInterval(() => {
      const idle = Date.now() - lastInputRef.current;
      if (idle >= TIER_TWO_MS) {
        setTier(2);
      } else if (idle >= TIER_ONE_MS) {
        setTier(1);
      } else {
        setTier(0);
      }
    }, POLL_MS);
    return () => window.clearInterval(interval);
  }, [screen]);

  // When the tier drops back to 0 (player resumed), pick a fresh seed so
  // the next idle session uses a different line.
  useEffect(() => {
    if (tier === 0) {
      seedRef.current = Math.floor(Math.random() * 99);
    }
  }, [tier]);

  const line =
    tier === 1
      ? pickStable(TIER_ONE_LINES, seedRef.current)
      : tier === 2
        ? pickStable(TIER_TWO_LINES, seedRef.current)
        : '';

  return (
    <AnimatePresence>
      {tier > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 12 }}
          transition={{ duration: 1.2, ease: 'easeOut' }}
          className="pointer-events-none fixed bottom-4 left-1/2 z-40 max-w-md -translate-x-1/2 px-6 text-center md:bottom-8"
          aria-hidden
        >
          <motion.p
            key={`idle-tier-${tier}`}
            initial={{ opacity: 0 }}
            animate={{ opacity: tier === 2 ? 0.85 : 0.55 }}
            transition={{ duration: 1.4 }}
            className={[
              'font-serif text-sm italic',
              tier === 2 ? 'text-blood-bright/80' : 'text-muted',
            ].join(' ')}
            style={{
              textShadow:
                tier === 2
                  ? '0 0 8px rgba(200,30,30,0.35)'
                  : '0 0 4px rgba(232,232,232,0.15)',
            }}
          >
            {line}
          </motion.p>
          {tier === 2 && (
            <motion.span
              initial={{ opacity: 0 }}
              animate={{ opacity: [0.4, 0.9, 0.4] }}
              transition={{ duration: 2.4, repeat: Infinity }}
              className="mt-1 block font-mono text-[9px] uppercase tracking-[0.4em] text-blood-bright/50"
            >
              ◊ input expected ◊
            </motion.span>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}
