import { useEffect, useRef, useState } from 'react';

// Typewriter hook: reveals text char-by-char. Clicking "advance" while still
// typing completes the line instantly (classic VN behaviour).
// Optional onTick fires whenever a new character is revealed (skipping
// whitespace), so the caller can layer a soft typing SFX without polling.
export function useTypewriter(
  text: string,
  speedMs: number,
  onTick?: (char: string) => void,
) {
  const [shown, setShown] = useState('');
  const [done, setDone] = useState(false);
  const idxRef = useRef(0);
  const timerRef = useRef<number | null>(null);
  // Keep the latest onTick in a ref so the interval closure stays stable
  // and we don't reset the typewriter whenever the caller's callback identity
  // changes (which would restart the letter reveal on every render).
  const onTickRef = useRef(onTick);
  onTickRef.current = onTick;

  useEffect(() => {
    // Reset when text changes
    setShown('');
    setDone(false);
    idxRef.current = 0;

    if (!text) {
      setDone(true);
      return;
    }

    const tick = () => {
      idxRef.current += 1;
      const nextChar = text[idxRef.current - 1];
      setShown(text.slice(0, idxRef.current));
      // Fire the tick callback for non-whitespace characters so the caller
      // can play a soft typing sound without it hissing on spaces.
      if (onTickRef.current && nextChar && nextChar.trim()) {
        onTickRef.current(nextChar);
      }
      if (idxRef.current >= text.length) {
        setDone(true);
        if (timerRef.current) {
          window.clearInterval(timerRef.current);
          timerRef.current = null;
        }
      }
    };

    timerRef.current = window.setInterval(tick, speedMs);
    return () => {
      if (timerRef.current) {
        window.clearInterval(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [text, speedMs]);

  const complete = () => {
    if (timerRef.current) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setShown(text);
    setDone(true);
    idxRef.current = text.length;
  };

  return { shown, done, complete };
}
