import { useState } from 'react';
import { motion } from 'framer-motion';
import { useGame } from '@/engine/store';
import { audio } from '@/engine/audioEngine';
import { ArrowLeft, Volume2, VolumeX, Gauge, Maximize } from 'lucide-react';

export default function SettingsPanel() {
  const setScreen = useGame((s) => s.setScreen);
  const settings = useGame((s) => s.settings);
  const updateSettings = useGame((s) => s.updateSettings);
  const [muted, setMuted] = useState(audio.isMuted());

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="absolute inset-0 z-40 flex flex-col bg-void"
    >
      <header className="flex items-center justify-between border-b border-ash px-6 py-4">
        <button
          onClick={() => setScreen('title')}
          className="flex items-center gap-2 font-mono text-xs uppercase tracking-widest text-muted hover:text-bone transition-colors"
        >
          <ArrowLeft size={14} /> Back
        </button>
        <h2 className="font-mono text-xs uppercase tracking-[0.4em] text-blood-bright">
          Settings
        </h2>
        <span className="w-12" />
      </header>

      <div className="flex-1 overflow-y-auto p-6">
        <div className="mx-auto max-w-lg space-y-8">
          {/* Text speed */}
          <SettingRow icon={<Gauge size={14} />} label="Text Speed">
            <div className="flex items-center gap-3">
              <span className="font-mono text-[10px] uppercase text-muted">Slow</span>
              <input
                type="range"
                min={5}
                max={80}
                value={85 - settings.textSpeed}
                onChange={(e) =>
                  updateSettings({ textSpeed: 85 - Number(e.target.value) })
                }
                className="flex-1 accent-blood-bright"
              />
              <span className="font-mono text-[10px] uppercase text-muted">Fast</span>
            </div>
          </SettingRow>

          {/* BGM volume */}
          <SettingRow icon={<Volume2 size={14} />} label="Music Volume">
            <input
              type="range"
              min={0}
              max={100}
              value={Math.round(settings.bgmVolume * 100)}
              onChange={(e) =>
                updateSettings({ bgmVolume: Number(e.target.value) / 100 })
              }
              className="w-full accent-blood-bright"
            />
          </SettingRow>

          {/* SFX volume */}
          <SettingRow icon={<VolumeX size={14} />} label="Sound Effects">
            <input
              type="range"
              min={0}
              max={100}
              value={Math.round(settings.sfxVolume * 100)}
              onChange={(e) =>
                updateSettings({ sfxVolume: Number(e.target.value) / 100 })
              }
              className="w-full accent-blood-bright"
            />
          </SettingRow>

          {/* Master mute — silent by default in dev, toggle here to test audio */}
          <SettingRow icon={<VolumeX size={14} />} label="Master Audio">
            <button
              onClick={() => {
                const next = !muted;
                audio.setMuted(next);
                setMuted(next);
              }}
              className={[
                'vn-choice px-5 py-2 font-mono text-[10px] uppercase tracking-widest hover:text-white',
                muted ? 'text-muted' : 'text-bone',
              ].join(' ')}
            >
              {muted ? 'Muted (tap to enable)' : 'On (tap to mute)'}
            </button>
            {import.meta.env?.DEV && (
              <p className="mt-2 font-mono text-[9px] uppercase tracking-wider text-muted/60">
                Dev mode: audio is muted by default while debugging.
              </p>
            )}
          </SettingRow>

          {/* Fullscreen */}
          <SettingRow icon={<Maximize size={14} />} label="Fullscreen">
            <button
              onClick={() => {
                if (!document.fullscreenElement) {
                  document.documentElement.requestFullscreen?.().catch(() => {});
                } else {
                  document.exitFullscreen?.().catch(() => {});
                }
              }}
              className="vn-choice px-5 py-2 font-mono text-[10px] uppercase tracking-widest text-bone hover:text-white"
            >
              Toggle Fullscreen
            </button>
          </SettingRow>

          <div className="border-t border-ash pt-6">
            <p className="font-serif text-xs italic text-muted">
              Beyond the Rules — a browser-native rule-horror visual novel.
              <br />
              Built with React, Vite &amp; TailwindCSS. Open-source, lightweight, no
              install.
            </p>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

function SettingRow({
  icon,
  label,
  children,
}: {
  icon: React.ReactNode;
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <div className="mb-3 flex items-center gap-2">
        <span className="text-blood-bright">{icon}</span>
        <span className="font-mono text-xs uppercase tracking-widest text-bone">
          {label}
        </span>
      </div>
      {children}
    </div>
  );
}
