import type { CSSProperties } from 'react';

// Aceternity-inspired Border Beam: 沿元素边框循环移动的光束。
// 参考来源: https://ui.aceternity.com/components/border-beam
//
// 适配本项目：用 blood-bright (#c81e1e) → bone (#e8e8e8) 渐变光束，
// 沿对话面板/选择卡片边框循环扫描，强化"游戏在审视你"的注视感。
// 实现思路: 用 conic-gradient + CSS mask 让光束只显示在边框 1px 区域，
// 通过 @keyframes 旋转 conic-gradient 的起始角度实现"光束沿边框移动"。

interface Props {
  /** 光束颜色（默认 blood-bright → bone 渐变） */
  colorFrom?: string;
  colorTo?: string;
  /** 光束宽度（默认 1.5px，对应边框宽度） */
  size?: number;
  /** 旋转周期（秒，默认 6s） */
  duration?: number;
  /** 是否启用（默认 true，可在某些状态下关闭） */
  active?: boolean;
  className?: string;
  style?: CSSProperties;
}

export default function BorderBeam({
  colorFrom = '#c81e1e',
  colorTo = '#e8e8e8',
  size = 1.5,
  duration = 6,
  active = true,
  className = '',
  style,
}: Props) {
  if (!active) return null;

  return (
    <div
      aria-hidden
      className={`pointer-events-none absolute inset-0 rounded-[inherit] ${className}`}
      style={{
        // 用 padding + mask 把 conic-gradient 限制在边框宽度内，
        // 实现真正的"光束沿边框线移动"，而不是矩形整体旋转。
        padding: `${size}px`,
        background: `conic-gradient(from 0deg, transparent 0deg, ${colorFrom} 30deg, ${colorTo} 60deg, transparent 90deg, transparent 360deg)`,
        WebkitMask: `
          linear-gradient(#000 0 0) content-box,
          linear-gradient(#000 0 0)
        `,
        WebkitMaskComposite: 'xor',
        maskComposite: 'exclude',
        animation: `borderBeamSpin ${duration}s linear infinite`,
        ...style,
      }}
    />
  );
}
