import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useGame } from '@/engine/store';
import { ENDINGS } from '@/data/characters';
import { getBackground } from '@/lib/assets';
import SceneFX from './effects/SceneFX';
import ShinyText from './effects/ShinyText';
import { BAD_END_DOJOS } from '@/data/dojo';
import DojoOverlay from './DojoOverlay';
import { RotateCcw, Home, ScrollText } from 'lucide-react';

export default function EndingScreen() {
  const endingId = useGame((s) => s.endingId);
  const loopBack = useGame((s) => s.loopBack);
  const goToTitle = useGame((s) => s.goToTitle);
  const loopCount = useGame((s) => s.loopCount);
  const flags = useGame((s) => s.flags);
  const seenDojos = useGame((s) => s.seenDojos);
  const recordDojo = useGame((s) => s.recordDojo);

  // Tiger Dojo: after a Bad End, the Game Master returns to correct the rule
  // you misread. We auto-surface the Dojo overlay a few seconds after the
  // ending text settles (only if the player hasn't already seen this lesson
  // — re-watching is opt-in via the "View Correction" button). This is the
  // Fate/stay night Tiger Dojo pattern, adapted so the rule itself is the
  // lesson: rule-horror makes the correction diegetic.
  const dojoEntry = endingId ? BAD_END_DOJOS[endingId] ?? null : null;
  const hasSeenThisDojo = dojoEntry ? seenDojos.includes(dojoEntry.id) : true;
  const [showDojo, setShowDojo] = useState(false);
  useEffect(() => {
    if (!dojoEntry || hasSeenThisDojo) return;
    const t = window.setTimeout(() => setShowDojo(true), 3500);
    return () => window.clearTimeout(t);
  }, [dojoEntry, hasSeenThisDojo]);

  const closeDojo = () => {
    if (dojoEntry) recordDojo(dojoEntry.id);
    setShowDojo(false);
  };

  const ending = endingId ? ENDINGS[endingId] : ENDINGS.perfect_survivor;
  const { img, gradient } = getBackground('ending');

  const isCollapse = endingId === 'collapse';
  const isSacrifice = endingId === 'sacrifice';
  const isTruth = endingId === 'truth_seeker' || endingId === 'game_master';
  const isGood = ending.isGood;
  // Salvation Mode: the ending resolver returns one of the four salvation_*
  // ids. The mode has no loop memory / clue carryover, so the classic-mode
  // "clues carry into the next loop" prompt is suppressed and the loop-again
  // button reads as "Begin Anew" rather than "Loop Again".
  const isSalvation = endingId?.startsWith('salvation_') ?? false;

  // Theory echo — if the player proposed a suspect theory on the Deduction
  // Board, the epilogue adds a single line that reflects their accusation.
  // This does not change the ending; it only acknowledges that the player
  // committed to a reading. The game does not confirm or deny — it merely
  // remembers what you believed.
  const theoryLine = flags.theory_linye
    ? 'You believed Lin Ye remembered. He never confirmed it. He never denied it either.'
    : flags.theory_baijing
    ? 'You believed Bai Jing served the game. She would have called it employment.'
    : flags.theory_self
    ? 'You believed you had been here before. The ending does not disagree.'
    : flags.theory_nobody
    ? 'You believed the game itself was the traitor. The closest reading. Also the safest.'
    : null;

  // Collapse & Sacrifice naturally loop; others return to title for a fresh loop.
  // Salvation Mode always offers a replay (the tally resets, no loop memory).
  const canLoop = isCollapse || isSacrifice || loopCount === 0 || isSalvation;

  // Mood-driven overlay: each ending gets its own visual signature.
  // - Good endings: warm rising glow
  // - Collapse: heavy glitch distortion
  // - Sacrifice: slow falling motes
  // - Default: cold steady fade
  return (
    <div
      className="relative h-full w-full overflow-hidden flex items-center justify-center"
      style={{ background: gradient }}
    >
      {img && (
        <img
          src={img}
          alt=""
          className="bg-ken-burns absolute inset-0 h-full w-full object-cover opacity-40"
          onError={(e) => {
            (e.currentTarget as HTMLImageElement).style.display = 'none';
          }}
        />
      )}

      {/* Ambient particles */}
      <SceneFX backgroundKey="ending" />

      {/* Mood-driven overlay: a soft radial wash tinted by the ending tone */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 2, delay: 0.5 }}
        className="pointer-events-none absolute inset-0"
        style={{
          background: isGood
            ? 'radial-gradient(ellipse at 50% 60%, rgba(200,200,220,0.15) 0%, transparent 60%)'
            : isCollapse
            ? 'radial-gradient(ellipse at 50% 50%, rgba(200,30,30,0.18) 0%, rgba(80,0,0,0.4) 100%)'
            : isSacrifice
            ? 'radial-gradient(ellipse at 50% 80%, rgba(139,0,0,0.15) 0%, transparent 70%)'
            : 'radial-gradient(ellipse at 50% 50%, rgba(60,60,80,0.1) 0%, transparent 60%)',
        }}
      />

      {/* Collapse-only glitch layer — full screen RGB split */}
      {isCollapse && (
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 animate-glitch-skew opacity-60"
          style={{
            background:
              'repeating-linear-gradient(0deg, transparent 0px, transparent 2px, rgba(200,30,30,0.08) 3px, transparent 4px)',
          }}
        />
      )}

      <div className="relative z-10 max-w-2xl px-8 text-center">
        <motion.p
          initial={{ opacity: 0, letterSpacing: '0.2em' }}
          animate={{ opacity: 1, letterSpacing: '0.6em' }}
          transition={{ duration: 1.4 }}
          className="mb-3 font-mono text-[10px] uppercase tracking-[0.6em] text-blood-bright"
        >
          ◊ Ending ◊
        </motion.p>

        <motion.h1
          initial={{ opacity: 0, y: 12, filter: 'blur(8px)' }}
          animate={{ opacity: 1, y: 0, filter: 'blur(0)' }}
          transition={{ duration: 1.4, delay: 0.5, ease: 'easeOut' }}
          className={[
            'font-serif text-3xl font-semibold leading-tight md:text-5xl',
            isGood ? 'text-bone' : 'text-blood-bright',
            isCollapse ? 'animate-glitch-skew' : '',
          ].join(' ')}
          style={
            isGood
              ? { textShadow: '0 0 24px rgba(232,232,232,0.35)' }
              : { textShadow: '0 0 24px rgba(200,30,30,0.55)' }
          }
        >
          {/* ReactBits ShinyText: 结局标题表面有高光扫过，
              让"结局"读起来像被铭刻而非打印。仅对非 collapse 结局启用，
              collapse 的 glitch-skew 已足够强烈，叠加扫光会过载。 */}
          {!isCollapse ? (
            <ShinyText
              duration={5}
              shimmerColor={isGood ? 'rgba(255,250,240,0.95)' : 'rgba(255,180,160,0.85)'}
              baseColor={isGood ? '#e8e8e8' : '#c81e1e'}
            >
              {ending.title}
            </ShinyText>
          ) : (
            ending.title
          )}
        </motion.h1>

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.8, delay: 1.1 }}
          className="mt-2 font-mono text-xs uppercase tracking-[0.4em] text-muted"
        >
          {ending.tone}
        </motion.p>

        <motion.div
          initial={{ scaleX: 0 }}
          animate={{ scaleX: 1 }}
          transition={{ duration: 1, delay: 1.5 }}
          className="mx-auto mt-8 h-px w-24 bg-gradient-to-r from-transparent via-blood to-transparent"
        />

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 1.4, delay: 1.8 }}
          className="mt-8 whitespace-pre-line font-serif text-base italic leading-relaxed text-bone/85 md:text-lg"
        >
          {ending.epilogue}
        </motion.p>

        {/* Theory echo — a single quiet line that reflects the player's
            accusation, if they made one. Rendered after the epilogue so it
            reads as a footnote, not a verdict. */}
        {theoryLine && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 1, delay: 2.8 }}
            className="mt-4 font-serif text-sm italic text-blood-bright/70"
          >
            {theoryLine}
          </motion.p>
        )}

        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 2.6 }}
          className="mt-10 flex flex-col items-center justify-center gap-3 sm:flex-row"
        >
          {canLoop && (
            <motion.button
              onClick={loopBack}
              whileHover={{ scale: 1.04 }}
              whileTap={{ scale: 0.98 }}
              className="vn-choice vn-choice-rulebreak animate-hover-glow flex items-center gap-2 px-8 py-3 font-mono text-xs uppercase tracking-[0.3em] text-bone hover:text-white"
            >
              <RotateCcw size={14} /> {isSalvation ? 'Begin Anew' : 'Loop Again'}
            </motion.button>
          )}
          <motion.button
            onClick={goToTitle}
            whileHover={{ scale: 1.04 }}
            whileTap={{ scale: 0.98 }}
            className="vn-choice flex items-center gap-2 px-8 py-3 font-mono text-xs uppercase tracking-[0.3em] text-bone hover:text-white"
          >
            <Home size={14} /> Main Menu
          </motion.button>
        </motion.div>

        {/* Tiger Dojo: on a Bad End, surface a "View Correction" button so the
            player can re-watch the lesson after auto-dismissing it. The auto
            overlay only fires once per save; this button is the opt-in path. */}
        {dojoEntry && (
          <motion.button
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 3.2, duration: 0.8 }}
            onClick={() => setShowDojo(true)}
            className="mt-4 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[0.3em] text-muted hover:text-blood-bright transition-colors"
          >
            <ScrollText size={12} />
            {hasSeenThisDojo ? 'Revisit Rule Correction' : 'View Rule Correction'}
          </motion.button>
        )}

        {canLoop && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8, delay: 3.2 }}
            className="mt-6 font-serif text-xs italic text-muted animate-pulse-slow"
          >
            {isSalvation
              ? 'The tally is closed. The contract can be rewritten.'
              : 'The clues you gathered will carry into the next loop. The truth is closer than you think.'}
          </motion.p>
        )}

        {/* Truth-ending stinger: a single pulse of red light to seal the reveal */}
        {isTruth && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: [0, 0.7, 0] }}
            transition={{ duration: 2, delay: 1.5, times: [0, 0.3, 1] }}
            className="pointer-events-none fixed inset-0 z-20"
            style={{
              background:
                'radial-gradient(ellipse at 50% 50%, rgba(200,30,30,0.4) 0%, transparent 70%)',
            }}
          />
        )}
      </div>

      {/* Tiger Dojo overlay — auto-surfaces a few seconds after a Bad End
          settles, dismissable via Esc or the "Understood" button. Re-openable
          via the "View Correction" button above. The Game Master returns to
          correct the rule you misread. */}
      <AnimatePresence>
        {showDojo && dojoEntry && (
          <DojoOverlay key="dojo" entry={dojoEntry} onClose={closeDojo} />
        )}
      </AnimatePresence>
    </div>
  );
}
