import { useMemo } from 'react';

// Aceternity-inspired Aurora Background: 缓慢漂移的彩色极光雾团。
// 参考来源: https://ui.aceternity.com/components/aurora-background
//
// 适配本项目黑红恐怖风：极光团改为 blood-red / deep-violet / void-blue
// 三色低饱和雾团，blur 极重，opacity 极低，作为 TitleScreen 底层氛围层。
// 仅用 CSS 动画 + GPU transform，无 rAF 循环，prefers-reduced-motion 时停止。

interface Props {
  /** 是否启用旋转动画（默认 true） */
  rotate?: boolean;
  /** 自定义 className（用于定位/层级） */
  className?: string;
}

// 三色极光雾团。颜色取自 tailwind.config.js 的 void/blood/bone 调色板，
// 通过极重的 blur + 低 opacity 形成柔和的极光氛围，而非生硬的彩色色块。
const AURORA_BLOBS = [
  {
    color: 'rgba(139, 0, 0, 0.45)', // blood
    size: '60vw',
    top: '-10%',
    left: '-10%',
    duration: '22s',
  },
  {
    color: 'rgba(80, 0, 30, 0.35)', // deep violet
    size: '50vw',
    top: '40%',
    left: '50%',
    duration: '28s',
  },
  {
    color: 'rgba(30, 30, 80, 0.28)', // void-blue
    size: '55vw',
    top: '20%',
    left: '20%',
    duration: '32s',
  },
  {
    color: 'rgba(200, 30, 30, 0.22)', // blood-bright
    size: '40vw',
    top: '60%',
    left: '-5%',
    duration: '26s',
  },
];

export default function AuroraBackground({ rotate = true, className = '' }: Props) {
  // 用 useMemo 锁定 blob 配置，避免 re-render 时重排。
  const blobs = useMemo(() => AURORA_BLOBS, []);

  return (
    <div
      aria-hidden
      className={`pointer-events-none absolute inset-0 overflow-hidden ${className}`}
    >
      {/* 底层暗色渐变，让极光雾团从黑底中浮现而非纯色背景 */}
      <div
        className="absolute inset-0"
        style={{
          background:
            'linear-gradient(180deg, #0a0a0f 0%, #0d0a14 50%, #0a0a0f 100%)',
        }}
      />
      {/* 极光雾团层 —— 用 CSS animation 缓慢漂移 + 缩放 */}
      <div
        className={rotate ? 'animate-aurora-rotate' : ''}
        style={{
          transformOrigin: 'center center',
          willChange: 'transform',
        }}
      >
        {blobs.map((b, i) => (
          <div
            key={i}
            className="absolute rounded-full animate-aurora-drift"
            style={{
              width: b.size,
              height: b.size,
              top: b.top,
              left: b.left,
              background: `radial-gradient(circle at 50% 50%, ${b.color} 0%, transparent 70%)`,
              filter: 'blur(60px)',
              mixBlendMode: 'screen',
              animationDuration: b.duration,
              animationDelay: `${i * -3}s`,
            }}
          />
        ))}
      </div>
      {/* 顶部 vignette —— 让极光在底部更明显，顶部保留暗黑 */}
      <div
        className="absolute inset-0"
        style={{
          background:
            'radial-gradient(ellipse at 50% 70%, transparent 0%, rgba(10,10,15,0.6) 70%, rgba(10,10,15,0.95) 100%)',
        }}
      />
    </div>
  );
}
