import { useMemo } from "react";

// Per-scene environmental particle / overlay effects.
// Each background key renders a unique ambient layer so locations feel
// visually distinct: dust in the white room, fog in the corridor, embers
// at the feast, gear silhouettes in the clock room, etc.
// All effects are pure CSS / SVG — GPU-cheap, no canvas, no rAF loop.

type Props = {
  backgroundKey?: string;
};

// Deterministic pseudo-random so particle layout is stable across re-renders.
function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function useParticles(count: number, seed: number) {
  return useMemo(() => {
    const rand = mulberry32(seed);
    return Array.from({ length: count }, () => ({
      left: `${Math.round(rand() * 100)}%`,
      top: `${Math.round(rand() * 100)}%`,
      delay: `${(rand() * 8).toFixed(2)}s`,
      duration: `${(8 + rand() * 10).toFixed(2)}s`,
      scale: `${(0.6 + rand() * 1.2).toFixed(2)}`,
      opacity: `${(0.3 + rand() * 0.5).toFixed(2)}`,
    }));
  }, [count, seed]);
}

export default function SceneFX({ backgroundKey }: Props) {
  // Stable seed per background so the layout doesn't reshuffle on every scene change.
  const seed = useMemo(() => {
    let h = 0;
    for (let i = 0; i < (backgroundKey ?? "").length; i++) {
      h = (h * 31 + backgroundKey!.charCodeAt(i)) | 0;
    }
    return Math.abs(h) || 7;
  }, [backgroundKey]);

  const dust = useParticles(18, seed);
  const embers = useParticles(14, seed + 1);
  const fog = useParticles(4, seed + 2);
  const shards = useParticles(6, seed + 3);
  const voidBlobs = useParticles(5, seed + 4);

  if (!backgroundKey) return null;

  return (
    <div aria-hidden className="pointer-events-none absolute inset-0 z-[5] overflow-hidden">
      {backgroundKey === "white_room" && (
        <>
          {/* Floating dust motes in sterile light */}
          {dust.map((p, i) => (
            <span
              key={i}
              className="absolute block h-[2px] w-[2px] rounded-full bg-bone/60 animate-dust-float"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: p.duration,
                opacity: p.opacity,
                transform: `scale(${p.scale})`,
                boxShadow: "0 0 4px rgba(232,232,232,0.4)",
              }}
            />
          ))}
          {/* Slow light flicker band */}
          <div
            className="absolute inset-x-0 top-0 h-1/3 animate-flicker"
            style={{
              background:
                "linear-gradient(180deg, rgba(255,255,255,0.06) 0%, transparent 100%)",
            }}
          />
        </>
      )}

      {backgroundKey === "corridor" && (
        <>
          {/* Drifting fog layers */}
          {fog.map((p, i) => (
            <div
              key={i}
              className="absolute h-[40vh] w-[80vw] animate-fog-drift"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: `${(20 + i * 4).toFixed(0)}s`,
                background:
                  "radial-gradient(ellipse at 50% 50%, rgba(120,120,140,0.12) 0%, transparent 70%)",
                filter: "blur(20px)",
              }}
            />
          ))}
          {/* Distant flickering lamp glow */}
          <div
            className="absolute left-1/2 top-1/3 h-32 w-32 -translate-x-1/2 animate-flicker"
            style={{
              background:
                "radial-gradient(circle, rgba(255,220,180,0.18) 0%, transparent 70%)",
              filter: "blur(8px)",
            }}
          />
        </>
      )}

      {backgroundKey === "feast" && (
        <>
          {/* Rising embers from below */}
          {embers.map((p, i) => (
            <span
              key={i}
              className="absolute bottom-0 block h-[3px] w-[3px] rounded-full animate-ember-rise"
              style={{
                left: p.left,
                animationDelay: p.delay,
                animationDuration: `${(5 + i * 0.6).toFixed(2)}s`,
                background:
                  "radial-gradient(circle, rgba(255,170,80,0.95) 0%, rgba(200,60,30,0.6) 60%, transparent 100%)",
                boxShadow: "0 0 8px rgba(255,140,40,0.7)",
              }}
            />
          ))}
          {/* Candlelight flicker band */}
          <div
            className="absolute inset-x-0 bottom-0 h-1/2 animate-flicker"
            style={{
              background:
                "linear-gradient(0deg, rgba(255,150,60,0.08) 0%, transparent 100%)",
            }}
          />
        </>
      )}

      {backgroundKey === "mirror" && (
        <>
          {/* Glass shimmer sweep */}
          <div
            className="absolute inset-0 animate-glass-shimmer"
            style={{
              background:
                "linear-gradient(115deg, transparent 30%, rgba(180,220,255,0.08) 45%, rgba(255,255,255,0.12) 50%, rgba(180,220,255,0.08) 55%, transparent 70%)",
            }}
          />
          {/* Occasional falling glass shards */}
          {shards.map((p, i) => (
            <span
              key={i}
              className="absolute top-0 block h-4 w-[1px] animate-ember-rise"
              style={{
                left: p.left,
                animationDelay: `${(i * 1.7).toFixed(2)}s`,
                animationDuration: `${(7 + i * 1.3).toFixed(2)}s`,
                background:
                  "linear-gradient(180deg, transparent 0%, rgba(200,230,255,0.6) 50%, transparent 100%)",
                transform: `rotate(${i * 17}deg)`,
              }}
            />
          ))}
        </>
      )}

      {backgroundKey === "clock" && (
        <>
          {/* Rotating gear silhouettes */}
          <svg
            className="absolute -right-32 -top-32 h-[60vh] w-[60vh] animate-gear-rotate opacity-[0.07]"
            viewBox="0 0 100 100"
          >
            <Gear />
          </svg>
          <svg
            className="absolute -bottom-40 -left-40 h-[70vh] w-[70vh] animate-gear-rotate-rev opacity-[0.05]"
            viewBox="0 0 100 100"
          >
            <Gear />
          </svg>
          {/* Ticking pulse ring at center */}
          <div
            className="absolute left-1/2 top-1/2 h-32 w-32 -translate-x-1/2 -translate-y-1/2 rounded-full border border-blood/30 animate-heartbeat"
            style={{ boxShadow: "0 0 30px rgba(139,0,0,0.2)" }}
          />
        </>
      )}

      {backgroundKey === "choice" && (
        <>
          {/* Sweeping spotlight beams */}
          <div
            className="absolute left-1/4 top-0 h-full w-24 origin-top animate-spotlight-sweep"
            style={{
              background:
                "linear-gradient(180deg, rgba(200,200,220,0.1) 0%, transparent 80%)",
              filter: "blur(12px)",
            }}
          />
          <div
            className="absolute right-1/4 top-0 h-full w-24 origin-top animate-spotlight-sweep"
            style={{
              animationDelay: "3s",
              background:
                "linear-gradient(180deg, rgba(200,200,220,0.08) 0%, transparent 80%)",
              filter: "blur(12px)",
            }}
          />
          {/* Dust particles in the light */}
          {dust.slice(0, 10).map((p, i) => (
            <span
              key={i}
              className="absolute block h-[2px] w-[2px] rounded-full bg-bone/40 animate-dust-float"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: p.duration,
                opacity: p.opacity,
              }}
            />
          ))}
        </>
      )}

      {backgroundKey === "truth" && (
        <>
          {/* Churning red void blobs */}
          {voidBlobs.map((p, i) => (
            <div
              key={i}
              className="absolute h-[40vh] w-[40vh] rounded-full animate-void-churn"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: `${(14 + i * 3).toFixed(0)}s`,
                background:
                  "radial-gradient(circle, rgba(200,30,30,0.18) 0%, rgba(139,0,0,0.08) 50%, transparent 80%)",
                filter: "blur(30px)",
              }}
            />
          ))}
          {/* CRT scanline distortion */}
          <div
            className="absolute inset-0 opacity-30"
            style={{
              backgroundImage:
                "repeating-linear-gradient(0deg, transparent 0px, transparent 2px, rgba(200,30,30,0.04) 3px, transparent 4px)",
            }}
          />
        </>
      )}

      {backgroundKey === "title" && (
        <>
          {/* Floating ember dust for the title screen */}
          {dust.slice(0, 12).map((p, i) => (
            <span
              key={i}
              className="absolute block h-[2px] w-[2px] rounded-full bg-blood-bright/70 animate-dust-float"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: p.duration,
                opacity: p.opacity,
                boxShadow: "0 0 6px rgba(200,30,30,0.5)",
              }}
            />
          ))}
        </>
      )}

      {backgroundKey === "ending" && (
        <>
          {/* Soft floating light motes */}
          {dust.slice(0, 8).map((p, i) => (
            <span
              key={i}
              className="absolute block h-[3px] w-[3px] rounded-full bg-bone/40 animate-dust-float"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: `${(14 + i).toFixed(0)}s`,
                opacity: p.opacity,
              }}
            />
          ))}
        </>
      )}

      {backgroundKey === "void" && (
        <>
          {/* A single distant pulsing point of red light — the only feature
              in an otherwise empty darkness. */}
          <div
            className="absolute left-1/2 top-1/2 h-2 w-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-blood-bright animate-pulse-slow"
            style={{ boxShadow: "0 0 24px 8px rgba(200,30,30,0.5)" }}
          />
          {/* Rare drifting motes, sparser than other scenes */}
          {dust.slice(0, 5).map((p, i) => (
            <span
              key={i}
              className="absolute block h-[1px] w-[1px] rounded-full bg-blood-bright/50 animate-dust-float"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: `${(20 + i * 2).toFixed(0)}s`,
                opacity: p.opacity,
              }}
            />
          ))}
        </>
      )}

      {backgroundKey === "loop_transition" && (
        <>
          {/* Swirling distortion rings — reality folding in on itself */}
          {voidBlobs.map((p, i) => (
            <div
              key={i}
              className="absolute h-[50vh] w-[50vh] rounded-full animate-void-churn"
              style={{
                left: p.left,
                top: p.top,
                animationDelay: p.delay,
                animationDuration: `${(10 + i * 2).toFixed(0)}s`,
                background:
                  "radial-gradient(circle, rgba(139,0,0,0.22) 0%, rgba(60,0,0,0.1) 50%, transparent 80%)",
                filter: "blur(20px)",
              }}
            />
          ))}
          {/* Cracked glass shards falling — the mirror of reality breaking */}
          {shards.map((p, i) => (
            <span
              key={i}
              className="absolute top-0 block h-6 w-[1px] animate-ember-rise"
              style={{
                left: p.left,
                animationDelay: `${(i * 0.9).toFixed(2)}s`,
                animationDuration: `${(5 + i * 0.8).toFixed(2)}s`,
                background:
                  "linear-gradient(180deg, transparent 0%, rgba(200,30,30,0.7) 50%, transparent 100%)",
                transform: `rotate(${i * 23}deg)`,
              }}
            />
          ))}
          {/* Heavy glitch scanlines — the world is being rewritten */}
          <div
            className="absolute inset-0 opacity-40 animate-flicker"
            style={{
              backgroundImage:
                "repeating-linear-gradient(0deg, transparent 0px, transparent 3px, rgba(200,30,30,0.06) 4px, transparent 5px)",
            }}
          />
        </>
      )}
    </div>
  );
}

// A 12-tooth gear silhouette, used as a background motif in the clock room.
function Gear() {
  const teeth = 12;
  const path = Array.from({ length: teeth * 2 })
    .map((_, i) => {
      const angle = (i / (teeth * 2)) * Math.PI * 2;
      const r = i % 2 === 0 ? 42 : 36;
      const x = 50 + Math.cos(angle) * r;
      const y = 50 + Math.sin(angle) * r;
      return `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`;
    })
    .join(" ");
  return (
    <>
      <path d={`${path} Z`} fill="#8b0000" />
      <circle cx="50" cy="50" r="14" fill="#0a0a0f" />
      <circle cx="50" cy="50" r="6" fill="#8b0000" />
    </>
  );
}
