import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { audio } from '@/engine/audioEngine';
import { useGame } from '@/engine/store';
import { CHARACTERS } from '@/data/characters';
import { Users, X, FileX2, AlertTriangle } from 'lucide-react';

// Character profile panel: shows each character's name, role, description,
// and current trust level. The descriptions already exist in characters.ts
// but were never surfaced to the player — this panel makes them visible,
// turning the cast from name-coloured labels into people with histories.
// Opened from the in-game menu, same overlay pattern as DeductionBoard.
//
// DDLC-inspired destruction: each NPC profile has a "destroy file" action.
// Destroying a profile triggers the FakeCrashOverlay — the game "crashes,"
// then recovers with the file restored, but the Game Master acknowledges
// the attempt. The destruction is logged but reversible; it is a narrative
// beat, not a permanent deletion.

// NPCs that have a trust meter (excludes narrator/system/you).
const TRUST_NPCS = ['linye', 'suwan', 'chenmo', 'xiaohe', 'laozhou', 'baijing'];

// Characters whose profiles can be destroyed (the playable cast, not the
// narrator or the protagonist — you cannot delete yourself, and the narrator
// has no file to corrupt).
const DESTRUCTIBLE = ['linye', 'suwan', 'chenmo', 'xiaohe', 'laozhou', 'baijing'];

interface Props {
  onClose: () => void;
  onDestroy?: (profileId: string) => void; // triggers FakeCrashOverlay in parent
}

export default function CharacterProfilePanel({ onClose, onDestroy }: Props) {
  const trust = useGame((s) => s.trust);
  const inventory = useGame((s) => s.inventory);
  const destroyedProfiles = useGame((s) => s.destroyedProfiles);
  // DDLC-inspired: characters the player once destroyed and then restored
  // "remember" the attempt. Surfaced as a quiet disturbed note on their
  // profile — they know what you tried to do.
  const rememberedDestruction = useGame((s) => s.rememberedDestruction);
  const destroyProfile = useGame((s) => s.destroyProfile);
  const [confirmId, setConfirmId] = useState<string | null>(null);

  // Some character descriptions unlock progressively — e.g. you only learn
  // someone's true nature after finding certain clues. This keeps the panel
  // from spoiling reveals on a first playthrough.
  function getDescription(id: string, baseDesc: string): string {
    switch (id) {
      case 'chenmo':
        // His antagonist role is obvious from the start, but the depth of
        // his self-preservation only surfaces after the feast scene.
        return inventory.includes('clue_feast')
          ? baseDesc + ' You have seen what he does when the plates are empty.'
          : baseDesc;
      case 'baijing':
        // Her allegiance is meant to be ambiguous; only reveal the second
        // sentence after the mirror clue (which exposes duality).
        return inventory.includes('clue_mirror')
          ? baseDesc + ' The mirror showed two faces. Both were hers.'
          : baseDesc.split('.')[0] + '.';
      case 'linye':
        // Lin Ye "knows more than he lets on" — after the first loop the
        // player starts to suspect he remembers too. Surface that.
        return useGame.getState().loopCount > 0
          ? baseDesc + ' He remembers. You are certain now.'
          : baseDesc;
      case 'system':
        // The Game Master's true nature is the core mystery.
        return inventory.includes('clue_truth')
          ? baseDesc + ' A player, once. Like you.'
          : baseDesc;
      default:
        return baseDesc;
    }
  }

  // Cast list in a deliberate order: protagonist first, then allies, then
  // ambiguous figures, then the Game Master last for dramatic closure.
  const ORDER = ['you', 'linye', 'suwan', 'xiaohe', 'laozhou', 'chenmo', 'baijing', 'system'];

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-50 flex items-center justify-center bg-void/90 backdrop-blur-md"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.94, y: 12 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.94, y: 12 }}
        onClick={(e) => e.stopPropagation()}
        className="vn-panel max-h-[85vh] w-full max-w-lg overflow-y-auto px-6 py-6 md:px-8"
      >
        {/* Header */}
        <div className="mb-5 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Users size={16} className="text-blood-bright" />
            <span className="font-mono text-xs uppercase tracking-[0.4em] text-blood-bright">
              The Cast
            </span>
          </div>
          <button
            onClick={onClose}
            className="text-muted transition-colors hover:text-bone"
            aria-label="Close"
          >
            <X size={18} />
          </button>
        </div>

        {/* Character entries */}
        <div className="flex flex-col gap-3">
          {ORDER.map((id, i) => {
            const c = CHARACTERS[id];
            if (!c) return null;
            const isTrustNpc = TRUST_NPCS.includes(id);
            const trustVal = trust[id] ?? 0;
            const desc = getDescription(id, c.description);
            const isDestroyed = destroyedProfiles.includes(id);
            const remembers = rememberedDestruction.includes(id);
            const canDestroy = DESTRUCTIBLE.includes(id) && !isDestroyed;
            const isConfirming = confirmId === id;

            return (
              <motion.div
                key={id}
                initial={{ opacity: 0, x: -12 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: i * 0.06, duration: 0.3 }}
                className={[
                  'border-l-2 pl-4 py-2 relative',
                  isDestroyed ? 'border-blood-bright/80' : '',
                ].join(' ')}
                style={{ borderColor: isDestroyed ? undefined : `${c.color}66` }}
              >
                <div className="flex items-baseline justify-between gap-3">
                  <div className="flex items-baseline gap-2">
                    <span
                      className={[
                        'font-serif text-base font-semibold',
                        isDestroyed ? 'text-blood-bright/60 animate-glitch-skew line-through' : '',
                      ].join(' ')}
                      style={{ color: isDestroyed ? undefined : c.color }}
                    >
                      {c.name}
                    </span>
                    <span className="font-mono text-[9px] uppercase tracking-[0.25em] text-muted">
                      {c.role}
                    </span>
                  </div>
                  {/* Trust meter for NPCs the player can influence */}
                  {isTrustNpc && (
                    <div className="flex items-center gap-1.5">
                      <span className="font-mono text-[10px] uppercase tracking-wider text-muted">
                        Trust
                      </span>
                      <div className="flex gap-[2px]">
                        {Array.from({ length: 5 }).map((_, p) => (
                          <span
                            key={p}
                            className="h-[6px] w-[6px] rounded-full transition-all"
                            style={{
                              backgroundColor:
                                p < Math.round((trustVal + 50) / 20)
                                  ? c.color
                                  : 'rgba(100,100,110,0.25)',
                              boxShadow:
                                p < Math.round((trustVal + 50) / 20)
                                  ? `0 0 4px ${c.color}88`
                                  : 'none',
                            }}
                          />
                        ))}
                      </div>
                      <span className="font-mono text-[10px] tabular-nums text-bone/60">
                        {trustVal > 0 ? `+${trustVal}` : trustVal}
                      </span>
                    </div>
                  )}
                </div>
                {desc && !isDestroyed && (
                  <p className="mt-1 font-serif text-sm italic leading-relaxed text-bone/70">
                    {desc}
                  </p>
                )}
                {/* Appearance dossier — gender / age / origin + physical
                    description. Only for characters with a profile (excludes
                    narrator; system shows only its nature). Rendered as a
                    small dossier card so the cast reads as people with
                    bodies, not just names with a colour. */}
                {!isDestroyed && (c.hair || c.build || c.features) && (
                  <div className="mt-2 border-l border-blood/30 pl-3">
                    {(c.origin || c.age || c.gender) && (
                      <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-muted">
                        {[
                          c.origin,
                          c.age && `${c.age}`,
                          c.gender && c.gender !== 'ambiguous' ? c.gender : null,
                        ]
                          .filter(Boolean)
                          .join(' · ')}
                      </p>
                    )}
                    {c.hair && (
                      <p className="mt-1 font-serif text-xs leading-snug text-bone/55">
                        <span className="text-muted">Hair</span> — {c.hair}
                      </p>
                    )}
                    {c.build && (
                      <p className="font-serif text-xs leading-snug text-bone/55">
                        <span className="text-muted">Build</span> — {c.build}
                      </p>
                    )}
                    {c.features && (
                      <p className="font-serif text-xs leading-snug text-bone/55">
                        <span className="text-muted">Marks</span> — {c.features}
                      </p>
                    )}
                    {c.clothing && (
                      <p className="font-serif text-xs leading-snug text-bone/55">
                        <span className="text-muted">Wears</span> — {c.clothing}
                      </p>
                    )}
                    {c.gesture && (
                      <p className="mt-1 font-serif text-xs italic leading-snug text-blood-bright/55">
                        {c.gesture}.
                      </p>
                    )}
                  </div>
                )}
                {/* Remembers-destruction note: the character was once
                    destroyed and restored. They know. Surfaced only when
                    the file is currently intact (destroyed state has its
                    own corrupted-file message above). */}
                {remembers && !isDestroyed && (
                  <p className="mt-1 flex items-center gap-1.5 font-mono text-[9px] uppercase tracking-[0.2em] text-blood-bright/70 animate-glitch-skew">
                    <AlertTriangle size={9} className="shrink-0" />
                    they remember what you tried to erase
                  </p>
                )}
                {/* Destroyed state — the profile reads as a corrupted file. */}
                {isDestroyed && (
                  <p className="mt-1 font-mono text-xs text-blood-bright/60">
                    [file corrupted — awaiting repair]
                  </p>
                )}
                {/* Destroy action — a small, deliberately uncomfortable
                    button. Confirmation is inline (two clicks) so it's not
                    accidental, but the path is short to preserve the
                    impulse-driven nature of DDLC's deletion moment. */}
                {canDestroy && !isConfirming && (
                  <button
                    onClick={() => setConfirmId(id)}
                    className="mt-1.5 flex items-center gap-1 font-mono text-[8px] uppercase tracking-[0.25em] text-muted/40 transition-colors hover:text-blood-bright"
                    aria-label={`Destroy ${c.name}'s file`}
                  >
                    <FileX2 size={9} /> destroy file
                  </button>
                )}
                <AnimatePresence>
                  {isConfirming && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      exit={{ opacity: 0, height: 0 }}
                      className="mt-2 flex items-center gap-2 border border-blood/40 bg-blood/5 px-2.5 py-1.5"
                    >
                      <AlertTriangle size={10} className="shrink-0 text-blood-bright animate-pulse" />
                      <span className="font-mono text-[9px] uppercase tracking-[0.2em] text-blood-bright/80">
                        delete {c.name}.chr?
                      </span>
                      <button
                        onClick={() => setConfirmId(null)}
                        className="ml-auto font-mono text-[9px] uppercase tracking-wider text-muted hover:text-bone"
                      >
                        no
                      </button>
                      <button
                        onClick={() => {
                          setConfirmId(null);
                          audio.playSFX('death');
                          destroyProfile(id);
                          onDestroy?.(id);
                        }}
                        className="font-mono text-[9px] uppercase tracking-wider text-blood-bright hover:text-white"
                      >
                        erase
                      </button>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            );
          })}
        </div>

        {/* Footer hint */}
        <p className="mt-5 text-center font-mono text-[9px] uppercase tracking-[0.3em] text-muted/50">
          Some truths reveal only as you learn more.
        </p>
      </motion.div>
    </motion.div>
  );
}
